local DragLabel = Instance.new("TextLabel")
DragLabel.Name = "DragLabel"
DragLabel.Text = "HOLD TO DRAG"
DragLabel.Size = UDim2.new(0, 100, 0, 20)
DragLabel.Position = UDim2.new(1, -390, 5, -125) -- Aligned relative to the Stop Button
