-- [DRAGGING SYSTEM VARIABLES]
local isDraggingUI = false
local dragInput, dragStart, startPos

local function updatePosition(input)
	local delta = input.Position - dragStart
	MainFrame.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X, startPos.Y.Scale, startPos.Y.Offset + delta.Y)
end

-- Input Handling for DragLabel
DragLabel.InputBegan:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
		isDraggingUI = true
		dragStart = input.Position
		startPos = MainFrame.Position
		DragLabel.TextColor3 = THEME.Accent

		input.Changed:Connect(function()
			if input.UserInputState == Enum.UserInputState.End then
				isDraggingUI = false
				DragLabel.TextColor3 = Color3.fromRGB(0, 0, 0)
			end
		end)
	end
end)

UserInputService.InputChanged:Connect(function(input)
	if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
		dragInput = input
	end
end)

local function ResetActiveButton()
	if currentPlayingAnim and buttonsMap[currentPlayingAnim] then
		local btn = buttonsMap[currentPlayingAnim]
		TweenService:Create(btn, TweenInfo.new(0.3), {BackgroundColor3 = THEME.ItemBg}):Play()
		if btn:FindFirstChild("UIStroke") then
			TweenService:Create(btn.UIStroke, TweenInfo.new(0.3), {Transparency = 1}):Play()
		end
		if btn:FindFirstChild("Title") then
			TweenService:Create(btn.Title, TweenInfo.new(0.3), {TextColor3 = Color3.fromRGB(180, 180, 180)}):Play()
		end
	end
	currentPlayingAnim = nil
end

local function UpdateSlider(input)
	local relativeX = input.Position.X - SliderBg.AbsolutePosition.X
	local percent = math.clamp(relativeX / SliderBg.AbsoluteSize.X, 0, 1)
	local newSpeed = math.floor((percent * 5) * 10) / 10
	currentSpeed = newSpeed

	TweenService:Create(SliderFill, TweenInfo.new(0.1), {Size = UDim2.new(percent, 0, 1, 0)}):Play()
	SpeedLabel.Text = string.format("SPEED %.1f", currentSpeed)
	AnimSpeedRemote:InvokeServer(currentSpeed)
end

local function CreateButton(data, index)
	if ScrollContainer:FindFirstChild(data.Name) then return end
	local ButtonFrame = Instance.new("TextButton")
	ButtonFrame.Name = data.Name
	ButtonFrame.Size = UDim2.new(0, 65, 0, 65)
	ButtonFrame.BackgroundColor3 = THEME.ItemBg
	ButtonFrame.Text = ""
	ButtonFrame.AutoButtonColor = false
	ButtonFrame.LayoutOrder = index
	ButtonFrame.Parent = ScrollContainer

	local Corner = Instance.new("UICorner")
	Corner.CornerRadius = UDim.new(0, 12)
	Corner.Parent = ButtonFrame

	local Stroke = Instance.new("UIStroke")
	Stroke.Color = THEME.Accent
	Stroke.Thickness = 2
	Stroke.Transparency = 1
	Stroke.Parent = ButtonFrame
	buttonsMap[data.Name] = ButtonFrame

	local Label = Instance.new("TextLabel")
	Label.Name = "Title"
	Label.Text = string.upper(data.Name)
	Label.Size = UDim2.new(1, -10, 1, -10)
	Label.Position = UDim2.new(0, 5, 0, 5)
	Label.BackgroundTransparency = 1
	Label.TextColor3 = Color3.fromRGB(180, 180, 180)
	Label.Font = Enum.Font.GothamBold
	Label.TextScaled = true 
	Label.TextWrapped = true
	Label.Parent = ButtonFrame

	ButtonFrame.MouseButton1Click:Connect(function()
		local character = LocalPlayer.Character
		local humanoid = character and character:FindFirstChild("Humanoid")
		if not humanoid then return end

		if currentPlayingAnim == data.Name then
			StopAnimRemote:FireServer(humanoid)
			ResetActiveButton()
			return
		end

		ResetActiveButton()
		PlayAnimRemote:InvokeServer(data.Name, character, false, nil)
		currentPlayingAnim = data.Name
		TweenService:Create(ButtonFrame, TweenInfo.new(0.3), {BackgroundColor3 = Color3.fromRGB(40, 50, 45)}):Play()
		TweenService:Create(Stroke, TweenInfo.new(0.3), {Transparency = 0}):Play()

		task.wait(0.1)
		AnimSpeedRemote:InvokeServer(currentSpeed)
	end)
end

for i, anim in ipairs(ANIMATION_PRESETS) do CreateButton(anim, i) end

-- Slider Input Listeners
SliderBtn.MouseButton1Down:Connect(function() isSliderDragging = true end)
UserInputService.InputEnded:Connect(function(input) 
	if input.UserInputType == Enum.UserInputType.MouseButton1 then isSliderDragging = false end 
end)

UserInputService.InputChanged:Connect(function(input) 
	if isSliderDragging and input.UserInputType == Enum.UserInputType.MouseMovement then 
		UpdateSlider(input) 
	elseif isDraggingUI and input.UserInputType == Enum.UserInputType.MouseMovement then
		updatePosition(input)
	end 
end)

StopButton.MouseButton1Click:Connect(function()
	local character = LocalPlayer.Character
	local humanoid = character and character:FindFirstChild("Humanoid")
	if humanoid then
		StopAnimRemote:FireServer(humanoid)
		ResetActiveButton()
		local t = TweenService:Create(StopButton, TweenInfo.new(0.1), {BackgroundColor3 = THEME.Stop, TextColor3 = Color3.fromRGB(255,255,255)})
		t:Play()
		task.wait(0.15)
		TweenService:Create(StopButton, TweenInfo.new(0.3), {BackgroundColor3 = Color3.fromRGB(45, 30, 30), TextColor3 = THEME.Stop}):Play()
	end
end)

UserInputService.InputBegan:Connect(function(input, gameProcessed)
	if gameProcessed then return end
	if input.KeyCode == TOGGLE_KEY then
		isOpen = not isOpen
		MainFrame.Visible = isOpen
	end
end)
