-- ── Toggle button (small icon tab, tweens in on hover) ────────
UI.toggleButton.MouseButton1Click:Connect(function()
	local opening = not UI.mainPanel.Visible

	if opening then
		UI.openBurstScale:Play()
		UI.openBurstGlow:Play()
		UI.openBurstText:Play()

		task.delay(0.20, function()
			-- Hide the toggle button while the editor is open
			UI.toggleButton.Visible = false

			-- Prepare the panel at the toggle location, then animate it open
			UI.mainScale.Scale = 0.05
			UI.mainPanel.Position = UDim2.new(1, UI.VISIBLE_OFFSET - (UI.mainPanel.AbsoluteSize.X/2 or 400), 0.38, 0)
			UI.mainPanel.Visible = true

			UI.panelOpenScale:Play()
			UI.panelOpenPos:Play()

			local liveChar = workspace:FindFirstChild(player.Name) or player.Character
			if liveChar then
				table.clear(State.modifications)
				UI.searchBox.Text = ""
				State.filterText  = ""
				table.clear(State.edExpanded)
				State.globalHumanoidScale = liveChar:GetScale()
				EditorLogic.setHighlight(nil)
				EditorLogic.setActiveTab("editor")
				EditorLogic.setupCharacter(liveChar, false)
				if State.syncConnection then State.syncConnection:Disconnect() end
				State.syncConnection = liveChar.DescendantAdded:Connect(function()
					task.wait(0.1)
					EditorLogic.setupCharacter(liveChar, true)
				end)
			end
			MorphsLogic.setActiveCategory(1)
			task.spawn(function()
				State.equipRemote = ReplicatedStorage:WaitForChild("EquipMorph", 10)
			end)
			PresetsLogic.refresh()
		end)
	else
		-- Closing via toggle (shouldn't normally happen since button is hidden, but keep as fallback)
		-- Play the minimize animation
		UI.panelCloseScale:Play()
		UI.panelClosePos:Play()

		task.delay(0.35, function()
			UI.mainPanel.Visible = false
		end)

		UI.closeShrinkScale:Play()
		UI.closeShrinkGlow:Play()
		UI.closeShrinkText:Play()
		UI.toggleButton.Visible = true
		UI.toggleTweenOut:Play()
		if State.syncConnection then State.syncConnection:Disconnect(); State.syncConnection = nil end
		if ColorPicker.panel then ColorPicker.panel.Visible = false end
	end
end)

-- ── Close button (X on the main panel) ───────────────────────
