local Player = Players.LocalPlayer

local FadeInfo = TweenInfo.new(0.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)

local function getFaderFrame()
	local pGui = Player:FindFirstChild("PlayerGui")
	return (pGui and pGui:FindFirstChild("Fader")) and pGui.Fader:FindFirstChild("BlackFrame") or nil
end

local function setFrozen(frozen)
	local char = Player.Character
	if char then
		local hrp = char:FindFirstChild("HumanoidRootPart")
		if hrp then
			hrp.Anchored = frozen
			if frozen then
				hrp.AssemblyLinearVelocity = Vector3.zero
				hrp.AssemblyAngularVelocity = Vector3.zero
			end
		end
	end
end

local function onServerRequest(action)
	local fader = getFaderFrame()
	if not fader then return end

	if action == "FadeOut" then
		setFrozen(true)

		fader.Visible = true
		fader.BackgroundTransparency = 1
		TweenService:Create(fader, FadeInfo, {BackgroundTransparency = 0}):Play()

	elseif action == "FadeIn" then
		setFrozen(true)

		if not game:IsLoaded() then
			game.Loaded:Wait()
		end

		pcall(function()
			local char = Player.Character
			if char and char:FindFirstChild("HumanoidRootPart") then
				Player:RequestStreamAroundAsync(char.HumanoidRootPart.Position)
			end
		end)

		task.wait(1.5)

		setFrozen(false)

		local t = TweenService:Create(fader, FadeInfo, {BackgroundTransparency = 1})
		t:Play()

		t.Completed:Wait()
		fader.Visible = false
	end
end

