local LocalSoundEvent = ReplicatedStorage:WaitForChild("LocalSoundEvent")
local RS_Sounds = ReplicatedStorage:WaitForChild("Sounds", 10) or ReplicatedStorage

local function PlayWetSounds(targetChar, intensity)
	if not targetChar then return end
	local rootPart = targetChar:FindFirstChild("HumanoidRootPart")
	if not rootPart then return end

	local s1Name, s2Name, repeats, delayTime, volDecay
	if intensity == "Soft" then
		s1Name, s2Name, repeats, delayTime, volDecay = "3", "4", 4, 0.9, 0.1
	else
		s1Name, s2Name, repeats, delayTime, volDecay = "1", "2", 5, 1.1, 0.3
	end

	local Sound1 = RS_Sounds.Wet:FindFirstChild(s1Name)
	local Sound2 = RS_Sounds.Wet:FindFirstChild(s2Name)

	if not Sound1 or not Sound2 then return end

	local attach1 = Sound1:Clone()
	attach1.Parent = rootPart

	local attach2 = Sound2:Clone()
	attach2.Parent = rootPart
	attach2:Play()
	Debris:AddItem(attach2, attach2.TimeLength + 1)

	task.spawn(function()
		local currentVolume = attach1.Volume
		for i = 1, repeats do
			if not rootPart or not rootPart.Parent then break end
			local clonedSound = attach1:Clone()
			clonedSound.Volume = currentVolume
			clonedSound.Parent = rootPart
			clonedSound:Play()
			Debris:AddItem(clonedSound, clonedSound.TimeLength + 1)
			task.wait(delayTime)
			currentVolume = currentVolume - volDecay
		end
		if attach1 then attach1:Destroy() end
	end)
end

local function PlayPlap(targetChar, soundName)
	if not targetChar then return end
	local root = targetChar:FindFirstChild("HumanoidRootPart")
	if not root then return end

	local sexFolder = root:FindFirstChild("Sex")
	if not sexFolder then return end

	local sounds = {}
	for _, v in pairs(sexFolder:GetChildren()) do
		if v:IsA("Sound") and v.Name == soundName then 
			table.insert(sounds, v) 
		end
	end

	if #sounds > 0 then
		local ran = sounds[math.random(1, #sounds)]
		local clone = ran:Clone()
		clone.Parent = root
		clone:Play()
		Debris:AddItem(clone, clone.TimeLength + 1)
	end
end

local function PlayMoan(targetChar)
	if not targetChar then return end
	local root = targetChar:FindFirstChild("HumanoidRootPart")
	if not root then return end

	local moanFolder = root:FindFirstChild("Moan")
	if not moanFolder then return end

	local moans = {}
	for _, v in pairs(moanFolder:GetChildren()) do
		if v:IsA("Sound") and v.Name == "Moan" then 
			table.insert(moans, v) 
		end
	end

	if #moans > 0 then
		local new = moans[math.random(1, #moans)]
		local new2 = new:Clone()
		new2.Parent = root
		new2:Play()
		Debris:AddItem(new2, new2.TimeLength + 1)
	end
end

LocalSoundEvent.OnClientEvent:Connect(function(category, arg1, arg2)
	if category == "Wet" then
		PlayWetSounds(arg2, arg1)
	elseif category == "Plap" then
		PlayPlap(arg2, arg1)
	elseif category == "Moan" then
		PlayMoan(arg2)
	end
end)local ReplicatedStorage = game:GetService('ReplicatedStorage')

local Remote = ReplicatedStorage:WaitForChild("CumEvent")
-- The module returns (function, ignoreParams). We call it () to get them.
local Nut = require(ReplicatedStorage:WaitForChild("CumModule"))()

Remote.OnClientEvent:Connect(function(origin, vel, ignoreSource, settings)
	local params = RaycastParams.new()
	params.FilterType = Enum.RaycastFilterType.Exclude
	params.RespectCanCollide = true

	-- Construct the filter list
	-- ignoreSource might be an Instance (Character), a table of Instances, or nil
	local filter = {}

	if typeof(ignoreSource) == "Instance" then
		filter = {ignoreSource}
	elseif typeof(ignoreSource) == "table" then
		-- Handle if it's a list or a RaycastParams object wrapper
		if ignoreSource.FilterDescendantsInstances then
			filter = ignoreSource.FilterDescendantsInstances
		else
			filter = ignoreSource
		end
	end

	params.FilterDescendantsInstances = filter

	-- Pass the correct params and settings to the module
	Nut(origin, vel, params, settings)
end)local uis = game:GetService("UserInputService")

