function freezePlayer(freeze)
	local char = player.Character
	if char and char:FindFirstChild("Humanoid") then
		local hum = char.Humanoid
		local hrp = char:FindFirstChild("HumanoidRootPart")

		if freeze then
			oldWalkSpeed = hum.WalkSpeed
			oldJumpPower = hum.JumpPower
			oldAutoRotate = hum.AutoRotate

			hum.WalkSpeed = 0
			hum.JumpPower = 0
			hum.AutoRotate = false

			if hrp then hrp.Anchored = true end
		else
			hum.WalkSpeed = oldWalkSpeed
			hum.JumpPower = oldJumpPower
			hum.AutoRotate = oldAutoRotate

			if hrp then hrp.Anchored = false end
		end
	end
end

function toggleGuis(shouldHide)
	if shouldHide then
		pcall(function()
			StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.All, false)
		end)

		hiddenGuis = {}
		local playerGui = player:WaitForChild("PlayerGui")
		for _, gui in pairs(playerGui:GetChildren()) do
			if gui:IsA("ScreenGui") and gui.Enabled then
				hiddenGuis[gui] = true
				gui.Enabled = false
			end
		end
	else

		pcall(function()
			StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.All, true)
		end)

		for gui, _ in pairs(hiddenGuis) do
			if gui and gui.Parent then
				gui.Enabled = true
			end
		end
		hiddenGuis = {}
	end
end

function enableFreecam()
	camera.CameraType = Enum.CameraType.Scriptable
	UserInputService.MouseBehavior = Enum.MouseBehavior.LockCenter
	UserInputService.MouseIconEnabled = false

	currentPos = camera.CFrame.Position
	currentFOV = camera.FieldOfView
	targetFOV = currentFOV
	currentVelocity = Vector3.new(0,0,0)

	dofEffect.Enabled = true
	targetFocusDist = 50
	currentFocusDist = 50
	dofEffect.FocusDistance = 50

	local lookVector = camera.CFrame.LookVector
	currentRot = Vector2.new(math.atan2(-lookVector.X, -lookVector.Z), math.asin(lookVector.Y))

	currentRoll = 0
	targetRoll = 0

	freezePlayer(true)
	toggleGuis(true)
end

function disableFreecam()
	camera.CameraType = Enum.CameraType.Custom
	UserInputService.MouseBehavior = Enum.MouseBehavior.Default
	UserInputService.MouseIconEnabled = true -- SHOW CURSOR
	camera.FieldOfView = 70
	dofEffect.Enabled = false
	freezePlayer(false)
	toggleGuis(false)
end


UserInputService.InputChanged:Connect(function(input)
	if enabled and input.UserInputType == Enum.UserInputType.MouseMovement then
		local delta = input.Delta
		currentRot = currentRot - Vector2.new(delta.X * math.rad(MOUSE_SENSITIVITY), delta.Y * math.rad(MOUSE_SENSITIVITY))
		currentRot = Vector2.new(currentRot.X, math.clamp(currentRot.Y, math.rad(-89), math.rad(89)))
	end
end)

--physics loop
RunService.RenderStepped:Connect(function(deltaTime)
	if not enabled then return end

	-- FOV handler
	if pressedKeys[Enum.KeyCode.Z] then
		targetFOV = math.clamp(targetFOV - FOV_SPEED, 5, 120)
	elseif pressedKeys[Enum.KeyCode.X] then
		targetFOV = math.clamp(targetFOV + FOV_SPEED, 5, 120)
	end
	currentFOV = currentFOV + (targetFOV - currentFOV) * 0.1

	-- Tilt handler
	if pressedKeys[Enum.KeyCode.Q] then
		targetRoll = targetRoll + math.rad(TILT_SPEED)
	elseif pressedKeys[Enum.KeyCode.E] then
		targetRoll = targetRoll - math.rad(TILT_SPEED)
	end
	currentRoll = currentRoll + (targetRoll - currentRoll) * 0.1

	-- DOF handler
	if pressedKeys[Enum.KeyCode.C] then
		targetFocusDist = math.max(0, targetFocusDist - DOF_SPEED)
	elseif pressedKeys[Enum.KeyCode.V] then
		targetFocusDist = targetFocusDist + DOF_SPEED
	end

	currentFocusDist = currentFocusDist + (targetFocusDist - currentFocusDist) * 0.1
	dofEffect.FocusDistance = currentFocusDist

	local rotationCFrame = CFrame.fromEulerAnglesYXZ(currentRot.Y, currentRot.X, currentRoll)

	local inputVector = Vector3.new()
	if pressedKeys[Enum.KeyCode.W] then inputVector = inputVector + Vector3.new(0, 0, -1) end
	if pressedKeys[Enum.KeyCode.S] then inputVector = inputVector + Vector3.new(0, 0, 1) end
	if pressedKeys[Enum.KeyCode.A] then inputVector = inputVector + Vector3.new(-1, 0, 0) end
	if pressedKeys[Enum.KeyCode.D] then inputVector = inputVector + Vector3.new(1, 0, 0) end

	local speedMult = 1
	if pressedKeys[Enum.KeyCode.LeftShift] then speedMult = 4 end 

	local targetVelocity = Vector3.new()
	if inputVector.Magnitude > 0 then
		targetVelocity = rotationCFrame:VectorToWorldSpace(inputVector.Unit * MAX_SPEED * speedMult)
	end

	currentVelocity = currentVelocity:Lerp(targetVelocity, inputVector.Magnitude > 0 and ACCELERATION or DECELERATION)
	currentPos = currentPos + currentVelocity

	camera.FieldOfView = currentFOV
	camera.CFrame = CFrame.new(currentPos) * rotationCFrame
end)local Players = game:GetService("Players")
