-- Slider Logic
-- -------------------------------------------------------------------------
local function connectSlider(sliderName, attr, min, max, isDecimal)
	local container = settingsPage:FindFirstChild("Slider_" .. sliderName)
	if not container then return end

	local valLabel = container:FindFirstChild("ValueLabel")
	local slideBg = container:FindFirstChild("SlideBg")
	local fill = slideBg:FindFirstChild("Fill")
	local trigger = slideBg:FindFirstChild("Trigger")

	local function updateVisuals()
		local current = screenGui:GetAttribute(attr) or min
		valLabel.Text = tostring(current)
		local ratio = math.clamp((current - min)/(max-min), 0, 1)
		fill.Size = UDim2.new(ratio, 0, 1, 0)
	end

	local dragging = false
	local function updateInput(input)
		local x = math.clamp((input.Position.X - slideBg.AbsolutePosition.X)/slideBg.AbsoluteSize.X, 0, 1)
		local raw = min + (max-min)*x
		local val = isDecimal and math.floor(raw*100)/100 or math.floor(raw+0.5)
		screenGui:SetAttribute(attr, val)
		updateVisuals()
	end

	trigger.MouseButton1Down:Connect(function() dragging = true end)
	UserInputService.InputEnded:Connect(function(input) 
		if input.UserInputType == Enum.UserInputType.MouseButton1 then dragging = false end 
	end)
	UserInputService.InputChanged:Connect(function(input) 
		if dragging and input.UserInputType == Enum.UserInputType.MouseMovement then updateInput(input) end 
	end)
	trigger.MouseButton1Down:Connect(function() 
		updateInput({Position = UserInputService:GetMouseLocation()}) 
	end)

	updateVisuals()
end

connectSlider("Amount", "Amount", 1, 8, false)
connectSlider("Size", "Size", 0.01, 0.12, true)
connectSlider("Lifetime", "Lifetime", 1, 20, false)

