local hexBox = colFrame:FindFirstChild("HexInput")
local rgbBox = colFrame:FindFirstChild("RGBInput")

local sliders = {
	{name="R", slider=colFrame.Slider_R},
	{name="G", slider=colFrame.Slider_G},
	{name="B", slider=colFrame.Slider_B}
}

local function updateColorUI(col, source)
	screenGui:SetAttribute("Color", col)
	preview.BackgroundColor3 = col

	if source ~= "Hex" then hexBox.Text = "#"..col:ToHex():upper() end
	if source ~= "RGB" then rgbBox.Text = string.format("%d, %d, %d", col.R*255, col.G*255, col.B*255) end

	if source ~= "Slider" then
		for _, s in ipairs(sliders) do
			local comp = (s.name == "R" and col.R) or (s.name == "G" and col.G) or col.B
			s.slider.Fill.Size = UDim2.new(comp, 0, 1, 0)
		end
	end
end

local function connectColSlider(data)
	local container = data.slider
	local trigger = container:FindFirstChild("Trigger")
	local dragging = false

	local function update(input)
		local x = math.clamp((input.Position.X - container.AbsolutePosition.X)/container.AbsoluteSize.X, 0, 1)
		container.Fill.Size = UDim2.new(x, 0, 1, 0)

		local cur = screenGui:GetAttribute("Color")
		local r,g,b = cur.R, cur.G, cur.B
		if data.name == "R" then r = x elseif data.name == "G" then g = x else b = x end
		updateColorUI(Color3.new(r,g,b), "Slider")
	end

	trigger.MouseButton1Down:Connect(function() dragging = true end)
	UserInputService.InputEnded:Connect(function(i) if i.UserInputType == Enum.UserInputType.MouseButton1 then dragging = false end end)
	UserInputService.InputChanged:Connect(function(i) if dragging and i.UserInputType == Enum.UserInputType.MouseMovement then update(i) end end)
	trigger.MouseButton1Down:Connect(function() update({Position = UserInputService:GetMouseLocation()}) end)
end

for _, s in ipairs(sliders) do connectColSlider(s) end

hexBox.FocusLost:Connect(function()
