local function switchPage(toMaterial)
	if toMaterial then
		materialPage.Visible = true
		TweenService:Create(settingsPage, TweenInfo.new(0.3, Enum.EasingStyle.Quad), {Position = UDim2.new(-1, 0, 0, 5)}):Play()
		TweenService:Create(materialPage, TweenInfo.new(0.3, Enum.EasingStyle.Quad), {Position = UDim2.new(0, 0, 0, 0)}):Play()
	else
		TweenService:Create(settingsPage, TweenInfo.new(0.3, Enum.EasingStyle.Quad), {Position = UDim2.new(0, 5, 0, 5)}):Play()
		local t = TweenService:Create(materialPage, TweenInfo.new(0.3, Enum.EasingStyle.Quad), {Position = UDim2.new(1, 0, 0, 0)})
		t:Play()
		t.Completed:Connect(function() materialPage.Visible = false end)
	end
end

