local function autoFrameMorphCam()
	local parts={}
	for _,d in ipairs(_ui.morphWorldModel:GetDescendants()) do
		if d:IsA("BasePart") and d.Transparency<0.9 then table.insert(parts,d) end
	end
	if #parts==0 then
		_state.moOrbitCenter=Vector3.new(0,2,0); _state.moOrbitDist=8; _state.moOrbitY=180; _state.moOrbitX=-15
		_editorLogic.updateMorphCam(); return
	end
	local mn,mx=parts[1].Position,parts[1].Position
	for _,p in ipairs(parts) do
		local s=p.Size*0.5
		mn=Vector3.new(math.min(mn.X,p.Position.X-s.X),math.min(mn.Y,p.Position.Y-s.Y),math.min(mn.Z,p.Position.Z-s.Z))
		mx=Vector3.new(math.max(mx.X,p.Position.X+s.X),math.max(mx.Y,p.Position.Y+s.Y),math.max(mx.Z,p.Position.Z+s.Z))
	end
	_state.moOrbitCenter=(mn+mx)*0.5; _state.moOrbitDist=math.max((mx-mn).Magnitude*1.3,3)
	_state.moOrbitY=180; _state.moOrbitX=-15; _editorLogic.updateMorphCam()
end

local function previewMorph(morphModel)
	for _,ch in ipairs(_ui.morphWorldModel:GetChildren()) do ch:Destroy() end
	_ui.morphNoPreview.Visible=true
	if not morphModel then return end
	local clone=morphModel:Clone()
	for _,d in ipairs(clone:GetDescendants()) do if d:IsA("BasePart") then d.Anchored=true; d.CanCollide=false end end
	clone.Parent=_ui.morphWorldModel; _ui.morphNoPreview.Visible=false; autoFrameMorphCam()
end

local function updateCheckboxes()
	local catStr=tostring(_state.currentCategory); local equippedName=_state.equippedMorphs[catStr]
	for inst,cb in pairs(_state.morphCheckboxMap) do
		local isEquipped=(equippedName==inst.Name)
		if isEquipped then cb.BackgroundColor3=Color3.fromRGB(46,204,113); cb.Text="✓"; cb.TextColor3=Color3.fromRGB(255,255,255)
		else cb.BackgroundColor3=Color3.fromRGB(40,40,50); cb.Text="" end
	end
end
