			_state.equipRemote=_state.equipRemote or ReplicatedStorage:FindFirstChild("EquipMorph")
			if not _state.equipRemote then warn("[CharacterEditor] EquipMorph RemoteEvent not found."); return end
			local cat=tostring(_state.currentCategory); local previousName=_state.equippedMorphs[cat]
			if previousName==inst.Name then _state.equippedMorphs[cat]=nil; _state.equipRemote:FireServer(cat,"Remove_"..inst.Name)
			else
				if previousName then _state.equipRemote:FireServer(cat,"Remove_"..previousName) end
				_state.equippedMorphs[cat]=inst.Name; _state.equipRemote:FireServer(cat,inst.Name)
			end; updateCheckboxes()
		end)
		btn.MouseEnter:Connect(function() if inst~=_state.selectedMorphModel then btn.BackgroundTransparency=0.82; btn.BackgroundColor3=Color3.fromRGB(30,30,46) end end)
		btn.MouseLeave:Connect(function() if inst~=_state.selectedMorphModel then btn.BackgroundTransparency=1 end end)
		btn.MouseButton1Click:Connect(function()
			if _state.selectedMorphModel and _state.morphRowMap[_state.selectedMorphModel] then
				_state.morphRowMap[_state.selectedMorphModel].BackgroundTransparency=1
				local pl=_state.morphRowMap[_state.selectedMorphModel]:FindFirstChildWhichIsA("TextLabel")
				if pl then pl.TextColor3=Color3.fromRGB(200,200,220) end
			end
			_state.selectedMorphModel=inst; btn.BackgroundTransparency=0; btn.BackgroundColor3=Color3.fromRGB(80,0,160)
			if lbl then lbl.TextColor3=Color3.fromRGB(255,255,255) end; previewMorph(inst)
		end)
		if arrowBtn then arrowBtn.MouseButton1Click:Connect(function() _state.morphExpanded[inst]=not _state.morphExpanded[inst]; rebuildFn() end) end
	end
	if hasKids and (isOpen or searching) then
		for _,ch in ipairs(inst:GetChildren()) do buildMorphRow(ch,searching and 0 or depth+1,rebuildFn) end
	end
end

local function buildMorphTree(catFolder)
	for _,ch in ipairs(_ui.morphListScroll:GetChildren()) do if ch:IsA("TextButton") then ch:Destroy() end end
	_state.morphRowMap={}; _state.morphCheckboxMap={}; morphTreeOrder=0
	if not catFolder then task.defer(function() _ui.morphListScroll.CanvasSize=UDim2.new(0,0,0,0) end); return end
	local function rebuild() buildMorphTree(catFolder) end
	local children=catFolder:GetChildren()
	table.sort(children,function(a,b) return a.Name:lower()<b.Name:lower() end)
	for _,ch in ipairs(children) do buildMorphRow(ch,0,rebuild) end
	task.defer(function() _ui.morphListScroll.CanvasSize=UDim2.new(0,0,0,_ui.morphListLayout.AbsoluteContentSize.Y+6) end)
end

function MorphsLogic.setActiveCategory(num)
	_state.currentCategory=num
	for i,btn in ipairs(_ui.categoryButtons) do
		btn.BackgroundColor3=i==num and Color3.fromRGB(80,0,160) or Color3.fromRGB(25,25,32)
		btn.TextColor3=i==num and Color3.fromRGB(255,255,255) or Color3.fromRGB(130,130,150)
	end
	_ui.mListHdrLbl.Text="Morphs - "..(_state.catNames[num] or tostring(num))
	_state.selectedMorphModel=nil; _state.morphExpanded={}
	for _,ch in ipairs(_ui.morphWorldModel:GetChildren()) do ch:Destroy() end
	_ui.morphNoPreview.Visible=true
	_ui.morphSearchBox.Text=""; morphFilterText=""
	local morphsRoot=ReplicatedStorage:FindFirstChild("Morphs")
	local catFolder=morphsRoot and morphsRoot:FindFirstChild(tostring(num))
	buildMorphTree(catFolder)
end

function MorphsLogic._setupCategoryButtons()
	for i,btn in ipairs(_ui.categoryButtons) do
		local cap=i; btn.MouseButton1Click:Connect(function() MorphsLogic.setActiveCategory(cap) end)
	end
end

function MorphsLogic._setupMorphSearch()
	_ui.morphSearchBox:GetPropertyChangedSignal("Text"):Connect(function()
		morphFilterText=_ui.morphSearchBox.Text:lower()
		local morphsRoot=ReplicatedStorage:FindFirstChild("Morphs")
		local catFolder=morphsRoot and morphsRoot:FindFirstChild(tostring(_state.currentCategory))
		buildMorphTree(catFolder)
	end)
end

