local function cpHsv2Rgb(h,s,v)
	local i=math.floor(h*6)%6; local f=h*6-math.floor(h*6)
	local p,q,t=v*(1-s),v*(1-f*s),v*(1-(1-f)*s)
	if i==0 then return v,t,p elseif i==1 then return q,v,p elseif i==2 then return p,v,t
	elseif i==3 then return p,q,v elseif i==4 then return t,p,v else return v,p,q end
end
local function cpRgb2Hsv(r,g,b)
	local mx,mn=math.max(r,g,b),math.min(r,g,b); local d=mx-mn
	local h,s,v=0,mx==0 and 0 or d/mx,mx
	if d~=0 then
		if mx==r then h=((g-b)/d)%6 elseif mx==g then h=(b-r)/d+2 else h=(r-g)/d+4 end; h=h/6
	end; return h,s,v
end
local function cpRgb2Hsl(r,g,b)
	local mx,mn=math.max(r,g,b),math.min(r,g,b); local l=(mx+mn)/2; local h,s=0,0
	if mx~=mn then
		local d=mx-mn; s=l>0.5 and d/(2-mx-mn) or d/(mx+mn)
		if mx==r then h=((g-b)/d)%6 elseif mx==g then h=(b-r)/d+2 else h=(r-g)/d+4 end; h=h/6
	end; return h*360,s*100,l*100
end
local function cpHsl2Rgb(h,s,l)
	h,s,l=h/360,s/100,l/100
	if s==0 then return l,l,l end
	local function hq(p,q,t) t=t%1
		if t<1/6 then return p+(q-p)*6*t end; if t<0.5 then return q end
		if t<2/3 then return p+(q-p)*(2/3-t)*6 end; return p
	end
	local q=l<0.5 and l*(1+s) or l+s-l*s; local p=2*l-q
	return hq(p,q,h+1/3),hq(p,q,h),hq(p,q,h-1/3)
end
local function cpLin(c)    return c<=0.04045   and c/12.92           or ((c+0.055)/1.055)^2.4 end
local function cpLinInv(c) return c<=0.0031308 and 12.92*c           or 1.055*c^(1/2.4)-0.055 end
local function cpRgb2Oklch(r,g,b)
	local rl,gl,bl=cpLin(r),cpLin(g),cpLin(b)
	local l=(0.4122214708*rl+0.5363325363*gl+0.0514459929*bl)^(1/3)
	local m=(0.2119034982*rl+0.6806995451*gl+0.1073969566*bl)^(1/3)
	local s=(0.0883024619*rl+0.2817188376*gl+0.6299787005*bl)^(1/3)
	local L=0.2104542553*l+0.7936177850*m-0.0040720468*s
	local a=1.9779984951*l-2.4285922050*m+0.4505937099*s
	local bv=0.0259040371*l+0.7827717662*m-0.8086757660*s
	local C=math.sqrt(a*a+bv*bv); local H=math.deg(math.atan2(bv,a))
	return L*100,C*100,(H<0 and H+360 or H)
end
local function cpOklch2Rgb(L,C,H)
	L,C=L/100,C/100; local hr=math.rad(H); local a,bv=C*math.cos(hr),C*math.sin(hr)
	local lc=(L+0.3963377774*a+0.2158037573*bv)^3
	local mc=(L-0.1055613458*a-0.0638541728*bv)^3
	local sc=(L-0.0894841775*a-1.2914855480*bv)^3
	return math.clamp(cpLinInv( 4.0767416621*lc-3.3077115913*mc+0.2309699292*sc),0,1),
	math.clamp(cpLinInv(-1.2684380046*lc+2.6097574011*mc-0.3413193965*sc),0,1),
	math.clamp(cpLinInv(-0.0041960863*lc-0.7034186147*mc+1.7076147010*sc),0,1)
end
local function cpToHex(r,g,b)
	return string.format("%02X%02X%02X",
		math.clamp(math.floor(r*255+.5),0,255),
		math.clamp(math.floor(g*255+.5),0,255),
		math.clamp(math.floor(b*255+.5),0,255))
end
local function cpFromHex(s)
	s=s:gsub("#",""):upper()
	if #s==3 then s=s:sub(1,1):rep(2)..s:sub(2,2):rep(2)..s:sub(3,3):rep(2) end
	if #s~=6 then return nil end
	local rv,gv,bv=tonumber(s:sub(1,2),16),tonumber(s:sub(3,4),16),tonumber(s:sub(5,6),16)
	if not(rv and gv and bv) then return nil end
	return rv/255,gv/255,bv/255
end

