	hlFrame.ZIndex           = 201
	hlFrame.Visible          = false
	corner(hlFrame, 8)
	stroke(hlFrame, Color3.fromRGB(55,55,80), 1)

	local hlTitle = Instance.new("TextLabel", hlFrame)
	hlTitle.Size                = UDim2.new(1,-12,0,18)
	hlTitle.Position            = UDim2.new(0,8,0,6)
	hlTitle.BackgroundTransparency = 1
	hlTitle.Text                = "Highlight Settings"
	hlTitle.TextColor3          = Color3.fromRGB(180,180,220)
	hlTitle.Font                = Enum.Font.GothamBold
	hlTitle.TextSize            = 10
	hlTitle.TextXAlignment      = Enum.TextXAlignment.Left
	hlTitle.ZIndex              = 202

	-- Depth mode label
	local hlDepthLbl = Instance.new("TextLabel", hlFrame)
	hlDepthLbl.Size                = UDim2.new(0,82,0,18)
	hlDepthLbl.Position            = UDim2.new(0,8,0,28)
	hlDepthLbl.BackgroundTransparency = 1
	hlDepthLbl.Text                = "Depth Mode"
	hlDepthLbl.TextColor3          = Color3.fromRGB(135,135,158)
	hlDepthLbl.Font                = Enum.Font.GothamMedium
	hlDepthLbl.TextSize            = 9
	hlDepthLbl.ZIndex              = 202

	local function makeDepthBtn(label, xPos)
		local b = Instance.new("TextButton", hlFrame)
		b.Size             = UDim2.new(0, 88, 0, 18)
		b.Position         = UDim2.new(0, xPos, 0, 28)
		b.BackgroundColor3 = Color3.fromRGB(30,30,40)
		b.TextColor3       = Color3.fromRGB(160,160,185)
		b.Font             = Enum.Font.GothamBold
		b.TextSize         = 9
		b.Text             = label
		b.ZIndex           = 202
		corner(b, 4)
		return b
	end
	local hlOccludedBtn    = makeDepthBtn("Occluded",     92)
	local hlAlwaysOnTopBtn = makeDepthBtn("AlwaysOnTop", 184)

	-- mini slider helper
	local function makeHLSlider(parent, label, yPos, initVal, callback)
		local lbl = Instance.new("TextLabel", parent)
		lbl.Size                = UDim2.new(0,120,0,14)
		lbl.Position            = UDim2.new(0,8,0,yPos)
		lbl.BackgroundTransparency = 1
		lbl.Text                = label
		lbl.TextColor3          = Color3.fromRGB(135,135,158)
		lbl.Font                = Enum.Font.GothamMedium
		lbl.TextSize            = 9
		lbl.ZIndex              = 202

		local valLbl = Instance.new("TextLabel", parent)
		valLbl.Size                = UDim2.new(0,40,0,14)
		valLbl.Position            = UDim2.new(1,-48,0,yPos)
		valLbl.BackgroundTransparency = 1
		valLbl.Text                = string.format("%.2f", initVal)
		valLbl.TextColor3          = Color3.fromRGB(200,200,200)
		valLbl.Font                = Enum.Font.Code
		valLbl.TextSize            = 9
		valLbl.TextXAlignment      = Enum.TextXAlignment.Right
		valLbl.ZIndex              = 202

		local track = Instance.new("Frame", parent)
		track.Size             = UDim2.new(1,-20,0,4)
		track.Position         = UDim2.new(0,8,0,yPos + 16)
		track.BackgroundColor3 = Color3.fromRGB(35,35,50)
		track.ZIndex           = 202
		corner(track, 99)

		local fill = Instance.new("Frame", track)
		fill.Size             = UDim2.new(initVal,0,1,0)
		fill.BackgroundColor3 = Color3.fromRGB(100,100,200)
		fill.BorderSizePixel  = 0
		fill.ZIndex           = 203
		corner(fill, 99)

		local knob = Instance.new("TextButton", track)
		knob.Size             = UDim2.new(0,12,0,12)
		knob.AnchorPoint      = Vector2.new(0.5,0.5)
		knob.Position         = UDim2.new(initVal,0,0.5,0)
		knob.BackgroundColor3 = Color3.fromRGB(150,150,220)
		knob.Text             = ""
		knob.AutoButtonColor  = false
		knob.ZIndex           = 204
		corner(knob, 99)

		local dragging = false
		knob.MouseButton1Down:Connect(function() dragging = true end)
		local mc = UserInputService.InputChanged:Connect(function(i)
			if not dragging then return end
			if i.UserInputType ~= Enum.UserInputType.MouseMovement then return end
			local pct = math.clamp((i.Position.X - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1)
			knob.Position = UDim2.new(pct, 0, 0.5, 0)
			fill.Size     = UDim2.new(pct, 0, 1, 0)
			valLbl.Text   = string.format("%.2f", pct)
			callback(pct)
		end)
		local me = UserInputService.InputEnded:Connect(function(i)
			if i.UserInputType == Enum.UserInputType.MouseButton1 then dragging = false end
		end)
		track.Destroying:Connect(function() mc:Disconnect(); me:Disconnect() end)

		return function(val)
			local pct = math.clamp(val, 0, 1)
			knob.Position = UDim2.new(pct, 0, 0.5, 0)
			fill.Size     = UDim2.new(pct, 0, 1, 0)
			valLbl.Text   = string.format("%.2f", pct)
		end
	end

	local function applyHLToTargets()
		for _, p in ipairs(cpTargetParts) do
			if not (p and p.Parent) then continue end
			local hl = p:FindFirstChildWhichIsA("Highlight")
			if not hl then continue end
			hl.FillTransparency    = cpHlFillTrans
			hl.OutlineTransparency = cpHlOutlineTrans
			hl.DepthMode           = cpHlDepthMode
		end
	end

	local setHLFillTrans    = makeHLSlider(hlFrame, "Fill Transparency",    50, cpHlFillTrans,
		function(v) cpHlFillTrans    = v; applyHLToTargets() end)
	local setHLOutlineTrans = makeHLSlider(hlFrame, "Outline Transparency", 76, cpHlOutlineTrans,
		function(v) cpHlOutlineTrans = v; applyHLToTargets() end)

	local function refreshDepthBtns()
		local isOcc = (cpHlDepthMode == Enum.HighlightDepthMode.Occluded)
		hlOccludedBtn.BackgroundColor3    = isOcc     and Color3.fromRGB(60,60,160) or Color3.fromRGB(30,30,40)
		hlOccludedBtn.TextColor3          = isOcc     and Color3.fromRGB(255,255,255) or Color3.fromRGB(160,160,185)
		hlAlwaysOnTopBtn.BackgroundColor3 = not isOcc and Color3.fromRGB(60,60,160) or Color3.fromRGB(30,30,40)
		hlAlwaysOnTopBtn.TextColor3       = not isOcc and Color3.fromRGB(255,255,255) or Color3.fromRGB(160,160,185)
	end
	refreshDepthBtns()

	hlOccludedBtn.MouseButton1Click:Connect(function()
		cpHlDepthMode = Enum.HighlightDepthMode.Occluded
		refreshDepthBtns(); applyHLToTargets()
	end)
	hlAlwaysOnTopBtn.MouseButton1Click:Connect(function()
		cpHlDepthMode = Enum.HighlightDepthMode.AlwaysOnTop
		refreshDepthBtns(); applyHLToTargets()
	end)

	cpApplyToTargets = function(col)
		for _, p in ipairs(cpTargetParts) do
			if not (p and p.Parent) then continue end
			if cpPickerMode == "color" then
				p.Color = col
			else
				local hl = p:FindFirstChildWhichIsA("Highlight")
				if hl then hl.FillColor = col; hl.OutlineColor = col end
			end
		end
	end

	cpRefresh = function()
		local r,g,b = cpHsv2Rgb(cpH, cpS, cpV)
		local col   = Color3.new(r, g, b)
		cpSwatch.BackgroundColor3 = col
		cpHexLbl.Text             = "#" .. cpToHex(r, g, b)
		cpSvSq.BackgroundColor3   = Color3.fromHSV(cpH, 1, 1)
		cpCursor.Position         = UDim2.new(cpS, 0, 1 - cpV, 0)
		cpCurStr.Color            = cpV > 0.55 and Color3.new(0,0,0) or Color3.new(1,1,1)
		cpHueKnob.Position        = UDim2.new(cpH, 0, 0.5, 0)
		cpApplyToTargets(col)
		if cpNoUpdate then return end
		cpNoUpdate = true
		if cpInputMode == "HEX" then
			cpHexBox.Text = cpToHex(r, g, b)
		elseif cpInputMode == "RGB" then
			cpRBox.Text = tostring(math.clamp(math.floor(r*255+.5),0,255))
			cpGBox.Text = tostring(math.clamp(math.floor(g*255+.5),0,255))
			cpBBox.Text = tostring(math.clamp(math.floor(b*255+.5),0,255))
		elseif cpInputMode == "HSL" then
			local hh,ss,ll = cpRgb2Hsl(r,g,b)
			cpHslH.Text = string.format("%.0f",hh)
			cpHslS.Text = string.format("%.0f",ss)
			cpHslL.Text = string.format("%.0f",ll)
		elseif cpInputMode == "OKLCH" then
			local L,C,H = cpRgb2Oklch(r,g,b)
			cpOklL.Text = string.format("%.1f",L)
			cpOklC.Text = string.format("%.1f",C)
			cpOklH.Text = string.format("%.1f",H)
		end
		cpNoUpdate = false
	end

	cpSetTab = function(m)
		cpInputMode = m
		for n, tb in pairs(cpTabBtns) do
			tb.BackgroundColor3 = n == m and Color3.fromRGB(48,48,65) or Color3.fromRGB(20,20,26)
			tb.TextColor3       = n == m and Color3.fromRGB(220,220,240) or Color3.fromRGB(110,110,130)
		end
		for n, gr in pairs(CP_GROUPS) do gr.Visible = (n == m) end
		cpRefresh()
	end
	for _, m in ipairs(CP_MODES) do
		cpTabBtns[m].MouseButton1Click:Connect(function() cpSetTab(m) end)
	end

	-- SV drag
	local function cpSvRead()
		local ml  = UserInputService:GetMouseLocation()
		local ins = GuiService:GetGuiInset()
		cpS = math.clamp((ml.X - cpSvSq.AbsolutePosition.X) / cpSvSq.AbsoluteSize.X, 0, 1)
		cpV = 1 - math.clamp(((ml.Y - ins.Y) - cpSvSq.AbsolutePosition.Y) / cpSvSq.AbsoluteSize.Y, 0, 1)
		cpRefresh()
	end
	cpSvSq.InputBegan:Connect(function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 then cpDraggingSV = true; cpSvRead() end
	end)

	-- Hue drag
	local function cpHueRead()
		local ml = UserInputService:GetMouseLocation()
		cpH = math.clamp((ml.X - cpHueTrack.AbsolutePosition.X) / cpHueTrack.AbsoluteSize.X, 0, 1)
		cpRefresh()
	end
	cpHueTrack.InputBegan:Connect(function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 then cpDraggingHue = true; cpHueRead() end
	end)

	UserInputService.InputChanged:Connect(function(i)
		if i.UserInputType ~= Enum.UserInputType.MouseMovement then return end
		if cpDraggingSV  then cpSvRead()  end
		if cpDraggingHue then cpHueRead() end
	end)
	UserInputService.InputEnded:Connect(function(i)
		if i.UserInputType == Enum.UserInputType.MouseButton1 then
			cpDraggingSV = false; cpDraggingHue = false
		end
	end)

	local function cpFromInput()
		if cpNoUpdate then return end
		if cpInputMode == "HEX" then
			local r,g,b = cpFromHex(cpHexBox.Text)
			if r then cpH,cpS,cpV = cpRgb2Hsv(r,g,b); cpRefresh() end
		elseif cpInputMode == "RGB" then
			local r,g,b = tonumber(cpRBox.Text), tonumber(cpGBox.Text), tonumber(cpBBox.Text)
			if r and g and b then cpH,cpS,cpV = cpRgb2Hsv(r/255,g/255,b/255); cpRefresh() end
		elseif cpInputMode == "HSL" then
			local h,s,l = tonumber(cpHslH.Text), tonumber(cpHslS.Text), tonumber(cpHslL.Text)
			if h and s and l then
				local r,g,b = cpHsl2Rgb(math.clamp(h,0,360), math.clamp(s,0,100), math.clamp(l,0,100))
				cpH,cpS,cpV = cpRgb2Hsv(r,g,b); cpRefresh()
			end
		elseif cpInputMode == "OKLCH" then
			local L,C,H = tonumber(cpOklL.Text), tonumber(cpOklC.Text), tonumber(cpOklH.Text)
			if L and C and H then
				local r,g,b = cpOklch2Rgb(math.clamp(L,0,100), math.clamp(C,0,40), math.clamp(H,0,360))
				cpH,cpS,cpV = cpRgb2Hsv(r,g,b); cpRefresh()
			end
		end
	end
	for _, bx in ipairs({cpHexBox,cpRBox,cpGBox,cpBBox,cpHslH,cpHslS,cpHslL,cpOklL,cpOklC,cpOklH}) do
		bx.FocusLost:Connect(cpFromInput)
	end

	local function cpDoCancel()
		if cpPickerMode == "color" then
			for p, orig in pairs(cpOrigColors) do
				if p and p.Parent then p.Color = orig end
			end
		else
			for p, info in pairs(cpOrigHLs) do
				if not (p and p.Parent) then continue end
				local hl = p:FindFirstChildWhichIsA("Highlight")
				if info.wasNew then
					if hl then hl:Destroy() end
				elseif hl then
					hl.FillColor           = info.origFill
					hl.OutlineColor        = info.origOutline
					hl.FillTransparency    = info.origFillTrans
					hl.OutlineTransparency = info.origOutlineTrans
					hl.DepthMode           = info.origDepth
				end
			end
		end
		cpPanel.Visible = false
	end
	cpXBtn.MouseButton1Click:Connect(cpDoCancel)
	cpCancelBtn.MouseButton1Click:Connect(cpDoCancel)

	cpApplyBtn.MouseButton1Click:Connect(function()
		-- persist colour into modifications
		if cpPickerMode == "color" then
			local r,g,b    = cpHsv2Rgb(cpH, cpS, cpV)
			local finalColor = Color3.new(r, g, b)
			for _, p in ipairs(cpTargetParts) do
				if p and p.Parent and _editorLogic then
					local mods = _editorLogic.getPartMods(p)
					if mods then mods.Color = finalColor end
				end
			end
		end

		-- persist highlight properties into modifications + mirror to real character
		if cpPickerMode == "highlight" then
			local rc = Players.LocalPlayer.Character
			for _, p in ipairs(cpTargetParts) do
				if not (p and p.Parent) then continue end
				local vpHL = p:FindFirstChildWhichIsA("Highlight")
				if not vpHL then continue end
				-- write into modifications
				if _editorLogic then
					local mods = _editorLogic.getPartMods(p)
					if mods then
						mods.HLFillColor        = vpHL.FillColor
						mods.HLFillTransparency = cpHlFillTrans
						mods.HLOutlineTrans     = cpHlOutlineTrans
						mods.HLDepthMode        = cpHlDepthMode.Name
					end
				end
				-- mirror to real character
				if rc and _editorLogic then
					local pk = _editorLogic.getPathKey(p)
					if not pk then continue end
					local rp = _editorLogic.findBySegs(rc, string.split(pk, "/"))
					if rp then
						local rHL = rp:FindFirstChildWhichIsA("Highlight")
						if not rHL then rHL = Instance.new("Highlight", rp) end
						rHL.FillColor           = vpHL.FillColor
						rHL.OutlineColor        = vpHL.OutlineColor
						rHL.FillTransparency    = cpHlFillTrans
						rHL.OutlineTransparency = cpHlOutlineTrans
						rHL.DepthMode           = cpHlDepthMode
					end
				end
			end
		end
		cpPanel.Visible = false
	end)


	openColorPicker = function(titleStr, mode, parts, initColor)
		cpPickerMode  = mode
		cpTargetParts = parts
		cpOrigColors  = {}
		cpOrigHLs     = {}

		if mode == "color" then
			for _, p in ipairs(parts) do cpOrigColors[p] = p.Color end
			hlFrame.Visible = false
			cpPanel.Size    = UDim2.new(0, CP_W, 0, CP_H)
		else
			-- read existing highlight properties
			local existHL = parts[1] and parts[1]:FindFirstChildWhichIsA("Highlight")
			cpHlFillTrans    = existHL and existHL.FillTransparency    or 0.5
			cpHlOutlineTrans = existHL and existHL.OutlineTransparency or 0.0
			cpHlDepthMode    = existHL and existHL.DepthMode           or Enum.HighlightDepthMode.Occluded

			-- sync slider knobs to current values
			setHLFillTrans(cpHlFillTrans)
			setHLOutlineTrans(cpHlOutlineTrans)
			refreshDepthBtns()

			for _, p in ipairs(parts) do
				local hl = p:FindFirstChildWhichIsA("Highlight")
				if hl then
					cpOrigHLs[p] = {
						wasNew         = false,
						origFill       = hl.FillColor,
						origOutline    = hl.OutlineColor,
						origFillTrans  = hl.FillTransparency,
						origOutlineTrans = hl.OutlineTransparency,
						origDepth      = hl.DepthMode,
					}
				else
					hl = Instance.new("Highlight", p)
					hl.FillTransparency    = cpHlFillTrans
					hl.OutlineTransparency = cpHlOutlineTrans
					hl.DepthMode           = cpHlDepthMode
					cpOrigHLs[p] = {wasNew = true}
				end
			end
			hlFrame.Visible = true
			cpPanel.Size    = UDim2.new(0, CP_W, 0, CP_H + HL_PANEL_H + 8)
		end

		local ic = initColor or Color3.fromRGB(255, 220, 0)
		local function rgb2hsv(r,g,b)
			local mx,mn = math.max(r,g,b), math.min(r,g,b); local d = mx-mn
			local h,s,v = 0, mx==0 and 0 or d/mx, mx
			if d ~= 0 then
				if mx==r then h=((g-b)/d)%6 elseif mx==g then h=(b-r)/d+2 else h=(r-g)/d+4 end
				h = h/6
			end; return h,s,v
		end
		cpH, cpS, cpV = rgb2hsv(ic.R, ic.G, ic.B)
		cpTLbl.Text   = titleStr
		cpSetTab("HEX")
		cpPanel.Visible = true
	end
end

return ColorPickerlocal UI = {}

function UI.build(player, H)
	local corner = H.corner
	local stroke = H.stroke
	local pad    = H.pad

	-- ── ScreenGui + Toggle ────────────────────────────────────
	local gui = Instance.new("ScreenGui")
	gui.Name="AutoCharacterViewer"; gui.ResetOnSpawn=false; gui.IgnoreGuiInset=true
	gui.Parent = player:WaitForChild("PlayerGui")

	local TweenService   = game:GetService("TweenService")
	local TOGGLE_W       = 34
	local TOGGLE_H       = 34

	-- Invisible wrapper hitbox protruding ~38px from the right screen edge when hidden (massive sweet spot)
	local toggleButton = Instance.new("TextButton")
	toggleButton.Size             = UDim2.new(0, TOGGLE_W + 40, 0, 250) -- Giant invisible bumper region
	local HIDDEN_OFFSET  = TOGGLE_W + 2    -- Right edge of wrapper is 36px offscreen
	local VISIBLE_OFFSET = -8              -- Right edge of wrapper is 8px left of screen edge
	toggleButton.Position         = UDim2.new(1, HIDDEN_OFFSET, 0.38, 0)
	toggleButton.AnchorPoint      = Vector2.new(1, 0.5)
	toggleButton.BackgroundTransparency = 1
	toggleButton.Text             = ""
	toggleButton.AutoButtonColor  = false
	toggleButton.ZIndex           = 10
	toggleButton.Parent           = gui

	-- Visible Graphics Frame (acts as the actual Button visually)
	local toggleGfx = Instance.new("Frame")
	toggleGfx.Size                = UDim2.new(0, TOGGLE_W, 0, TOGGLE_H)
	toggleGfx.Position            = UDim2.new(1, -(TOGGLE_W / 2), 0.5, 0) -- Hugs right edge of wrapper
	toggleGfx.AnchorPoint         = Vector2.new(0.5, 0.5)
	toggleGfx.BackgroundColor3    = Color3.fromRGB(25, 25, 34)
	toggleGfx.ZIndex              = 10
	toggleGfx.Parent              = toggleButton
	corner(toggleGfx, 10)
	local toggleStroke = stroke(toggleGfx, Color3.fromRGB(90, 60, 160), 1.5)

	-- UIScale child lets us animate scale without touching Size
	local toggleScale = Instance.new("UIScale")
	toggleScale.Scale  = 1
	toggleScale.Parent = toggleGfx

	local toggleIcon = Instance.new("ImageLabel")
	toggleIcon.Size               = UDim2.new(0.85, 0, 0.85, 0) -- Nicely tight inside 34x34
	toggleIcon.Position           = UDim2.new(0.5, 0, 0.5, 0)
	toggleIcon.AnchorPoint        = Vector2.new(0.5, 0.5)
	toggleIcon.BackgroundTransparency = 1
	toggleIcon.Image              = "rbxthumb://type=Asset&id=7366741871&w=150&h=150" -- Nepgear portrait
	toggleIcon.ScaleType          = Enum.ScaleType.Crop
	toggleIcon.ImageColor3        = Color3.fromRGB(255, 255, 255)
	toggleIcon.ZIndex             = 11
	toggleIcon.Parent             = toggleGfx
	corner(toggleIcon, 8)

	-- ── Main Panel ────────────────────────────────────────────
	local mainPanel = Instance.new("Frame")
	mainPanel.Size=UDim2.new(0.82,0,0.90,0); mainPanel.Position=UDim2.new(0.5,0,0.5,0)
	mainPanel.AnchorPoint=Vector2.new(0.5,0.5); mainPanel.BackgroundColor3=Color3.fromRGB(18,18,22)
	mainPanel.BorderSizePixel=0; mainPanel.Visible=false; mainPanel.Parent=gui
	corner(mainPanel,16)

	-- mainPanel Scale for Mac-style transitions
	local mainScale = Instance.new("UIScale")
	mainScale.Scale = 1
	mainScale.Parent = mainPanel

	-- ── Close button (top-right of main panel) ───────────────────
	local closeButton = Instance.new("TextButton")
	closeButton.Size             = UDim2.new(0, 28, 0, 28)
	closeButton.Position         = UDim2.new(1, -10, 0, 10)
	closeButton.AnchorPoint      = Vector2.new(1, 0)
	closeButton.BackgroundColor3 = Color3.fromRGB(55, 18, 18)
	closeButton.TextColor3       = Color3.fromRGB(220, 140, 140)
	closeButton.Font             = Enum.Font.GothamBold
	closeButton.TextSize         = 14
	closeButton.Text             = "X"
	closeButton.ZIndex           = 20
	closeButton.Parent           = mainPanel
	corner(closeButton, 6)
	closeButton.MouseEnter:Connect(function()
		closeButton.BackgroundColor3 = Color3.fromRGB(100, 28, 28)
	end)
	closeButton.MouseLeave:Connect(function()
		closeButton.BackgroundColor3 = Color3.fromRGB(55, 18, 18)
	end)

	-- ── Toggle button tween wiring ────────────────────────────────
	-- Hover: elastic slide-in with a tiny scale bounce
	local hoverSlideIn  = TweenInfo.new(0.28, Enum.EasingStyle.Back,  Enum.EasingDirection.Out)
	local hoverSlideOut = TweenInfo.new(0.20, Enum.EasingStyle.Quad,  Enum.EasingDirection.Out)
	local toggleTweenIn  = TweenService:Create(toggleButton, hoverSlideIn,
		{ Position = UDim2.new(1, VISIBLE_OFFSET, 0.38, 0) })
	local toggleTweenOut = TweenService:Create(toggleButton, hoverSlideOut,
		{ Position = UDim2.new(1, HIDDEN_OFFSET, 0.38, 0) })
	local hoverScaleUp   = TweenService:Create(toggleScale, TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
		{ Scale = 1.18 })
	local hoverScaleDown = TweenService:Create(toggleScale, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
		{ Scale = 1.0 })

	-- Open burst: spin ✦ and scale-punch before showing the panel
	local openSpinInfo   = TweenInfo.new(0.45, Enum.EasingStyle.Back,    Enum.EasingDirection.Out)
	local openScaleInfo  = TweenInfo.new(0.35, Enum.EasingStyle.Elastic, Enum.EasingDirection.Out)
	local openGlowInfo   = TweenInfo.new(0.30, Enum.EasingStyle.Quad,    Enum.EasingDirection.Out)
	local openBurstScale = TweenService:Create(toggleScale,   openScaleInfo,  { Scale = 1.45 })
	local openBurstGlow  = TweenService:Create(toggleStroke,  openGlowInfo,   { Thickness = 3.5, Color = Color3.fromRGB(180, 120, 255) })
