	local closeShrinkScale = TweenService:Create(toggleScale,  closeShrinkInfo, { Scale = 1.0 })
	local closeShrinkGlow  = TweenService:Create(toggleStroke, closeShrinkInfo, { Thickness = 1.5, Color = Color3.fromRGB(90, 60, 160) })
	local closeShrinkText  = TweenService:Create(toggleGfx,    closeShrinkInfo, { Rotation = 0 })

