	-- The panel gets sucked back into the toggle button
	local macCloseInfo = TweenInfo.new(0.35, Enum.EasingStyle.Back, Enum.EasingDirection.In)

	local TARGET_POS = UDim2.new(0.5, 0, 0.5, 0)
