	preExportBox.Size=UDim2.new(0.9,0,1,-168); preExportBox.Position=UDim2.new(0.05,0,0,162)
	preExportBox.BackgroundColor3=Color3.fromRGB(18,18,22); preExportBox.TextColor3=Color3.fromRGB(150,220,150)
	preExportBox.PlaceholderText="Export string or messages will appear here..."
	preExportBox.PlaceholderColor3=Color3.fromRGB(60,60,75); preExportBox.Font=Enum.Font.Code
	preExportBox.TextSize=9; preExportBox.Text=""; preExportBox.ClearTextOnFocus=false
	preExportBox.BorderSizePixel=0; preExportBox.TextXAlignment=Enum.TextXAlignment.Left
	preExportBox.TextYAlignment=Enum.TextYAlignment.Top; preExportBox.TextWrapped=true; preExportBox.MultiLine=true
	corner(preExportBox,4); pad(preExportBox,6,6,6,6)

	-- ── Cameras ───────────────────────────────────────────────
	local viewportCamera = Instance.new("Camera")
	viewportFrame.CurrentCamera=viewportCamera; viewportCamera.Parent=viewportFrame

	local morphViewportCamera = Instance.new("Camera")
	morphViewportFrame.CurrentCamera=morphViewportCamera; morphViewportCamera.Parent=morphViewportFrame

	-- ── Return all handles ────────────────────────────────────
	return {
		gui=gui, mainPanel=mainPanel, toggleButton=toggleButton,
		editorTabBtn=editorTabBtn, morphsTabBtn=morphsTabBtn, presetsTabBtn=presetsTabBtn,
		editorPanel=editorPanel,
		viewportFrame=viewportFrame, worldModel=worldModel, vpBg=vpBg, gizmoOverlay=gizmoOverlay,
		searchBox=searchBox, partListScroll=partListScroll, listLayout=listLayout,
		modeButtons=modeButtons,
		sliderScroll=sliderScroll, sliderListLayout=sliderListLayout,
		materialUI=materialUI, matSearchBox=matSearchBox, matScroll=matScroll,
		matGrid=matGrid, matActionPanel=matActionPanel,
		oilyBtn=oilyBtn, highlighterBtn=highlighterBtn, colorBtn=colorBtn,
		saveButton=saveButton,
		morphsPanel=morphsPanel, morphViewportFrame=morphViewportFrame,
		morphWorldModel=morphWorldModel, morphNoPreview=morphNoPreview,
		morphListPanel=morphListPanel, mListHdrLbl=mListHdrLbl,
		morphSearchBox=morphSearchBox, morphListScroll=morphListScroll,
		morphListLayout=morphListLayout, categoryButtons=categoryButtons,
		presetsPanel=presetsPanel,
		preScroll=preScroll, preLayout=preLayout, preNameBox=preNameBox,
		preSaveBtn=preSaveBtn, preEquipBtn=preEquipBtn,
		preWorkspaceBtn=preWorkspaceBtn, preExportBtn=preExportBtn, preExportBox=preExportBox,
		viewportCamera=viewportCamera, morphViewportCamera=morphViewportCamera,
		closeButton      = closeButton,
		toggleTweenIn    = toggleTweenIn,
		toggleTweenOut   = toggleTweenOut,
		openBurstScale   = openBurstScale,
		openBurstGlow    = openBurstGlow,
		openBurstText    = openBurstText,
		closeShrinkScale = closeShrinkScale,
		closeShrinkGlow  = closeShrinkGlow,
		closeShrinkText  = closeShrinkText,
		panelOpenScale   = panelOpenScale,
		panelOpenPos     = panelOpenPos,
		panelCloseScale  = panelCloseScale,
		panelClosePos    = panelClosePos,
		mainScale        = mainScale,
		VISIBLE_OFFSET   = VISIBLE_OFFSET,
	}
end

return UIlocal UserInputService     = game:GetService("UserInputService")
local ContextActionService = game:GetService("ContextActionService")
local ReplicatedStorage    = game:GetService("ReplicatedStorage")
local GuiService           = game:GetService("GuiService")

local EditorLogic = {}

local _ui           = nil
local _state        = nil
local _player       = nil
local _H            = nil
local _gizmos       = nil
local _colorPicker  = nil

local isEdOrbiting  = false
local lastEdMouse   = nil
local isMoOrbiting  = false
local lastMoMouse   = nil
local edTreeOrder   = 0
local _matButtons   = {}

local TAB_ACT_BG = Color3.fromRGB(30,30,38)
local TAB_ACT_TC = Color3.fromRGB(255,255,255)
local TAB_INA_BG = Color3.fromRGB(20,20,26)
local TAB_INA_TC = Color3.fromRGB(110,110,130)


function EditorLogic.setGizmos(g)
	_gizmos = g
end

function EditorLogic.setColorPicker(cp)
	_colorPicker = cp
	-- Wire the Material-panel colour buttons now that we have the ref
	_ui.highlighterBtn.MouseButton1Click:Connect(function()
		local parts = EditorLogic.getAffectedParts(_state.selectedObject)
		if #parts == 0 then return end
		local existHL = parts[1]:FindFirstChildWhichIsA("Highlight")
		_colorPicker.open(
			"🔦  Highlight Color", "highlight", parts,
			existHL and existHL.FillColor or Color3.fromRGB(255,230,0)
		)
	end)
	_ui.colorBtn.MouseButton1Click:Connect(function()
		local parts = EditorLogic.getAffectedParts(_state.selectedObject)
		if #parts == 0 then return end
		_colorPicker.open("🎨  Part Color", "color", parts, parts[1].Color)
	end)
end


function EditorLogic.init(uiRef, stateRef, playerRef, H)
	_ui     = uiRef
	_state  = stateRef
	_player = playerRef
	_H      = H

	EditorLogic._setupInputHandlers()
	EditorLogic._setupMaterialButtons()
	EditorLogic._setupSaveButton()
	EditorLogic.setMode("Position")
	EditorLogic.setActiveTab("editor")
end


function EditorLogic.updateEditorCam()
	local cf = CFrame.new(_state.edOrbitCenter)
		* CFrame.Angles(0, math.rad(_state.edOrbitY), 0)
		* CFrame.Angles(math.rad(_state.edOrbitX), 0, 0)
		* CFrame.new(0, 0, _state.edOrbitDist)
	_ui.viewportCamera.CFrame = CFrame.new(cf.Position, _state.edOrbitCenter)
end

function EditorLogic.updateMorphCam()
	local cf = CFrame.new(_state.moOrbitCenter)
		* CFrame.Angles(0, math.rad(_state.moOrbitY), 0)
		* CFrame.Angles(math.rad(_state.moOrbitX), 0, 0)
		* CFrame.new(0, 0, _state.moOrbitDist)
	_ui.morphViewportCamera.CFrame = CFrame.new(cf.Position, _state.moOrbitCenter)
end


local function mouseOver(frame)
	local ml    = UserInputService:GetMouseLocation()
	local inset = GuiService:GetGuiInset()
	local rx    = ml.X - frame.AbsolutePosition.X
	local ry    = (ml.Y - inset.Y) - frame.AbsolutePosition.Y
	return (rx >= 0 and rx <= frame.AbsoluteSize.X and ry >= 0 and ry <= frame.AbsoluteSize.Y), rx, ry
end


function EditorLogic.getPathKey(inst)
	if not _state.clonedChar then return nil end
	local segs = {}
	local cur  = inst
	while cur and cur ~= _state.clonedChar do
		table.insert(segs, 1, cur.Name)
		cur = cur.Parent
	end
	if cur ~= _state.clonedChar then return nil end
	return table.concat(segs, "/")
end

function EditorLogic.findBySegs(root, segs)
	local cur = root
	for _, seg in ipairs(segs) do
		local found = nil
		for _, ch in ipairs(cur:GetChildren()) do
			if ch.Name == seg then found = ch; break end
		end
		if not found then return nil end
		cur = found
	end
	return cur
end


function EditorLogic.getAffectedParts(obj)
	if not obj then return {} end
	if obj:IsA("BasePart") then return {obj} end
	local r = {}
	for _, d in ipairs(obj:GetDescendants()) do
		if d:IsA("BasePart") and d.Name ~= "ViewportHighlight" then
			table.insert(r, d)
		end
	end
	return r
end


function EditorLogic.getPartMods(part)
	local key = EditorLogic.getPathKey(part)
	if not key then return nil end
	if not _state.modifications[key] then
		_state.modifications[key] = {
			HeightScale     = 1,
			WidthScale      = 1,
			UniformScale    = 1,
			OffsetX         = 0,
			OffsetY         = 0,
			OffsetZ         = 0,
			Transparency    = part.Transparency,
			Material        = part.Material,
			MaterialVariant = part.MaterialVariant or "",
			Color           = part.Color,
		}
	end
	return _state.modifications[key]
end


function EditorLogic.applyTransforms(part, mods)
	part.Transparency    = mods.Transparency
	part.Material        = mods.Material
	part.MaterialVariant = mods.MaterialVariant or ""
	if mods.Color then part.Color = mods.Color end

	if mods.HLFillColor then
		local hl = part:FindFirstChildWhichIsA("Highlight")
		if hl then
			hl.FillColor           = mods.HLFillColor
			hl.FillTransparency    = mods.HLFillTransparency   or 0.5
			hl.OutlineTransparency = mods.HLOutlineTrans       or 0.0
			hl.DepthMode           = Enum.HighlightDepthMode[mods.HLDepthMode or "Occluded"]
				or Enum.HighlightDepthMode.Occluded
		end
	end

	local width  = mods.WidthScale  * mods.UniformScale
	local height = mods.HeightScale * mods.UniformScale
	local sv     = Vector3.new(width, height, width)
	local offset = Vector3.new(mods.OffsetX, mods.OffsetY, mods.OffsetZ)

	local foundJoint = false
	for _, d in ipairs(_state.clonedChar:GetDescendants()) do
		if d:IsA("JointInstance") and d.Part1 == part then
			foundJoint = true
			if not part:GetAttribute("OriginalSize") then
				part:SetAttribute("OriginalSize", part.Size)
				part:SetAttribute("OriginalC1",   d.C1)
			end
			part.Size = part:GetAttribute("OriginalSize") * sv
			local origC1 = part:GetAttribute("OriginalC1")
			d.C1 = CFrame.new((origC1.Position * sv) + offset) * origC1.Rotation
			break
		end
	end

	if not foundJoint then
		if not part:GetAttribute("OriginalSize") then
			part:SetAttribute("OriginalSize", part.Size)
		end
		part.Size = part:GetAttribute("OriginalSize") * sv
	end

	local mesh = part:FindFirstChildWhichIsA("DataModelMesh")
	if mesh then
		if not part:GetAttribute("OriginalMeshScale") then
			part:SetAttribute("OriginalMeshScale", mesh.Scale)
		end
		mesh.Scale = part:GetAttribute("OriginalMeshScale") * sv
	end

	for _, h in ipairs(_state.highlightClones) do
		if h and h.Parent == part then
			h.Size = part.Size * 1.05
			local hm = h:FindFirstChildWhichIsA("SpecialMesh")
			local om = part:FindFirstChildWhichIsA("DataModelMesh")
			if hm and om then hm.Scale = om.Scale * 1.05 end
		end
	end
end


function EditorLogic.applyAllMods()
	if not _state.clonedChar then return end
	for _, d in ipairs(_state.clonedChar:GetDescendants()) do
		if d:IsA("BasePart") and d.Name ~= "ViewportHighlight" then
			local mods = EditorLogic.getPartMods(d)
			if mods then EditorLogic.applyTransforms(d, mods) end
		end
	end
end


function EditorLogic.applyModsToReal(realChar, segs, mods)
	local rp = EditorLogic.findBySegs(realChar, segs)
	if not rp or not rp:IsA("BasePart") then return false end

	local width  = mods.WidthScale  * mods.UniformScale
	local height = mods.HeightScale * mods.UniformScale
	local sv     = Vector3.new(width, height, width)
	local offset = Vector3.new(mods.OffsetX, mods.OffsetY, mods.OffsetZ)

	local foundJoint = false
	for _, d in ipairs(realChar:GetDescendants()) do
		if d:IsA("JointInstance") and d.Part1 == rp then
			foundJoint = true
			if not rp:GetAttribute("OriginalSize") then
				rp:SetAttribute("OriginalSize", rp.Size)
				rp:SetAttribute("OriginalC1",   d.C1)
			end
			rp.Size = rp:GetAttribute("OriginalSize") * sv
			local origC1 = rp:GetAttribute("OriginalC1")
			d.C1 = CFrame.new((origC1.Position * sv) + offset) * origC1.Rotation
			break
		end
	end

	if not foundJoint then
		if not rp:GetAttribute("OriginalSize") then
			rp:SetAttribute("OriginalSize", rp.Size)
		end
		rp.Size = rp:GetAttribute("OriginalSize") * sv
	end

	local mesh = rp:FindFirstChildWhichIsA("DataModelMesh")
	if mesh then
		if not rp:GetAttribute("OriginalMeshScale") then
			rp:SetAttribute("OriginalMeshScale", mesh.Scale)
		end
		mesh.Scale = rp:GetAttribute("OriginalMeshScale") * sv
	end

	if rp.Name ~= "HumanoidRootPart" then rp.Massless = true end
	rp.Transparency    = mods.Transparency
	rp.Material        = mods.Material
	rp.MaterialVariant = mods.MaterialVariant or ""
	if mods.Color then rp.Color = mods.Color end

	if mods.HLFillColor then
		local rHL = rp:FindFirstChildWhichIsA("Highlight")
		if not rHL then
			rHL = Instance.new("Highlight", rp)
		end
		rHL.FillColor           = mods.HLFillColor
		rHL.FillTransparency    = mods.HLFillTransparency   or 0.5
		rHL.OutlineTransparency = mods.HLOutlineTrans       or 0.0
		rHL.DepthMode           = Enum.HighlightDepthMode[mods.HLDepthMode or "Occluded"]
			or Enum.HighlightDepthMode.Occluded
	end

	return (mods.HeightScale > 1.05 or mods.WidthScale > 1.05 or mods.UniformScale > 1.05)
end

local function clearHL()
	for _, h in ipairs(_state.highlightClones) do
		if h and h.Parent then h:Destroy() end
	end
	_state.highlightClones = {}
end

local function makeHL(part)
	if not part or not part.Parent then return end
	part.Archivable = true
	local h = part:Clone()
	h.Name = "ViewportHighlight"
	for _, ch in ipairs(h:GetChildren()) do
		if not ch:IsA("SpecialMesh") then ch:Destroy() end
	end
	h.Material      = Enum.Material.Neon
	h.Color         = Color3.fromRGB(0, 200, 255)
	h.Transparency  = 0.58
	h.CanCollide    = false
	h.Anchored      = false
	h.Massless      = true
	h.Size          = part.Size * 1.05
	local mesh = h:FindFirstChildWhichIsA("SpecialMesh")
	if mesh then mesh.Scale = mesh.Scale * 1.05 end
	local w = Instance.new("WeldConstraint")
	w.Part0 = part; w.Part1 = h; w.Parent = h
	h.CFrame = part.CFrame
	h.Parent = part
	table.insert(_state.highlightClones, h)
end


function EditorLogic.setHighlight(obj)
	_state.selectedObject = obj
	clearHL()
	EditorLogic._updateEdSel(obj)
	if obj then
		for _, part in ipairs(EditorLogic.getAffectedParts(obj)) do
			makeHL(part)
		end
	end
	EditorLogic.rebuildSliders()
	if _gizmos then _gizmos.showGizmosForMode(_state.currentMode) end
end


function EditorLogic._updateEdSel(obj)
	for inst, btn in pairs(_state.rowButtonMap) do
		local lbl = btn:FindFirstChildWhichIsA("TextLabel")
		if inst == obj then
			btn.BackgroundTransparency = 0
			btn.BackgroundColor3       = Color3.fromRGB(0, 88, 160)
			if lbl then lbl.TextColor3 = Color3.fromRGB(255, 255, 255) end
		else
			btn.BackgroundTransparency = 1
			if lbl then lbl.TextColor3 = Color3.fromRGB(168, 168, 190) end
		end
	end
end

local function hasVisibleChild(inst)
	for _, ch in ipairs(inst:GetChildren()) do
		if not _state.SKIP_CLASSES[ch.ClassName] and ch.Name ~= "ViewportHighlight" then
			if ch:IsA("BasePart") or ch:IsA("Model") or ch:IsA("Folder")
				or ch:IsA("Accessory") or ch:IsA("Tool") then
				return true
			end
		end
	end
	return false
end

local function shouldShow(inst)
	if _state.SKIP_CLASSES[inst.ClassName]    then return false end
	if inst.Name == "ViewportHighlight"       then return false end
	if inst:IsA("BasePart")                   then return true  end
	if inst:IsA("Model") or inst:IsA("Folder")
		or inst:IsA("Accessory") or inst:IsA("Tool") then
		for _, d in ipairs(inst:GetDescendants()) do
			if d:IsA("BasePart") and d.Name ~= "ViewportHighlight" then return true end
		end
	end
	return false
end

local function buildEdRow(inst, depth)
	if _state.SKIP_CLASSES[inst.ClassName] or inst.Name == "ViewportHighlight" then return end
	if not shouldShow(inst) then return end

	local isBase    = inst:IsA("BasePart")
	local searching = _state.filterText ~= ""
	local matches   = not searching or inst.Name:lower():find(_state.filterText, 1, true)
	local pathKey   = EditorLogic.getPathKey(inst) or inst.Name
	local hasKids   = hasVisibleChild(inst)
	local isOpen    = _state.edExpanded[pathKey] == true

	if matches then
		edTreeOrder += 1
		local indent = searching and 0 or depth * 12
		local ROW    = 22

		local btn = Instance.new("TextButton")
		btn.Size                = UDim2.new(1, 0, 0, ROW)
		btn.BackgroundTransparency = 1
		btn.AutoButtonColor     = false
		btn.LayoutOrder         = edTreeOrder
		btn.Text                = ""
		btn.Parent              = _ui.partListScroll
		local c = Instance.new("UICorner", btn); c.CornerRadius = UDim.new(0, 3)

		if indent > 0 then
			local line = Instance.new("Frame", btn)
			line.Size             = UDim2.new(0, 1, 0.55, 0)
			line.Position         = UDim2.new(0, indent - 5, 0.22, 0)
			line.BackgroundColor3 = Color3.fromRGB(42, 42, 58)
			line.BorderSizePixel  = 0
		end

		local arrowBtn = nil
		if hasKids and not isBase then
			arrowBtn = Instance.new("TextButton", btn)
			arrowBtn.Size                = UDim2.new(0, 16, 0, 16)
			arrowBtn.Position            = UDim2.new(0, indent + 2, 0.5, 0)
			arrowBtn.AnchorPoint         = Vector2.new(0, 0.5)
			arrowBtn.BackgroundTransparency = 1
			arrowBtn.AutoButtonColor     = false
			arrowBtn.Text                = isOpen and "▼" or "▶"
			arrowBtn.TextColor3          = Color3.fromRGB(140, 140, 165)
			arrowBtn.Font                = Enum.Font.GothamBold
			arrowBtn.TextSize            = 9
		end

		local lbl        = Instance.new("TextLabel", btn)
		local lblIndent  = indent + (hasKids and not isBase and 18 or 6)
		lbl.Size              = UDim2.new(1, -(lblIndent + 28), 1, 0)
		lbl.Position          = UDim2.new(0, lblIndent, 0, 0)
		lbl.BackgroundTransparency = 1
		lbl.Text              = (isBase and "◆ " or "") .. inst.Name
		lbl.TextColor3        = isBase and Color3.fromRGB(168,168,190) or Color3.fromRGB(192,192,215)
		lbl.Font              = isBase and Enum.Font.Gotham or Enum.Font.GothamBold
		lbl.TextSize          = 10
		lbl.TextXAlignment    = Enum.TextXAlignment.Left
		lbl.TextTruncate      = Enum.TextTruncate.AtEnd

		local trashBtn = Instance.new("TextButton", btn)
		trashBtn.Size             = UDim2.new(0, 18, 0, 18)
		trashBtn.Position         = UDim2.new(1, -22, 0.5, 0)
		trashBtn.AnchorPoint      = Vector2.new(0, 0.5)
		trashBtn.BackgroundColor3 = Color3.fromRGB(60, 18, 18)
		trashBtn.Text             = "ⓧ"
		trashBtn.TextSize         = 10
		trashBtn.Font             = Enum.Font.Gotham
		trashBtn.TextColor3 = Color3.fromRGB(255, 255, 255)
		trashBtn.AutoButtonColor  = false
		trashBtn.BorderSizePixel  = 0
		trashBtn.ZIndex           = 5
		local tc = Instance.new("UICorner", trashBtn); tc.CornerRadius = UDim.new(0, 4)

		trashBtn.MouseButton1Click:Connect(function()
			if not inst or not inst.Parent then return end
			local realChar = _player.Character
			local segs     = string.split(pathKey, "/")
			if _state.syncConnection then _state.syncConnection:Disconnect(); _state.syncConnection = nil end
			if realChar then
				local rp = EditorLogic.findBySegs(realChar, segs)
				if rp then rp:Destroy() end
			end
			if _state.selectedObject == inst then EditorLogic.setHighlight(nil) end
			inst:Destroy()
			_state.modifications[pathKey] = nil
			_state.rowButtonMap[inst]     = nil
			EditorLogic.buildTree()
			task.delay(0.5, function()
				if not _ui.mainPanel.Visible then return end
				local liveChar = workspace:FindFirstChild(_player.Name) or _player.Character
				if liveChar and not _state.syncConnection then
					_state.syncConnection = liveChar.DescendantAdded:Connect(function()
						task.wait(0.1)
						EditorLogic.setupCharacter(liveChar, true)
					end)
				end
			end)
		end)

		_state.rowButtonMap[inst] = btn

		btn.MouseEnter:Connect(function()
			if inst ~= _state.selectedObject then
				btn.BackgroundTransparency = 0.82
				btn.BackgroundColor3       = Color3.fromRGB(30, 30, 46)
			end
		end)
		btn.MouseLeave:Connect(function()
			if inst ~= _state.selectedObject then
				btn.BackgroundTransparency = 1
			end
		end)
		btn.MouseButton1Click:Connect(function()
			EditorLogic.setHighlight(inst)
		end)

		if arrowBtn then
			arrowBtn.MouseButton1Click:Connect(function()
				_state.edExpanded[pathKey] = not _state.edExpanded[pathKey]
				EditorLogic.buildTree()
			end)
		end
	end

	if not isBase and (searching or isOpen) then
		local nd = searching and 0 or depth + 1
		for _, ch in ipairs(inst:GetChildren()) do
			buildEdRow(ch, nd)
		end
	end
end

function EditorLogic.buildTree()
	for _, ch in ipairs(_ui.partListScroll:GetChildren()) do
		if ch:IsA("TextButton") then ch:Destroy() end
	end
	_state.rowButtonMap = {}
	edTreeOrder         = 0
	if not _state.clonedChar then return end
	for _, ch in ipairs(_state.clonedChar:GetChildren()) do
		buildEdRow(ch, 0)
	end
	task.defer(function()
		_ui.partListScroll.CanvasSize = UDim2.new(0, 0, 0, _ui.listLayout.AbsoluteContentSize.Y + 6)
	end)
	EditorLogic._updateEdSel(_state.selectedObject)
end


local function matName(m)
	return tostring(m):gsub("Enum%.Material%.","")
end

local function mkCorner(p, r)
	local c = Instance.new("UICorner", p); c.CornerRadius = UDim.new(0, r or 8); return c
end

local function createSlider(name, color, minVal, maxVal, currentVal, callback, isMaterial)
	local frame = Instance.new("Frame")
	frame.Size                = UDim2.new(1, 0, 0, 26)
	frame.BackgroundTransparency = 1

	local label = Instance.new("TextLabel", frame)
	label.Size             = UDim2.new(0.6, 0, 1, -10)
	label.BackgroundTransparency = 1
	label.Text             = name
	label.TextColor3       = color
	label.Font             = Enum.Font.GothamMedium
	label.TextSize         = 11
	label.TextXAlignment   = Enum.TextXAlignment.Left

	local valLabel = Instance.new("TextLabel", frame)
	valLabel.Size             = UDim2.new(0.4, 0, 1, -10)
	valLabel.Position         = UDim2.new(0.6, 0, 0, 0)
	valLabel.BackgroundTransparency = 1
	valLabel.Text             = isMaterial and matName(currentVal) or string.format("%.2f", currentVal)
	valLabel.TextColor3       = Color3.fromRGB(200, 200, 200)
	valLabel.Font             = Enum.Font.Gotham
	valLabel.TextSize         = 10
	valLabel.TextXAlignment   = Enum.TextXAlignment.Right

	local track = Instance.new("Frame", frame)
	track.Size             = UDim2.new(1, 0, 0, 4)
	track.Position         = UDim2.new(0, 0, 1, -6)
	track.BackgroundColor3 = Color3.fromRGB(35, 35, 45)
	mkCorner(track, 99)

	local knob = Instance.new("TextButton", track)
	knob.Size             = UDim2.new(0, 12, 0, 12)
	knob.AnchorPoint      = Vector2.new(0.5, 0.5)
	knob.BackgroundColor3 = color
	knob.Text             = ""
	knob.AutoButtonColor  = false
	mkCorner(knob, 99)

	local sliderStartVal = currentVal
	if isMaterial then
		sliderStartVal = table.find(_state.MaterialList, currentVal) or 1
	end
	local pct = math.clamp((sliderStartVal - minVal) / (maxVal - minVal), 0, 1)
	knob.Position = UDim2.new(pct, 0, 0.5, 0)

	local isDragging = false
	knob.MouseButton1Down:Connect(function() isDragging = true end)

	local c1, c2
	c1 = UserInputService.InputChanged:Connect(function(input)
		if not isDragging then return end
		if input.UserInputType ~= Enum.UserInputType.MouseMovement
			and input.UserInputType ~= Enum.UserInputType.Touch then return end
		local relX   = input.Position.X - track.AbsolutePosition.X
		local newPct = math.clamp(relX / track.AbsoluteSize.X, 0, 1)
		knob.Position = UDim2.new(newPct, 0, 0.5, 0)
		local trueVal = minVal + (maxVal - minVal) * newPct
		if isMaterial then
			local idx  = math.floor(newPct * (#_state.MaterialList - 1)) + 1
			trueVal    = _state.MaterialList[idx]
			valLabel.Text = matName(trueVal)
		else
			valLabel.Text = string.format("%.2f", trueVal)
		end
		callback(trueVal)
	end)
	c2 = UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 then
			isDragging = false
		end
	end)
	frame.Destroying:Connect(function() c1:Disconnect(); c2:Disconnect() end)
	return frame
end

local function createUserInputBox(placeholder, callback)
	local frame = Instance.new("Frame")
	frame.Size                = UDim2.new(1, 0, 0, 26)
	frame.BackgroundTransparency = 1

	local box = Instance.new("TextBox", frame)
	box.Size              = UDim2.new(1, -10, 1, -4)
	box.Position          = UDim2.new(0, 5, 0, 2)
	box.BackgroundColor3  = Color3.fromRGB(22, 22, 28)
	box.TextColor3        = Color3.fromRGB(220, 220, 240)
	box.PlaceholderText   = placeholder
	box.PlaceholderColor3 = Color3.fromRGB(90, 90, 110)
	box.Font              = Enum.Font.Gotham
	box.TextSize          = 11
	box.Text              = ""
	box.ClearTextOnFocus  = false
	mkCorner(box, 4)

	local debounce = false
	box.FocusLost:Connect(function(enterPressed)
		if enterPressed and box.Text ~= "" and not debounce then
			debounce = true
			callback(box.Text)
			task.wait(0.125)
			box.Text  = ""
			debounce  = false
		end
	end)
	return frame
end

function EditorLogic.rebuildSliders()
	for _, ch in ipairs(_ui.sliderScroll:GetChildren()) do
		if ch:IsA("Frame") or ch:IsA("TextLabel") then ch:Destroy() end
	end

	local parts = EditorLogic.getAffectedParts(_state.selectedObject)
	local mods  = parts[1] and EditorLogic.getPartMods(parts[1]) or nil

	if _state.currentMode == "Material" then
		_ui.sliderScroll.Visible = false
		_ui.materialUI.Visible   = true
		EditorLogic._updateMatSelection()
		return
	else
		_ui.sliderScroll.Visible = true
		_ui.materialUI.Visible   = false
	end

	local function noSel(txt)
		local lbl = Instance.new("TextLabel", _ui.sliderScroll)
		lbl.Size                = UDim2.new(1, 0, 0, 30)
		lbl.BackgroundTransparency = 1
		lbl.Text                = txt or ("Select a part to adjust " .. _state.currentMode)
		lbl.TextColor3          = Color3.fromRGB(130, 130, 150)
		lbl.Font                = Enum.Font.Gotham
		lbl.TextSize            = 11
	end

	if _state.currentMode == "Size" then
		if mods then
			local c = _ui.modeButtons["Size"].Color
			createSlider("Overall Size", c, _state.MIN_SCALE, _state.MAX_SCALE, mods.UniformScale, function(v)
				for _, p in ipairs(parts) do EditorLogic.getPartMods(p).UniformScale = v; EditorLogic.applyTransforms(p, EditorLogic.getPartMods(p)) end
			end).Parent = _ui.sliderScroll
			createSlider("Part Width", c, _state.MIN_SCALE, _state.MAX_SCALE, mods.WidthScale, function(v)
				for _, p in ipairs(parts) do EditorLogic.getPartMods(p).WidthScale = v; EditorLogic.applyTransforms(p, EditorLogic.getPartMods(p)) end
			end).Parent = _ui.sliderScroll
			createSlider("Part Height", c, _state.MIN_SCALE, _state.MAX_SCALE, mods.HeightScale, function(v)
				for _, p in ipairs(parts) do EditorLogic.getPartMods(p).HeightScale = v; EditorLogic.applyTransforms(p, EditorLogic.getPartMods(p)) end
			end).Parent = _ui.sliderScroll
		else noSel() end

	elseif _state.currentMode == "Position" then
		if mods then
			local c = _ui.modeButtons["Position"].Color
			createSlider("X Offset", c, -5, 5, mods.OffsetX, function(v)
				for _, p in ipairs(parts) do EditorLogic.getPartMods(p).OffsetX = v; EditorLogic.applyTransforms(p, EditorLogic.getPartMods(p)) end
			end).Parent = _ui.sliderScroll
			createSlider("Y Offset", c, -5, 5, mods.OffsetY, function(v)
				for _, p in ipairs(parts) do EditorLogic.getPartMods(p).OffsetY = v; EditorLogic.applyTransforms(p, EditorLogic.getPartMods(p)) end
			end).Parent = _ui.sliderScroll
			createSlider("Z Offset", c, -5, 5, mods.OffsetZ, function(v)
				for _, p in ipairs(parts) do EditorLogic.getPartMods(p).OffsetZ = v; EditorLogic.applyTransforms(p, EditorLogic.getPartMods(p)) end
			end).Parent = _ui.sliderScroll
		else noSel() end

	elseif _state.currentMode == "Transparency" then
		if mods then
			createSlider("Transparency", _ui.modeButtons["Transparency"].Color, 0, 1, mods.Transparency, function(v)
				for _, p in ipairs(parts) do EditorLogic.getPartMods(p).Transparency = v; EditorLogic.applyTransforms(p, EditorLogic.getPartMods(p)) end
			end).Parent = _ui.sliderScroll
		else noSel() end

	elseif _state.currentMode == "User" then
		local uColor = _ui.modeButtons["User"].Color
		createSlider("Overall Character Scale", uColor, 0.1, 4.0, _state.globalHumanoidScale, function(v)
			_state.globalHumanoidScale = v
			if _state.clonedChar then _state.clonedChar:ScaleTo(v) end
			local sr = ReplicatedStorage:FindFirstChild("SizeRemote")
			if sr then sr:FireServer(v) end
		end).Parent = _ui.sliderScroll
		createUserInputBox("Morph into User (Name/ID)...", function(txt)
			local re = ReplicatedStorage:FindFirstChild("CharUser"); if re then re:FireServer(txt) end
		end).Parent = _ui.sliderScroll
		createUserInputBox("Wear Accessory/Hat (ID)...", function(txt)
			local re = ReplicatedStorage:FindFirstChild("CatalogStuff"); if re then re:FireServer(txt) end
		end).Parent = _ui.sliderScroll
		createUserInputBox("Wear Shirt (ID)...", function(txt)
			local re = ReplicatedStorage:FindFirstChild("CatalogStuff"); if re then re:FireServer(txt, "Shirt") end
		end).Parent = _ui.sliderScroll
		createUserInputBox("Wear Pants (ID)...", function(txt)
			local re = ReplicatedStorage:FindFirstChild("CatalogStuff"); if re then re:FireServer(txt, "Pants") end
		end).Parent = _ui.sliderScroll
		createUserInputBox("Wear T-Shirt (ID)...", function(txt)
			local re = ReplicatedStorage:FindFirstChild("CatalogStuff"); if re then re:FireServer(txt, "TShirt") end
		end).Parent = _ui.sliderScroll
		createUserInputBox("Wear Face (ID)...", function(txt)
			local re = ReplicatedStorage:FindFirstChild("CatalogStuff"); if re then re:FireServer(txt, "Face") end
		end).Parent = _ui.sliderScroll
	end

	task.defer(function()
		_ui.sliderScroll.CanvasSize = UDim2.new(0, 0, 0, _ui.sliderListLayout.AbsoluteContentSize.Y + 4)
	end)
end


function EditorLogic._updateMatSelection()
	if _state.currentMode ~= "Material" then return end
	local parts = EditorLogic.getAffectedParts(_state.selectedObject)

	if #parts == 0 then
		for _, btn in pairs(_matButtons) do
			btn.BackgroundColor3 = Color3.fromRGB(30, 30, 38)
			btn.TextColor3       = Color3.fromRGB(180, 180, 200)
		end
		local ob = _ui.matActionPanel and _ui.matActionPanel:FindFirstChild("Oily")
		if ob then ob.BackgroundColor3 = Color3.fromRGB(25,25,30); ob.TextColor3 = Color3.fromRGB(241,196,15) end
		return
	end

	local currentMat = EditorLogic.getPartMods(parts[1]).Material
	local currentVar = EditorLogic.getPartMods(parts[1]).MaterialVariant or ""

	for matEnum, btn in pairs(_matButtons) do
		if matEnum == currentMat and currentVar == "" then
			btn.BackgroundColor3 = _ui.modeButtons["Material"].Color
			btn.TextColor3       = Color3.fromRGB(255, 255, 255)
		else
			btn.BackgroundColor3 = Color3.fromRGB(30, 30, 38)
			btn.TextColor3       = Color3.fromRGB(180, 180, 200)
		end
	end

	local ob = _ui.matActionPanel and _ui.matActionPanel:FindFirstChild("Oily")
	if ob then
		if currentVar == "Oily" then
			ob.BackgroundColor3 = Color3.fromRGB(241, 196, 15)
			ob.TextColor3       = Color3.fromRGB(255, 255, 255)
		else
			ob.BackgroundColor3 = Color3.fromRGB(25, 25, 30)
			ob.TextColor3       = Color3.fromRGB(241, 196, 15)
		end
	end
end

function EditorLogic._setupMaterialButtons()
	for _, matEnum in ipairs(_state.MaterialList) do
		local btn = Instance.new("TextButton", _ui.matScroll)
		btn.BackgroundColor3 = Color3.fromRGB(30, 30, 38)
		btn.Text             = matName(matEnum)
		btn.TextColor3       = Color3.fromRGB(180, 180, 200)
		btn.Font             = Enum.Font.Gotham
		btn.TextSize         = 10
		mkCorner(btn, 4)
		_matButtons[matEnum] = btn

		btn.MouseButton1Click:Connect(function()
			local parts = EditorLogic.getAffectedParts(_state.selectedObject)
			if #parts == 0 then return end
			for _, p in ipairs(parts) do
				local m = EditorLogic.getPartMods(p)
				m.Material        = matEnum
				m.MaterialVariant = ""
				EditorLogic.applyTransforms(p, m)
			end
			EditorLogic._updateMatSelection()
		end)
	end

	_ui.matSearchBox:GetPropertyChangedSignal("Text"):Connect(function()
		local q = _ui.matSearchBox.Text:lower()
		for matEnum, btn in pairs(_matButtons) do
			btn.Visible = (q == "" or matName(matEnum):lower():find(q, 1, true))
		end
		task.defer(function()
			_ui.matScroll.CanvasSize = UDim2.new(0, 0, 0, _ui.matGrid.AbsoluteContentSize.Y + 4)
		end)
	end)

	_ui.oilyBtn.MouseButton1Click:Connect(function()
		local parts = EditorLogic.getAffectedParts(_state.selectedObject)
		if #parts == 0 then return end
		for _, p in ipairs(parts) do
			local m = EditorLogic.getPartMods(p)
			if m.MaterialVariant == "Oily" then
				m.MaterialVariant = ""
			else
				m.Material        = Enum.Material.SmoothPlastic
				m.MaterialVariant = "Oily"
			end
			EditorLogic.applyTransforms(p, m)
		end
		EditorLogic._updateMatSelection()
	end)
end


function EditorLogic.setMode(name)
	_state.currentMode = name
	for n, ui in pairs(_ui.modeButtons) do
		if n == name then
			ui.Button.BackgroundColor3 = Color3.fromRGB(45, 45, 55)
			ui.Button.TextColor3       = ui.Color
			if ui.Stroke then ui.Stroke.Transparency = 0 end
		else
			ui.Button.BackgroundColor3 = Color3.fromRGB(25, 25, 30)
			ui.Button.TextColor3       = Color3.fromRGB(120, 120, 133)
			if ui.Stroke then ui.Stroke.Transparency = 1 end
		end
	end
	EditorLogic.rebuildSliders()
	if _gizmos then _gizmos.showGizmosForMode(name) end
end


function EditorLogic.setActiveTab(tab)
	_ui.editorPanel.Visible  = (tab == "editor")
	_ui.morphsPanel.Visible  = (tab == "morphs")
	_ui.presetsPanel.Visible = (tab == "presets")

	_ui.editorTabBtn.BackgroundColor3  = tab == "editor"  and TAB_ACT_BG or TAB_INA_BG
	_ui.editorTabBtn.TextColor3        = tab == "editor"  and TAB_ACT_TC or TAB_INA_TC
	_ui.morphsTabBtn.BackgroundColor3  = tab == "morphs"  and TAB_ACT_BG or TAB_INA_BG
	_ui.morphsTabBtn.TextColor3        = tab == "morphs"  and TAB_ACT_TC or TAB_INA_TC
	_ui.presetsTabBtn.BackgroundColor3 = tab == "presets" and TAB_ACT_BG or TAB_INA_BG
	_ui.presetsTabBtn.TextColor3       = tab == "presets" and TAB_ACT_TC or TAB_INA_TC
end


function EditorLogic.setupCharacter(character, isSyncRefresh)
	task.spawn(function()
		local hrp = character:WaitForChild("HumanoidRootPart", 10)
		local hum = character:WaitForChild("Humanoid", 10)
		if not (hrp and hum) then return end

		local t = 0
		while not _player:HasAppearanceLoaded() and t < 3 do
			task.wait(0.1); t += 0.1
		end

		local lastPath = _state.selectedObject and EditorLogic.getPathKey(_state.selectedObject) or nil

		if _state.clonedChar then _state.clonedChar:Destroy(); _state.clonedChar = nil end
		clearHL(); _state.selectedObject = nil

		local attempts = 0
		while not _state.clonedChar and attempts < 10 do
			attempts += 1
			character.Archivable = true
			for _, d in ipairs(character:GetDescendants()) do d.Archivable = true end
			_state.clonedChar = character:Clone()
			character.Archivable = false
			if not _state.clonedChar then task.wait(0.2) end
		end
		if not _state.clonedChar then return end

		_state.clonedChar:PivotTo(CFrame.new(0, 0, 0))
		_state.clonedChar.Parent = _ui.worldModel

		if character.Parent then
			_state.globalHumanoidScale = character:GetScale()
			_state.clonedChar:ScaleTo(_state.globalHumanoidScale)
		end

		if not isSyncRefresh then
			_state.edOrbitY    = 180
			_state.edOrbitX    = -12
			_state.edOrbitDist = 6.5
		end
		EditorLogic.updateEditorCam()

		local ch2 = _state.clonedChar:FindFirstChildWhichIsA("Humanoid")
		if ch2 then
			local anim = ch2:FindFirstChildWhichIsA("Animator") or Instance.new("Animator", ch2)
			local animScript = character:FindFirstChild("Animate")
			if animScript then
				local idle = animScript:WaitForChild("idle", 3)
				if idle and idle:FindFirstChild("Animation1") then
					anim:LoadAnimation(idle.Animation1):Play()
				end
			end
		end

		EditorLogic.applyAllMods()
		EditorLogic.buildTree()

		if lastPath then
			local segs = string.split(lastPath, "/")
			local r    = EditorLogic.findBySegs(_state.clonedChar, segs)
			if r then EditorLogic.setHighlight(r) end
		end
	end)
end


function EditorLogic._setupSaveButton()
	_ui.saveButton.MouseButton1Click:Connect(function()
		local rc = _player.Character
		if not rc or not _state.clonedChar then return end

		local pop = false
		for pk, mods in pairs(_state.modifications) do
			if EditorLogic.applyModsToReal(rc, string.split(pk, "/"), mods) then pop = true end
		end
		if pop then rc:PivotTo(rc:GetPivot() + Vector3.new(0, 3, 0)) end

		local ev = ReplicatedStorage:FindFirstChild("SaveMorphData")
		if ev then
			local payload = {}
			for pk, mods in pairs(_state.modifications) do
				payload[pk] = {
					HeightScale     = mods.HeightScale,
					WidthScale      = mods.WidthScale,
					UniformScale    = mods.UniformScale,
					OffsetX         = mods.OffsetX,
					OffsetY         = mods.OffsetY,
					OffsetZ         = mods.OffsetZ,
					Transparency    = mods.Transparency,
					Material        = mods.Material.Value,
					MaterialVariant = mods.MaterialVariant or "",
					ColorR          = mods.Color and mods.Color.R or nil,
					ColorG          = mods.Color and mods.Color.G or nil,
					ColorB          = mods.Color and mods.Color.B or nil,
					HLFillColorR     = mods.HLFillColor and mods.HLFillColor.R or nil,
					HLFillColorG     = mods.HLFillColor and mods.HLFillColor.G or nil,
					HLFillColorB     = mods.HLFillColor and mods.HLFillColor.B or nil,
					HLFillTrans      = mods.HLFillTransparency,
					HLOutlineTrans   = mods.HLOutlineTrans,
					HLDepthMode      = mods.HLDepthMode,
				}
			end
			ev:FireServer(payload)
		end

		-- Play the Mac-style minimize animation
		_ui.panelCloseScale:Play()
		_ui.panelClosePos:Play()

		task.delay(0.35, function()
			_ui.mainPanel.Visible  = false
		end)

		-- Restore the toggle button
		_ui.closeShrinkScale:Play()
		_ui.closeShrinkGlow:Play()
		_ui.closeShrinkText:Play()
		_ui.toggleButton.Visible = true
		_ui.toggleTweenOut:Play()

		if _state.syncConnection then
			_state.syncConnection:Disconnect()
			_state.syncConnection = nil
		end
	end)
end


function EditorLogic._setupInputHandlers()
	-- Search box
	_ui.searchBox:GetPropertyChangedSignal("Text"):Connect(function()
		_state.filterText = _ui.searchBox.Text:lower()
		EditorLogic.buildTree()
	end)

	-- Mode buttons
	for name, ui in pairs(_ui.modeButtons) do
		ui.Button.MouseButton1Click:Connect(function()
			EditorLogic.setMode(name)
		end)
	end

	-- Tab buttons
	_ui.editorTabBtn.MouseButton1Click:Connect(function()  EditorLogic.setActiveTab("editor")  end)
	_ui.morphsTabBtn.MouseButton1Click:Connect(function()  EditorLogic.setActiveTab("morphs")  end)
	_ui.presetsTabBtn.MouseButton1Click:Connect(function() EditorLogic.setActiveTab("presets") end)

	-- RMB orbit
	ContextActionService:BindAction("EditorRMB", function(_, state, _)
		if not _ui.mainPanel.Visible then return Enum.ContextActionResult.Pass end
		if state == Enum.UserInputState.Begin then
			local oe = mouseOver(_ui.viewportFrame)
			local om = mouseOver(_ui.morphViewportFrame)
			if oe and _ui.editorPanel.Visible then
				isEdOrbiting = true; lastEdMouse = UserInputService:GetMouseLocation()
				_state.activeOrbit = "editor"
				return Enum.ContextActionResult.Sink
			elseif om and _ui.morphsPanel.Visible then
				isMoOrbiting = true; lastMoMouse = UserInputService:GetMouseLocation()
				_state.activeOrbit = "morph"
				return Enum.ContextActionResult.Sink
			end
		elseif state == Enum.UserInputState.End then
			if _state.activeOrbit then
				isEdOrbiting = false; isMoOrbiting = false
				lastEdMouse  = nil;   lastMoMouse  = nil
				_state.activeOrbit = nil
				return Enum.ContextActionResult.Sink
			end
		end
		return Enum.ContextActionResult.Pass
	end, false, Enum.UserInputType.MouseButton2)

	-- Mouse move + scroll
	UserInputService.InputChanged:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseMovement then
			if isEdOrbiting and lastEdMouse then
				local ml = UserInputService:GetMouseLocation()
				_state.edOrbitY = _state.edOrbitY - (ml.X - lastEdMouse.X) * 0.5
				_state.edOrbitX = math.clamp(_state.edOrbitX + (ml.Y - lastEdMouse.Y) * 0.4, -85, 85)
				EditorLogic.updateEditorCam(); lastEdMouse = ml
			elseif isMoOrbiting and lastMoMouse then
				local ml = UserInputService:GetMouseLocation()
				_state.moOrbitY = _state.moOrbitY - (ml.X - lastMoMouse.X) * 0.5
				_state.moOrbitX = math.clamp(_state.moOrbitX + (ml.Y - lastMoMouse.Y) * 0.4, -85, 85)
				EditorLogic.updateMorphCam(); lastMoMouse = ml
			end
		end
		if input.UserInputType == Enum.UserInputType.MouseWheel then
			if _ui.editorPanel.Visible and mouseOver(_ui.viewportFrame) then
				_state.edOrbitDist = math.clamp(_state.edOrbitDist - input.Position.Z * 0.7, 1.5, 22)
				EditorLogic.updateEditorCam()
			elseif _ui.morphsPanel.Visible and mouseOver(_ui.morphViewportFrame) then
				_state.moOrbitDist = math.clamp(_state.moOrbitDist - input.Position.Z * 0.7, 1.5, 22)
				EditorLogic.updateMorphCam()
			end
		end
	end)

	-- Viewport LMB select
	UserInputService.InputBegan:Connect(function(input)
		if not _ui.mainPanel.Visible or not _ui.editorPanel.Visible then return end
		if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
		if not _state.clonedChar then return end
		local over, rx, ry = mouseOver(_ui.viewportFrame)
		if not over then return end
		if _gizmos and _gizmos.isHandleDown() then return end

		local cam  = _ui.viewportCamera
		local sz   = _ui.viewportFrame.AbsoluteSize
		local nx   = (rx / sz.X) * 2 - 1
		local ny   = -((ry / sz.Y) * 2 - 1)
		local tanF = math.tan(math.rad(cam.FieldOfView) / 2)
		local dir  = Vector3.new(nx * tanF * (sz.X / sz.Y), ny * tanF, -1).Unit
		local ray  = Ray.new(cam.CFrame.Position, cam.CFrame:VectorToWorldSpace(dir))

		local excl = {}
		for _, d in ipairs(_state.clonedChar:GetDescendants()) do
			if d.Name == "ViewportHighlight" or (d:IsA("BasePart") and d.Transparency >= 1) then
				table.insert(excl, d)
			end
		end
		local rp = RaycastParams.new()
		rp.FilterDescendantsInstances = excl
		rp.FilterType                 = Enum.RaycastFilterType.Exclude
		local res = _ui.worldModel:Raycast(ray.Origin, ray.Direction * 1000, rp)
		EditorLogic.setHighlight(res and res.Instance or nil)
	end)
end

return EditorLogiclocal UserInputService = game:GetService("UserInputService")
local RunService       = game:GetService("RunService")

local Gizmos = {}

local _ui, _state, _editorLogic

local gizmoWidgets    = {}
local gizmoActive     = false
local activeGizmoDrag = nil
local gizmoHandleDown = false

function Gizmos.isHandleDown() return gizmoHandleDown end

function Gizmos.init(uiRef, stateRef, editorLogicRef)
	_ui          = uiRef
	_state       = stateRef
	_editorLogic = editorLogicRef

	-- RenderStepped: reproject gizmo handles onto screen
	RunService.RenderStepped:Connect(function()
		if not gizmoActive or #gizmoWidgets==0 then return end
		if not _state.selectedObject or not _state.clonedChar then Gizmos.clearGizmos(); return end
		local parts=_editorLogic.getAffectedParts(_state.selectedObject); if #parts==0 then return end
		local part=parts[1]; local center=part.CFrame.Position
		local ARROW_LEN=math.clamp(part.Size.Magnitude*0.75,1.0,3.0)
		local vpSize=_ui.viewportFrame.AbsoluteSize

		local function proj(worldPos)
			if vpSize.X==0 or vpSize.Y==0 then return Vector2.new(0,0),false end
			local cam=_ui.viewportCamera; local localPos=cam.CFrame:PointToObjectSpace(worldPos)
			if localPos.Z>0 then return Vector2.new(0,0),false end
			local fov=math.rad(cam.FieldOfView); local aspect=vpSize.X/vpSize.Y; local depth=-localPos.Z
			local ndcX=(localPos.X/depth)/(math.tan(fov/2)*aspect)
			local ndcY=(localPos.Y/depth)/math.tan(fov/2)
			local px=((ndcX+1)/2)*vpSize.X; local py=((-ndcY+1)/2)*vpSize.Y
			local vis=px>=-30 and px<=vpSize.X+30 and py>=-30 and py<=vpSize.Y+30
			return Vector2.new(px,py),vis
		end

		local cPx,cVisible=proj(center)
		if not cVisible then
			for _,w in ipairs(gizmoWidgets) do w.line.Visible=false; w.head.Visible=false; w.knob.Visible=false end; return
		end
		for _,w in ipairs(gizmoWidgets) do
			local tPx,tVisible=proj(center+w.def.dir*ARROW_LEN)
			w.line.Visible=tVisible; w.head.Visible=tVisible; w.knob.Visible=tVisible
			if not tVisible then continue end
			local dx=tPx.X-cPx.X; local dy=tPx.Y-cPx.Y; local len=math.sqrt(dx*dx+dy*dy)
			local tNX=tPx.X/vpSize.X; local tNY=tPx.Y/vpSize.Y
			local midNX=(cPx.X+tPx.X)/2/vpSize.X; local midNY=(cPx.Y+tPx.Y)/2/vpSize.Y
			w.knob.Position=UDim2.new(tNX,0,tNY,0); w.head.Position=UDim2.new(tNX,0,tNY,0)
			w.line.Size=UDim2.new(0,math.max(len-15,0),0,2); w.line.Position=UDim2.new(midNX,0,midNY,0)
			w.line.Rotation=math.deg(math.atan2(dy,dx))
			w.axisDirScreen=len>0 and Vector2.new(dx/len,dy/len) or Vector2.new(0,-1)
		end
	end)

	-- Gizmo drag movement
	UserInputService.InputChanged:Connect(function(input)
		if not activeGizmoDrag then return end
		if input.UserInputType~=Enum.UserInputType.MouseMovement then return end
		local ml=UserInputService:GetMouseLocation(); local drag=activeGizmoDrag
		local delta=Vector2.new(ml.X-drag.startX,ml.Y-drag.startY)
		local projected=delta:Dot(drag.widget.axisDirScreen)
		local newVal=math.clamp(drag.startVal+projected*drag.def.sens,drag.def.min,drag.def.max)
		for _,p in ipairs(drag.parts) do
			local mods=_editorLogic.getPartMods(p); mods[drag.def.prop]=newVal; _editorLogic.applyTransforms(p,mods)
		end
	end)

	-- Gizmo drag end
	UserInputService.InputEnded:Connect(function(input)
		if input.UserInputType==Enum.UserInputType.MouseButton1 then
			if activeGizmoDrag then activeGizmoDrag=nil; _editorLogic.rebuildSliders() end
			gizmoHandleDown=false
		end
	end)
end

function Gizmos.clearGizmos()
	for _,w in ipairs(gizmoWidgets) do
		if w.line  and w.line.Parent  then w.line:Destroy()  end
		if w.head  and w.head.Parent  then w.head:Destroy()  end
		if w.knob  and w.knob.Parent  then w.knob:Destroy()  end
	end
	gizmoWidgets={}; gizmoActive=false; activeGizmoDrag=nil
end

local function makeGizmoWidget(def)
	local function corner(p,r) local c=Instance.new("UICorner",p); c.CornerRadius=UDim.new(0,r or 8); return c end

	local line=Instance.new("Frame"); line.BackgroundColor3=def.color; line.BackgroundTransparency=0.25
	line.BorderSizePixel=0; line.AnchorPoint=Vector2.new(0.5,0.5); line.ZIndex=11; line.Parent=_ui.gizmoOverlay

	local head=Instance.new("Frame"); head.Size=UDim2.new(0,9,0,9); head.BackgroundColor3=def.color
	head.BorderSizePixel=0; head.AnchorPoint=Vector2.new(0.5,0.5); head.Rotation=45; head.ZIndex=12; head.Parent=_ui.gizmoOverlay

	local knob=Instance.new("TextButton"); knob.Size=UDim2.new(0,22,0,22)
	knob.BackgroundColor3=def.color; knob.BackgroundTransparency=0.15; knob.Text=def.label
	knob.TextColor3=Color3.fromRGB(255,255,255); knob.Font=Enum.Font.GothamBold; knob.TextSize=9
	knob.AnchorPoint=Vector2.new(0.5,0.5); knob.ZIndex=13; knob.AutoButtonColor=false; corner(knob,99); knob.Parent=_ui.gizmoOverlay

	local widget={line=line,head=head,knob=knob,def=def,axisDirScreen=Vector2.new(0,-1)}
	table.insert(gizmoWidgets,widget)

	knob.MouseButton1Down:Connect(function()
		local parts=_editorLogic.getAffectedParts(_state.selectedObject); if #parts==0 then return end
		gizmoHandleDown=true
		activeGizmoDrag={
			def=def, parts=parts,
			startX=UserInputService:GetMouseLocation().X, startY=UserInputService:GetMouseLocation().Y,
			startVal=_editorLogic.getPartMods(parts[1])[def.prop], widget=widget,
		}
	end)
	knob.MouseEnter:Connect(function() knob.BackgroundTransparency=0 end)
	knob.MouseLeave:Connect(function() knob.BackgroundTransparency=0.15 end)
	return widget
end

function Gizmos.showGizmosForMode(mode)
	Gizmos.clearGizmos()
	local defs=_state.GIZMO_DEFS[mode]
	if defs and _state.selectedObject then
		for _,def in ipairs(defs) do makeGizmoWidget(def) end
		gizmoActive=true
	end
end

return Gizmoslocal ReplicatedStorage = game:GetService("ReplicatedStorage")

local PresetsLogic = {}
local _ui, _state, _editorLogic, _morphsLogic, _player

function PresetsLogic.init(uiRef, stateRef, editorLogicRef, morphsLogicRef, playerRef)
	_ui          = uiRef
	_state       = stateRef
	_editorLogic = editorLogicRef
	_morphsLogic = morphsLogicRef
	_player      = playerRef
	PresetsLogic._setupButtons()
end

-- ── Helpers ───────────────────────────────────────────────────
local function mkCorner(p, r)
	local c = Instance.new("UICorner", p); c.CornerRadius = UDim.new(0, r or 8); return c
end
local function mkPad(p, t, b, l, r)
	local u = Instance.new("UIPadding", p)
	u.PaddingTop    = UDim.new(0, t or 0); u.PaddingBottom = UDim.new(0, b or 0)
	u.PaddingLeft   = UDim.new(0, l or 0); u.PaddingRight  = UDim.new(0, r or 0)
end

-- ── Refresh preset list ───────────────────────────────────────
local function refreshPresetsList()
	for _, ch in ipairs(_ui.preScroll:GetChildren()) do
		if ch:IsA("TextButton") then ch:Destroy() end
	end
	local order = 0
	for name, _ in pairs(_state.savedPresets) do
		order += 1
		local btn = Instance.new("TextButton", _ui.preScroll)
		btn.Size             = UDim2.new(1,0,0,28)
		btn.BackgroundColor3 = (name == _state.selectedPresetName)
			and Color3.fromRGB(80,0,160) or Color3.fromRGB(20,20,26)
		btn.TextColor3       = Color3.fromRGB(220,220,240)
		btn.Font             = Enum.Font.GothamMedium
		btn.TextSize         = 11
		btn.Text             = " ★  " .. name
		btn.TextXAlignment   = Enum.TextXAlignment.Left
		btn.LayoutOrder      = order
		mkCorner(btn, 4)
		mkPad(btn, 0, 0, 8, 0)
		btn.MouseButton1Click:Connect(function()
			_state.selectedPresetName = name
			refreshPresetsList()
		end)
	end
	task.defer(function()
		_ui.preScroll.CanvasSize = UDim2.new(0, 0, 0, _ui.preLayout.AbsoluteContentSize.Y + 8)
	end)
end
PresetsLogic.refresh = refreshPresetsList

-- ═════════════════════════════════════════════════════════════
--  BUTTON WIRING
-- ═════════════════════════════════════════════════════════════
function PresetsLogic._setupButtons()

	-- ── Save current config as preset ────────────────────────
	_ui.preSaveBtn.MouseButton1Click:Connect(function()
		local name = _ui.preNameBox.Text
		if name == "" then name = "Preset " .. tostring(math.random(1000, 9999)) end

		local snap = {
			savedMorphs  = {},
			mods         = {},
			humanoidScale = _state.globalHumanoidScale,
		}

		for c, mName in pairs(_state.equippedMorphs) do
			if mName then snap.savedMorphs[c] = mName end
		end

		if _state.clonedChar then
			for _, part in ipairs(_state.clonedChar:GetDescendants()) do
				if part:IsA("BasePart") and part.Name ~= "ViewportHighlight" then
					local pk = _editorLogic.getPathKey(part)
					if pk then
						local em = _state.modifications[pk]
						if em then
							snap.mods[pk] = {
								HeightScale     = em.HeightScale,
								WidthScale      = em.WidthScale,
								UniformScale    = em.UniformScale,
								OffsetX         = em.OffsetX,
								OffsetY         = em.OffsetY,
								OffsetZ         = em.OffsetZ,
								Transparency    = em.Transparency,
								Material        = tostring(em.Material),
								MaterialVariant = em.MaterialVariant or "",
								-- colour
								ColorR          = em.Color and em.Color.R or nil,
								ColorG          = em.Color and em.Color.G or nil,
								ColorB          = em.Color and em.Color.B or nil,
								-- highlight
								HLFillColorR    = em.HLFillColor and em.HLFillColor.R or nil,
								HLFillColorG    = em.HLFillColor and em.HLFillColor.G or nil,
								HLFillColorB    = em.HLFillColor and em.HLFillColor.B or nil,
								HLFillTrans     = em.HLFillTransparency,
								HLOutlineTrans  = em.HLOutlineTrans,
								HLDepthMode     = em.HLDepthMode,
							}
						else
							snap.mods[pk] = {
								HeightScale=1, WidthScale=1, UniformScale=1,
								OffsetX=0, OffsetY=0, OffsetZ=0,
								Transparency    = part.Transparency,
								Material        = tostring(part.Material),
								MaterialVariant = part.MaterialVariant or "",
							}
						end
					end
				end
			end
		end

		_state.savedPresets[name]    = snap
		_state.selectedPresetName    = name
		_ui.preNameBox.Text          = ""
		refreshPresetsList()
	end)

	-- ── Equip selected preset ─────────────────────────────────
	_ui.preEquipBtn.MouseButton1Click:Connect(function()
		if not _state.selectedPresetName or not _state.savedPresets[_state.selectedPresetName] then
			_ui.preExportBox.Text = "-- Error: No preset selected.\n-- Please click a preset from the left menu first."
			return
		end

		local preset = _state.savedPresets[_state.selectedPresetName]

		-- Swap morphs
		if preset.savedMorphs then
			_state.equipRemote = _state.equipRemote or ReplicatedStorage:FindFirstChild("EquipMorph")
			if _state.equipRemote then
				-- unequip anything not in the preset
				for cat, currentName in pairs(_state.equippedMorphs) do
					if currentName then
						local presetName = preset.savedMorphs[cat]
						if presetName ~= currentName then
							_state.equipRemote:FireServer(cat, "Remove_" .. currentName)
						end
					end
				end
				_state.equippedMorphs = {}
				for c, mName in pairs(preset.savedMorphs) do
					if mName then
						_state.equippedMorphs[c] = mName
						_state.equipRemote:FireServer(c, mName)
					end
				end
				if _morphsLogic then _morphsLogic.updateCheckboxes() end
				task.wait(0.6)
			end
		end

		-- Clear existing mods and rebuild from preset
		table.clear(_state.modifications)
		local rc  = _player.Character
		local pop = false

		-- Overall humanoid scale
		_state.globalHumanoidScale = preset.humanoidScale or 1.0
		local sr = ReplicatedStorage:FindFirstChild("SizeRemote")
		if sr then sr:FireServer(_state.globalHumanoidScale) end
		if _state.clonedChar then _state.clonedChar:ScaleTo(_state.globalHumanoidScale) end

		-- Rebuild each part modification
		for pk, m in pairs(preset.mods) do
			-- Resolve Material enum
			local matEnum = Enum.Material.Plastic
			pcall(function()
				local matStr = string.match(m.Material, "Enum%.Material%.(%w+)") or m.Material
				matEnum = Enum.Material[matStr] or Enum.Material.Plastic
			end)

			-- Resolve Color
			local col = nil
			if m.ColorR then
				col = Color3.new(m.ColorR, m.ColorG or 0, m.ColorB or 0)
			end

			-- Resolve Highlight fill colour
			local hlCol = nil
			if m.HLFillColorR then
				hlCol = Color3.new(m.HLFillColorR, m.HLFillColorG or 0, m.HLFillColorB or 0)
			end

			-- Build the full mod table
			local builtMod = {
				HeightScale     = m.HeightScale     or 1,
				WidthScale      = m.WidthScale      or 1,
				UniformScale    = m.UniformScale    or 1,
				OffsetX         = m.OffsetX         or 0,
				OffsetY         = m.OffsetY         or 0,
				OffsetZ         = m.OffsetZ         or 0,
				Transparency    = m.Transparency    or 0,
				Material        = matEnum,
				MaterialVariant = m.MaterialVariant or "",
				Color           = col,
				-- highlight fields
				HLFillColor        = hlCol,
				HLFillTransparency = m.HLFillTrans,
				HLOutlineTrans     = m.HLOutlineTrans,
				HLDepthMode        = m.HLDepthMode,
			}

			_state.modifications[pk] = builtMod

			if rc then
				if _editorLogic.applyModsToReal(rc, string.split(pk, "/"), builtMod) then
					pop = true
				end
			end
		end

		if pop and rc then
			rc:PivotTo(rc:GetPivot() + Vector3.new(0, 3, 0))
		end

		_editorLogic.applyAllMods()

		-- Fire save event with full payload
		local saveEvent = ReplicatedStorage:FindFirstChild("SaveMorphData")
		if saveEvent then
			local payload = {}
			for pk, m in pairs(_state.modifications) do
				payload[pk] = {
					HeightScale     = m.HeightScale,
					WidthScale      = m.WidthScale,
					UniformScale    = m.UniformScale,
					OffsetX         = m.OffsetX,
					OffsetY         = m.OffsetY,
					OffsetZ         = m.OffsetZ,
					Transparency    = m.Transparency,
					Material        = m.Material.Value,
					MaterialVariant = m.MaterialVariant or "",
					ColorR          = m.Color and m.Color.R or nil,
					ColorG          = m.Color and m.Color.G or nil,
					ColorB          = m.Color and m.Color.B or nil,
					HLFillColorR    = m.HLFillColor and m.HLFillColor.R or nil,
					HLFillColorG    = m.HLFillColor and m.HLFillColor.G or nil,
					HLFillColorB    = m.HLFillColor and m.HLFillColor.B or nil,
					HLFillTrans     = m.HLFillTransparency,
					HLOutlineTrans  = m.HLOutlineTrans,
					HLDepthMode     = m.HLDepthMode,
				}
			end
			saveEvent:FireServer(payload)
		end

		_ui.preExportBox.Text = "✅ Successfully equipped preset: " .. _state.selectedPresetName
	end)

	-- ── Export to Workspace ───────────────────────────────────
	_ui.preWorkspaceBtn.MouseButton1Click:Connect(function()
		if not _state.clonedChar then return end

		local exportModel      = Instance.new("Model")
		exportModel.Name       = _ui.preNameBox.Text ~= "" and _ui.preNameBox.Text or "CustomMorphPreset"

		for _, child in ipairs(_state.clonedChar:GetChildren()) do
			if _state.allowedMorphParts[child.Name] then
				local cc = child:Clone()
				if cc:IsA("BasePart") then cc.Anchored = true end
				for _, v in pairs(cc:GetDescendants()) do
					if v.Name == "ViewportHighlight" then
						v:Destroy()
					elseif v:IsA("BasePart") then
						v.Anchored = true
					end
				end
				cc.Parent = exportModel
			end
		end

		if #exportModel:GetChildren() == 0 then
			_ui.preExportBox.Text = "⚠️ No valid morph parts found on character!\nMake sure you have a custom morph equipped before exporting."
			exportModel:Destroy()
			return
		end

		exportModel.Parent = workspace
		local targetPivot  = _player.Character and _player.Character:GetPivot() or CFrame.new(0, 10, 0)
		exportModel:PivotTo(targetPivot)

		_ui.preExportBox.Text = "📦 MORPH EXPORTED TO WORKSPACE!\n\n1. Look in Workspace for '"
			.. exportModel.Name .. "'.\n2. Right-Click and Copy it.\n3. Stop your Play test.\n4. Paste into ServerStorage > Morphs > Preset!"
	end)

	-- ── Get export text ───────────────────────────────────────
	_ui.preExportBtn.MouseButton1Click:Connect(function()
		if not _state.selectedPresetName or not _state.savedPresets[_state.selectedPresetName] then
			_ui.preExportBox.Text = "-- No preset selected\n-- Please select a preset from the list to export."
			return
		end

		local preset = _state.savedPresets[_state.selectedPresetName]
		local lines  = {"-- Preset Export: " .. _state.selectedPresetName}

		if preset.savedMorphs then
			local mStrs = {}
			for c, mName in pairs(preset.savedMorphs) do
				if mName then table.insert(mStrs, c .. "/" .. mName) end
			end
			table.insert(lines, #mStrs > 0
				and "Equipped Morphs: " .. table.concat(mStrs, ", ")
				or  "Equipped Morphs: None")
		else
			table.insert(lines, "Equipped Morphs: None")
		end

		table.insert(lines, "Global Humanoid Scale: " .. string.format("%.2f", preset.humanoidScale or 1))
		table.insert(lines, "\n-- Modifications Data:")

		local hasMods = false
		for pk, m in pairs(preset.mods) do
			local changed = m.HeightScale~=1 or m.WidthScale~=1 or m.UniformScale~=1
				or m.OffsetX~=0 or m.OffsetY~=0 or m.OffsetZ~=0
				or m.Transparency~=0 or not string.find(m.Material,"Plastic")
				or (m.MaterialVariant and m.MaterialVariant~="")
				or m.ColorR or m.HLFillColorR
			if changed then
				hasMods = true
				local colStr = m.ColorR
					and string.format(", Col=(%.2f,%.2f,%.2f)", m.ColorR, m.ColorG or 0, m.ColorB or 0)
					or ""
				local hlStr = m.HLFillColorR
					and string.format(", HL=(%.2f,%.2f,%.2f) FT=%.2f OT=%.2f D=%s",
						m.HLFillColorR, m.HLFillColorG or 0, m.HLFillColorB or 0,
						m.HLFillTrans or 0.5, m.HLOutlineTrans or 0, m.HLDepthMode or "Occluded")
					or ""
				table.insert(lines, string.format(
					"[\"%s\"] = {H=%.2f,W=%.2f,U=%.2f,X=%.2f,Y=%.2f,Z=%.2f,Trans=%.2f,Mat=\"%s\",Var=\"%s\"%s%s}",
					pk,
					m.HeightScale or 1, m.WidthScale or 1, m.UniformScale or 1,
					m.OffsetX or 0, m.OffsetY or 0, m.OffsetZ or 0,
					m.Transparency or 0, m.Material or "", m.MaterialVariant or "",
					colStr, hlStr
					))
			end
		end

		if not hasMods then
			table.insert(lines, "-- No modifications found.")
		end

		_ui.preExportBox.Text = table.concat(lines, "\n")
	end)
end

return PresetsLogiclocal cumshots = {}
local cumgravity = 60

local rng = Random.new()

-- Modified to accept settings table
function newcumshot(cframe, vel, ignore, settings)
	local cum = script.cumshot:Clone()
	local points = {}
	local t0 = 0
	local extravel = Vector3.zero

	-- Default settings if none provided (for backward compatibility)
	local size = 0.05
	local life = 20
	local color = Color3.fromRGB(255, 255, 255)
	local material = Enum.Material.Plastic

	if settings then
		if settings.Size then size = settings.Size end
		if settings.Lifetime then life = settings.Lifetime end
		if settings.Color then color = settings.Color end
		if settings.Material then material = settings.Material end
	end

	cum:ScaleTo(size)

	local sphere = cum.Sphere
	sphere.CFrame = cframe * CFrame.Angles(math.rad(90), 0, 0)
	sphere.Anchored = true
	sphere.CanCollide = false
	sphere.CanQuery = false
	sphere.CanTouch = false
	sphere.Massless = true

	-- Apply appearance
	sphere.Color = color
	sphere.Material = material

	-- Apply to children/bones if necessary (depending on mesh structure)
	for _, child in ipairs(cum:GetDescendants()) do
		if child:IsA("BasePart") or child:IsA("MeshPart") then
			child.Color = color
			child.Material = material
		end
	end

	for i = 1, 8 do
		local v = sphere["Bone.00" .. i]
		if v then
			points[#points + 1] = {v, 0, t0, v.WorldPosition, vel + extravel, false}
			t0 += i % 2 == 0 and 1 / 60 or 0
			vel *= 0.95
			extravel = Vector3.zero
			v.Position = Vector3.zero
		end
	end
	points[#points + 1] = {sphere.Bone, 0, t0, sphere.Bone.WorldPosition, vel + extravel, false}
	sphere.Bone.Position = Vector3.zero
	cum.Parent = workspace

	sphere.Transparency = 0
	cumshots[#cumshots + 1] = {
		cum = cum,
		mainpart = sphere,
		life = life, -- Uses the variable from settings
		points = points,
		ignore = ignore,
	}
end

game:GetService('RunService').RenderStepped:Connect(function(dt)
	local j = 1
	for i = 1, #cumshots do
		local v = cumshots[i]
		cumshots[i] = nil
		if not v or not v.cum or not v.cum.Parent then
			continue
		end

		v.life -= dt
		if v.life <= 0 then
			if v.cum and not v.fading then
				v.fading = true
				game.TweenService:Create(v.mainpart, TweenInfo.new(4), {Transparency = 1}):Play()
				task.delay(4, game.Destroy, v.cum)
			end
		end

		local lastpos
		for x = 1, #v.points do
			local y = v.points[x]
			if y[2] >= y[3] then
				if not y[6] or not y[6].Parent then
					y[6] = nil
					local newvel = y[5] - (Vector3.yAxis * cumgravity * dt)
					local dtvel = (newvel + y[5]) * dt / 2
					y[5] = newvel
					local results = workspace:Raycast(y[1].WorldPosition, dtvel, v.ignore) --v.frames < 3 and v.ignore or nil)
					if results then
						if not v.hit then
							v.hit = results.Instance
							local weld = Instance.new('WeldConstraint')
							weld.Part0 = v.mainpart
							weld.Part1 = results.Instance
							weld.Parent = v.mainpart
							v.mainpart.Anchored = false
						end
						y[6] = results.Instance
						y[1].WorldCFrame = CFrame.new(results.Position, results.Position + results.Normal)
					else
						y[1].WorldPosition += dtvel
					end
				end
			else
				y[2] += dt
			end

			if lastpos then
				y[1].Transform = CFrame.fromOrientation(math.pi / 2, 0, 0)
				y[1].WorldCFrame = CFrame.new(lastpos, y[1].WorldPosition) + (y[1].WorldPosition - lastpos)
			elseif y[1].WorldPosition.X ~= y[4].X 
				and y[1].WorldPosition.Y ~= y[4].Y 
				and y[1].WorldPosition.Z ~= y[4].Z 
			then
				y[1].Transform = CFrame.fromOrientation(0, math.pi, 0)
				if typeof(y[4]) == 'CFrame' then
					y[1].WorldCFrame = y[4]
				else
					y[1].WorldCFrame = CFrame.new(y[4], y[1].WorldPosition) + (y[1].WorldPosition - y[4])
				end
			end

			if y[6] then
				if not y[7] then
					y[7] = y[6].CFrame:ToObjectSpace(y[1].WorldCFrame)
				end
				y[1].WorldCFrame = y[6].CFrame * y[7]
			end	

			y[4] = y[1].WorldPosition
			lastpos = y[4]
		end

		cumshots[j] = v
		j += 1
	end
	j = nil
end)

return function(ignore_list)
	local cm_ignore = RaycastParams.new()
	cm_ignore.FilterDescendantsInstances = ignore_list or {};
	cm_ignore.RespectCanCollide = true

	return newcumshot, cm_ignore
end--[[ SmartBone Version 0.1.2 by Celnak ]] --

-- // Types \\ --

type func = () -> ()
type dictionary = { [string]: any }
type array = { [number]: any }

type rootList = {
	[number]: Bone
}
type particle = {
	Bone: Bone,
	RestLength: number,
	Weight: number,
	ParentIndex: number,
	Transform: CFrame,
	LocalTransform: CFrame,
	RootTransform: CFrame,
	Radius: number,
	IsColliding: boolean,
	BoneLength: number,
	HeirarchyLength: number,
	DebugPart: BasePart,

	TransformOffset: CFrame,
	LastTransformOffset: CFrame,
	LocalTransformOffset: CFrame,
	RestPosition: Vector3,
	BoneTransform: CFrame,
	CalculatedWorldCFrame: CFrame,
	CalculatedWorldPosition: Vector3,

	Position: Vector3,
	LastPosition: Vector3,
	Anchored: boolean,
	RecyclingBin: any,
}
type particleArray = {
	[number]: particle
}
type particleTree = {
	WindOffset: number,
	Root: Bone,
	RootPart: BasePart,
	RootWorldToLocal: Vector3,
	BoneTotalLength: number,
	Particles: particleArray,
	LocalCFrame: CFrame,
	LocalGravity: Vector3,
	Force: Vector3,
	RestGravity: Vector3,
	ObjectMove: Vector3,
	ObjectPreviousPosition: Vector3,
}

-- // Services \\ --

local Lighting = game:GetService("Lighting")
local CollectionService = game:GetService("CollectionService")
local RunService = game:GetService("RunService")

if not RunService:IsClient() then 
	warn("Attempted to initialize SmartBone on Server.") 
	return nil
end

-- // Constructors \\ --

local ZERO = Vector3.zero

-- // Dependencies \\ --

local Dependencies = script:WaitForChild("Dependencies")
local Components = script:WaitForChild("Components")

local Config = require(Dependencies.Config)

local UnitConversion = require(Dependencies.UnitConversion)
local DefaultSettings = require(Dependencies.DefaultSettings)

local ParticleTree = require(Components.ParticleTree)
local Particle = require(Components.Particle)

local SettingsMath = require(Dependencies.SettingsMath)
local Utilities = require(Dependencies.Utilities)

local ID_SEED = 12098135901304
local ID_RANDOM = Random.new(ID_SEED)

local SmartBoneTags = CollectionService:GetTagged("SmartBone")

-- // Debug \\ --

local DEBUG = Config.Debug
local DEBUG_FOLDER, DEBUG_HIGHLIGHT

if DEBUG then
	DEBUG_FOLDER = Instance.new("Model")
	DEBUG_FOLDER.Name = "SMARTBONE_DEBUGFOLDER"
	DEBUG_FOLDER.Parent = workspace

	DEBUG_HIGHLIGHT = Instance.new("Highlight")
	DEBUG_HIGHLIGHT.FillColor = Color3.fromRGB(255, 0, 0)
	DEBUG_HIGHLIGHT.OutlineTransparency = 1
	DEBUG_HIGHLIGHT.FillTransparency = 0
	DEBUG_HIGHLIGHT.Parent = DEBUG_FOLDER
	DEBUG_HIGHLIGHT.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
	DEBUG_HIGHLIGHT.Enabled = true
end

-- // Module \\ --

local CurrentControllers = {}
local module = {}
module.__index = module

function module.new(rootPart: BasePart, rootList: array)
	local self = setmetatable({
		ID = ID_RANDOM:NextInteger(1, 10000000),
		RootPart = rootPart,
		Time = 0,
		ParticleTrees = {},
		Connections = {},
		RootList = rootList,
		ObjectScale = UnitConversion.Convert(math.abs(rootPart.Size.X), "Millimeter"),
		WindPreviousPosition = Vector3.zero,
		Removed = false,
		RemovedEvent = Instance.new("BindableEvent"),
		InRange = false,

		Settings = {},
	}, module)

	for name, value in DefaultSettings do
		self.Settings[name] = rootPart:GetAttribute(name) or value
	end

	self.Settings.BlendWeight = 1
	self.Settings.UpdateRate = math.floor(self.Settings.UpdateRate + 0.1)

	self:Init()

	self:UpdateParameters(self.Settings)

	return self
end

function module:Init()
	local RootPart = self.RootPart

	local tailBone, start

	CurrentControllers[self.ID] = self

	self.Connections["AttributeChanged"] = RootPart.AttributeChanged:ConnectParallel(function(Attribute: string)
		if not self.Settings[Attribute] then return end
		self:UpdateParameters(Attribute, RootPart:GetAttribute(Attribute))
	end)

	self.Connections["LightingAttributeChanged"] = Lighting.AttributeChanged:ConnectParallel(function(Attribute: string)
		if not self.Settings[Attribute] then return end
		self:UpdateParameters(Attribute, Lighting:GetAttribute(Attribute))
	end)

	for _, Bone in RootPart:GetDescendants() do
		if Bone:IsA("Bone") and Bone.Parent:IsA("Bone") and #Bone:GetChildren() == 0 then
			start = Bone.WorldCFrame
				+ (Bone.WorldCFrame.UpVector.Unit * (Bone.WorldPosition - Bone.Parent.WorldPosition).Magnitude)
			tailBone = Instance.new("Bone")
			tailBone.Parent = Bone
			tailBone.Name = Bone.Name .. "_Tail"
			tailBone.WorldCFrame = start
		end
	end

	for _, Root in self.RootList do
		self:AppendParticleTree(Root)
	end

	for _, particleTree in self.ParticleTrees do
		self:AppendParticles(particleTree, particleTree.Root, 0, 0)
	end
end

function module:AppendParticleTree(Root: Bone)
	table.insert(self.ParticleTrees, ParticleTree.new(Root, self.RootPart, self.Settings.Gravity))
end

function module:AppendParticles(particleTree: dictionary, Bone: Bone, ParentIndex: number, BoneLength: number)
	local Settings = self.Settings

	local particle: particle = Particle.new(Bone, particleTree.Root, self.RootPart, Settings)
	particle.Position, particle.LastPosition = Bone.WorldPosition, Bone.WorldPosition
	particle.ParentIndex = ParentIndex
	particle.BoneLength = BoneLength
	particle.HeirarchyLength = 0
	if DEBUG == true then
		particle.DebugPart = Instance.new("Part")
		particle.DebugPart.Size = Vector3.new(.1,.1,.1)
		particle.DebugPart.Anchored = true
		particle.DebugPart.CanCollide = false
		particle.DebugPart.CastShadow = false
		particle.DebugPart.CanTouch = false
		particle.DebugPart.CanQuery = false
		particle.DebugPart.Color = Color3.fromRGB(255,0,0)
		particle.DebugPart.Parent = DEBUG_FOLDER
	end
	if ParentIndex >= 1 then
		BoneLength = (particleTree.Particles[ParentIndex].Bone.WorldPosition - particle.Position).Magnitude
		particle.BoneLength = BoneLength
		particle.Weight = (BoneLength * 0.7)
		particle.HeirarchyLength = Utilities.GetHierarchyLength(Bone, particleTree.Root)
	end

	if particle.HeirarchyLength <= Settings.AnchorDepth then
		particle.Anchored = true
	end

	table.insert(particleTree.Particles, particle)

	local index = #particleTree.Particles
	local boneChildren = Bone:GetChildren()

	local child

	for i = 1, #boneChildren do
		child = boneChildren[i]
		if child:IsA("Bone") then
			self:AppendParticles(particleTree, child, index, BoneLength)
		end
	end
end

function module:UpdateParameters(setting, value)
	if not self.Settings[setting] then return end
	self.Settings[setting] = if SettingsMath[setting] then SettingsMath[setting](value) else value
end

function module:PreUpdate(particleTree: particleTree)
	
	local rootPart = particleTree.RootPart
	local root = particleTree.Root
	
	particleTree.ObjectMove = (rootPart.Position - particleTree.ObjectPreviousPosition)
	particleTree.ObjectPreviousPosition = rootPart.Position

	particleTree.RestGravity = root.CFrame:PointToWorldSpace(particleTree.LocalGravity)

	for _, particle in particleTree.Particles do
		particle.LastTransformOffset = particle.TransformOffset
		if particle.Bone == particle.Root then
			particle.TransformOffset = rootPart.CFrame * particle.RootTransform
		else
			particle.TransformOffset = root.WorldCFrame * particle.Transform
		end
		particle.LocalTransformOffset = root.CFrame * particle.LocalTransform
	end
end

function module:UpdateParticles(particleTree: particleTree, Delta: number, LoopIndex: number)
	local Settings = self.Settings

	local Damping = Settings.Damping
	local Force = Settings.Gravity
	local ForceDirection = Settings.Gravity.Unit

	local ProjectedForce = ForceDirection * math.max(particleTree.RestGravity:Dot(ForceDirection), 0)

	Force -= ProjectedForce
	Force = (Force + Settings.Force) * (self.ObjectScale * Delta)

	local ObjectMove = LoopIndex == 0 and particleTree.ObjectMove or ZERO

	local windMove, velocity, move
	local timeModifier

	for _, particle in particleTree.Particles do
		if particle.ParentIndex >= 1 and particle.Anchored == false then
			windMove = ZERO

			if Settings.WindInfluence > 0 then
				timeModifier = particleTree.WindOffset
					+ (os.clock() - (particle.HeirarchyLength / 5))
					+ (
						((particle.TransformOffset.Position - particleTree.Root.WorldPosition).Magnitude / 5)
						* Settings.WindInfluence
					)
				windMove = Vector3.new(
					Settings.WindDirection.X
						+ (Settings.WindDirection.X * (math.sin(timeModifier * Settings.WindSpeed))),
					Settings.WindDirection.Y + (0.05 * (math.sin(timeModifier * Settings.WindSpeed))),
					Settings.WindDirection.Z
						+ (Settings.WindDirection.X * (math.sin(timeModifier * Settings.WindSpeed)))
				)

				windMove /= particle.BoneLength
				windMove *= Settings.WindInfluence
				windMove *= (Settings.WindStrength / 100) * (math.clamp(particle.HeirarchyLength, 1, 10) / 10)
				windMove *= particle.Weight
				self.WindPreviousPosition = windMove
			end

			velocity = (particle.Position - particle.LastPosition)
			move = (ObjectMove * Settings.Inertia)
			
			particle.LastPosition = particle.Position + move
			particle.Position += velocity * (1 - Damping) + Force + move + windMove
		else
			particle.LastPosition = particle.TransformOffset.Position--particle.Bone.WorldPosition
			particle.Position = particle.TransformOffset.Position
		end
	end
end

function module:CorrectParticles(particleTree: particleTree, Delta: number)
	local Settings = self.Settings
	local stiffness = Settings.Stiffness

	local parentPoint
	local restLength, difference, length
	local mat, restPosition, maxLength

	for _, point in particleTree.Particles do
		parentPoint = particleTree.Particles[point.ParentIndex]

		if parentPoint and point.ParentIndex >= 1 and point.Anchored == false then
			restLength = (parentPoint.TransformOffset.Position - point.TransformOffset.Position).Magnitude

			if stiffness > 0 or Settings.Elasticity > 0 then
				mat = CFrame.new(parentPoint.Position) * parentPoint.TransformOffset.Rotation
				restPosition = (mat * CFrame.new(point.LocalTransformOffset.Position)).Position

				difference = restPosition - point.Position
				point.Position += difference * (Settings.Elasticity * Delta)

				if stiffness > 0 then
					difference = restPosition - point.Position
					length = difference.Magnitude
					maxLength = restLength * (1 - stiffness) * 2
					if length > maxLength then
						point.Position += difference * ((length - maxLength) / length)
					end
				end
			end

			difference = parentPoint.Position - point.Position
			length = difference.Magnitude
			if length > 0 then
				point.Position += difference * ((length - restLength) / length)
			end
		end
	end
end

function module:SkipUpdateParticles(particleTree: particleTree)
	local parentPoint, restLength, stiffness
	local restPosition, difference, length, maxLength

	for _, point in particleTree.Particles do
		if point.ParentIndex >= 1 and not point.Anchored then
			point.LastPosition += particleTree.ObjectMove
			point.Position += particleTree.ObjectMove

			parentPoint = particleTree.Particles[point.ParentIndex]
			restLength = (parentPoint.TransformOffset.Position - point.TransformOffset.Position).Magnitude
			stiffness = self.Settings.Stiffness

			if stiffness > 0 then
				restPosition = parentPoint.Position
					+ CFrame.lookAt(parentPoint.Position, point.Position).LookVector.Unit
						* (parentPoint.Position - point.Position).Magnitude

				difference = restPosition - point.Position
				length = difference.Magnitude
				maxLength = restLength * (1 - stiffness) * 2
				if length > maxLength then
					point.Position += difference * ((length - maxLength) / length)
				end
			end

			difference = parentPoint.Position - point.Position
			length = difference.Magnitude
			if length > restLength then
				point.Position += difference * ((length - restLength) / length)
			end
		else
			point.LastPosition = point.TransformOffset.Position--point.Bone.WorldPosition
			point.Position = point.TransformOffset.Position
		end
	end
end

function module:CalculateTransforms(particleTree: particleTree, Delta: number)
	if self.InRange then
		local parentPoint, boneParent
		local localPosition, referenceCFrame, v0, v1, rotation, factor, alpha

		for _, point in particleTree.Particles do
			if point.ParentIndex >= 1 and point.Anchored == false then
				parentPoint = particleTree.Particles[point.ParentIndex]
				boneParent = parentPoint.Bone

				if parentPoint and boneParent and boneParent:IsA("Bone") and boneParent ~= particleTree.Root then
					localPosition = parentPoint.LocalTransformOffset.Position
					referenceCFrame = parentPoint.TransformOffset
					v0 = referenceCFrame:PointToObjectSpace(localPosition)
					v1 = point.Position - parentPoint.Position
					rotation = Utilities.GetRotationBetween(referenceCFrame.UpVector, v1, v0).Rotation
						* referenceCFrame.Rotation

					factor = 0.00001
					alpha = (1 - factor ^ Delta)

					parentPoint.CalculatedWorldCFrame = boneParent.WorldCFrame:Lerp(CFrame.new(parentPoint.Position) * rotation, alpha)
				end
			end
		end
	end
end

function module:TransformBones(particleTree: particleTree)
	local parentPoint, boneParent

	if self.InRange then
		for _, point in particleTree.Particles do
			if point.ParentIndex >= 1 and point.Anchored == false then
				parentPoint = particleTree.Particles[point.ParentIndex]
				boneParent = parentPoint.Bone

				if parentPoint and boneParent and boneParent:IsA("Bone") and boneParent ~= particleTree.Root then
					if parentPoint.Anchored and self.Settings.AnchorsRotate == false then
						boneParent.WorldCFrame = parentPoint.TransformOffset
					else
						boneParent.WorldCFrame = parentPoint.CalculatedWorldCFrame
					end
				end
			end
		end
	end
end

function module:DEBUG(particleTree: particleTree)
	for _, point in particleTree.Particles do
		if point then
			point.DebugPart.CFrame = CFrame.new(point.Position)
		end
	end
end

function module:RunLoop(particleTree: particleTree, Delta: number, UpdateRate: number)
	local ready = true
	local timeVar = Delta * 10

	if UpdateRate > 0 then
		local frameTime = 1 / UpdateRate
		self.Time += Delta
		ready = false

		if self.Time >= frameTime then
			ready = true
			self.Time = 0
		end
	end

	if ready then
		self:UpdateParticles(particleTree, timeVar, 0)
		self:CorrectParticles(particleTree, timeVar)
	else
		self:SkipUpdateParticles(particleTree)
	end
end

function module:ResetParticles(particleTree: particleTree)
	for _, point in particleTree.Particles do
		point.LastPosition = point.TransformOffset.Position
		point.Position = point.TransformOffset.Position
	end
end

function module:ResetTransforms(particleTree: particleTree)
	local transformOffset

	for _, point in particleTree.Particles do
		if point.Bone == point.Root then
			transformOffset = particleTree.RootPart.CFrame * point.RootTransform
		else
			transformOffset = particleTree.Root.WorldCFrame * point.Transform
		end

		point.Bone.WorldCFrame = transformOffset
	end
end

function module:UpdateBones(Delta: number, UpdateRate: number)
	for _, particleTree: particleTree in self.ParticleTrees do
		self:PreUpdate(particleTree, Delta)
		self:RunLoop(particleTree, Delta, UpdateRate)
		self:CalculateTransforms(particleTree, Delta)
	end
end

function module.Start()
	local Player = game.Players.LocalPlayer

	local ActorsFolder = Instance.new("Folder")
	ActorsFolder.Name = "Actors"
	ActorsFolder.Parent = Player:WaitForChild("PlayerScripts")

	local function DebugPrint(String: string)
		if DEBUG then
			warn(String)
		end
	end

	local SmartBones = {}
	local IgnoreList = {}

	local function registerSmartBoneObject(Object: BasePart)
		if
			Object:IsA("BasePart")
			and Utilities.WaitForChildOfClass(Object, "Bone", 3)
			and game.Workspace:IsAncestorOf(Object)
		then
			local RootList = {}

			if
				Object:GetAttribute("Roots")
				and Object:GetAttribute("Roots") ~= nil
				and typeof(Object:GetAttribute("Roots")) == "string"
			then
				local list = string.split(Object:GetAttribute("Roots"), ",")
				for _, value in ipairs(list) do
					local Bone = Object:FindFirstChild(value, true)
					if Bone and Bone:IsA("Bone") then
						table.insert(RootList, Bone)
					end
				end
			end

			if #RootList > 0 then
				local SmartBoneActor = Instance.new("Actor")

				local Event = Instance.new("BindableFunction")
				Event.Name = "Event"
				Event.Parent = SmartBoneActor

				local RuntimeScript = script.Dependencies.ActorScript:Clone()
				RuntimeScript.Name = "Runtime"
				RuntimeScript.Parent = SmartBoneActor

				SmartBoneActor.Parent = ActorsFolder

				RuntimeScript.Enabled = true

				SmartBones[Object] = SmartBoneActor.Event:Invoke(Object, RootList)

				SmartBoneActor.Name = Object.Name .. SmartBones[Object].ID

				SmartBones[Object].RemovedEvent.Event:Once(function()
					SmartBoneActor.Runtime.Enabled = false
					SmartBoneActor:Destroy()
				end)

				table.insert(IgnoreList, Object)
				DebugPrint("Created new SmartBone Object with ID: " .. SmartBones[Object].ID)
			else
				table.insert(IgnoreList, Object)
				DebugPrint(
					"Failed to create SmartBone Object for "
						.. Object:GetFullName()
						.. "! Make sure you have defined the Root Bone(s) for this object!"
				)
			end
		end
	end

	local function removeSmartBoneObject(Object: BasePart)
		if SmartBones[Object] then
			DebugPrint("Removing SmartBone Object with ID: " .. SmartBones[Object].ID)
			task.spawn(function()
				for _, Connection in pairs(SmartBones[Object].Connections) do
					Connection:Disconnect()
				end

				SmartBones[Object].SimulationConnection:Disconnect()

				task.wait()

				SmartBones[Object].RemovedEvent:Destroy()

				for _, particleTree: particleTree in ipairs(SmartBones[Object].ParticleTrees) do
					for _, _Particle in particleTree.Particles do
						for _, Recycling in _Particle.RecyclingBin do
							Recycling:Destroy()
						end
					end
				end

				task.wait()

				if CurrentControllers[SmartBones[Object].ID] then
					CurrentControllers[SmartBones[Object].ID] = nil
				end

				SmartBones[Object].Removed = true
				SmartBones[Object].RemovedEvent:Fire()

				SmartBones[Object] = nil
			end)
		end
	end

	CollectionService:GetInstanceAddedSignal("SmartBone"):Connect(registerSmartBoneObject)
	CollectionService:GetInstanceRemovedSignal("SmartBone"):Connect(removeSmartBoneObject)

	for _, Object in pairs(SmartBoneTags) do
		if not SmartBones[Object] and not table.find(IgnoreList, Object) then
			task.spawn(function()
				registerSmartBoneObject(Object)
			end)
		end
	end
end

return modulelocal TableUtil = {}

local http = game:GetService("HttpService")

local function CopyTable(t)
	assert(type(t) == "table", "First argument must be a table")
	local tCopy = table.create(#t)
	for k,v in pairs(t) do
		if (type(v) == "table") then
			tCopy[k] = CopyTable(v)
		else
			tCopy[k] = v
		end
	end
	return tCopy
end

local function CopyTableShallow(t)
	local tCopy = table.create(#t)
	for k,v in pairs(t) do tCopy[k] = v end
	return tCopy
end

local function Sync(tbl, templateTbl)

	assert(type(tbl) == "table", "First argument must be a table")
	assert(type(templateTbl) == "table", "Second argument must be a table")
	
	for k,v in pairs(tbl) do
		
		local vTemplate = templateTbl[k]
		if (vTemplate == nil) then
			tbl[k] = nil
		elseif (type(v) ~= type(vTemplate)) then
			if (type(vTemplate) == "table") then
				tbl[k] = CopyTable(vTemplate)
			else
				tbl[k] = vTemplate
			end
		elseif (type(v) == "table") then
			Sync(v, vTemplate)
		end
		
	end
	
	for k,vTemplate in pairs(templateTbl) do
		
		local v = tbl[k]
		
		if (v == nil) then
			if (type(vTemplate) == "table") then
				tbl[k] = CopyTable(vTemplate)
			else
				tbl[k] = vTemplate
			end
		end
	end
end

local function FastRemove(t, i)
	local n = #t
	t[i] = t[n]
	t[n] = nil
end

local function Map(t, f)
	assert(type(t) == "table", "First argument must be a table")
	assert(type(f) == "function", "Second argument must be an array")
	local newT = table.create(#t)
	for k,v in pairs(t) do
		newT[k] = f(v, k, t)
	end
	return newT
end

local function Filter(t, f)
	assert(type(t) == "table", "First argument must be a table")
	assert(type(f) == "function", "Second argument must be an array")
	local newT = table.create(#t)
	if (#t > 0) then
		local n = 0
		for i = 1,#t do
			local v = t[i]
			if (f(v, i, t)) then
				n = (n + 1)
				newT[n] = v
			end
		end
	else
		for k,v in pairs(t) do
			if (f(v, k, t)) then
				newT[k] = v
			end
		end
	end
	return newT
end

local function Reduce(t, f, init)
	assert(type(t) == "table", "First argument must be a table")
	assert(type(f) == "function", "Second argument must be an array")
	assert(init == nil or type(init) == "number", "Third argument must be a number or nil")
	local result = (init or 0)
	for k,v in pairs(t) do
		result = f(result, v, k, t)
	end
	return result
end

local function Assign(target, ...)
	for _,src in ipairs({...}) do
		for k,v in pairs(src) do
			target[k] = v
		end
	end
	return target
end

local function Print(tbl, label, deepPrint)

	assert(type(tbl) == "table", "First argument must be a table")
	assert(label == nil or type(label) == "string", "Second argument must be a string or nil")
	
	label = (label or "TABLE")
	
	local strTbl = {}
	local indent = " - "
	
	local function Insert(s, l)
		strTbl[#strTbl + 1] = (indent:rep(l) .. s .. "\n")
	end
	
	local function AlphaKeySort(a, b)
		return (tostring(a.k) < tostring(b.k))
	end
	
	local function PrintTable(t, lvl, lbl)
		Insert(lbl .. ":", lvl - 1)
		local nonTbls = {}
		local tbls = {}
		local keySpaces = 0
		for k,v in pairs(t) do
			if (type(v) == "table") then
				table.insert(tbls, {k = k, v = v})
			else
				table.insert(nonTbls, {k = k, v = "[" .. typeof(v) .. "] " .. tostring(v)})
			end
			local spaces = #tostring(k) + 1
			if (spaces > keySpaces) then
				keySpaces = spaces
			end
		end
		table.sort(nonTbls, AlphaKeySort)
		table.sort(tbls, AlphaKeySort)
		for _,v in pairs(nonTbls) do
			Insert(tostring(v.k) .. ":" .. (" "):rep(keySpaces - #tostring(v.k)) .. v.v, lvl)
		end
		if (deepPrint) then
			for _,v in pairs(tbls) do
				PrintTable(v.v, lvl + 1, tostring(v.k) .. (" "):rep(keySpaces - #tostring(v.k)) .. " [Table]")
			end
		else
			for _,v in pairs(tbls) do
				Insert(tostring(v.k) .. ":" .. (" "):rep(keySpaces - #tostring(v.k)) .. "[Table]", lvl)
			end
		end
	end
	
	PrintTable(tbl, 1, label)
	
	print(table.concat(strTbl, ""))
	
end


local function IndexOf(tbl, item)
	for i = 1,#tbl do
		if (tbl[i] == item) then
			return i
		end
	end
	return nil
end


local function Reverse(tbl)
	local n = #tbl
	local tblRev = table.create(n)
	for i = 1,n do
		tblRev[i] = tbl[n - i + 1]
	end
	return tblRev
end


local function Shuffle(tbl)
	assert(type(tbl) == "table", "First argument must be a table")
	local rng = Random.new()
	for i = #tbl, 2, -1 do
		local j = rng:NextInteger(1, i)
		tbl[i], tbl[j] = tbl[j], tbl[i]
	end
end


local function IsEmpty(tbl)
	return (next(tbl) == nil)
end


local function EncodeJSON(tbl)
	return http:JSONEncode(tbl)
end


local function DecodeJSON(str)
	return http:JSONDecode(str)
end


local function FastRemoveFirstValue(t, v)
	local index = IndexOf(t, v)
	if (index) then
		FastRemove(t, index)
		return true, index
	end
	return false, nil
end


TableUtil.Copy = CopyTable
TableUtil.CopyShallow = CopyTableShallow
TableUtil.Sync = Sync
TableUtil.FastRemove = FastRemove
TableUtil.FastRemoveFirstValue = FastRemoveFirstValue
TableUtil.Print = Print
TableUtil.Map = Map
TableUtil.Filter = Filter
TableUtil.Reduce = Reduce
TableUtil.Assign = Assign
TableUtil.IndexOf = IndexOf
TableUtil.Reverse = Reverse
TableUtil.Shuffle = Shuffle
TableUtil.IsEmpty = IsEmpty
TableUtil.EncodeJSON = EncodeJSON
TableUtil.DecodeJSON = DecodeJSON


return TableUtil-- LOCAL
local players = game:GetService("Players")
local runService = game:GetService("RunService")
local heartbeat = runService.Heartbeat
local localPlayer = runService:IsClient() and players.LocalPlayer
local replicatedStorage = game:GetService("ReplicatedStorage")
local httpService = game:GetService("HttpService")
local Enum_ = require(script.Enum)
local enum = Enum_.enums
local Janitor = require(script.Janitor)
local Signal = require(script.Signal)
local ZonePlusReference = require(script.ZonePlusReference)
local referenceObject = ZonePlusReference.getObject()
local zoneControllerModule = script.ZoneController
local trackerModule = zoneControllerModule.Tracker
local collectiveWorldModelModule = zoneControllerModule.CollectiveWorldModel
local ZoneController = require(zoneControllerModule)
local referenceLocation = (game:GetService("RunService"):IsClient() and "Client") or "Server"
local referencePresent = referenceObject and referenceObject:FindFirstChild(referenceLocation)
if referencePresent then
	return require(referenceObject.Value)
end

local Zone = {}
Zone.__index = Zone
if not referencePresent then
	ZonePlusReference.addToReplicatedStorage()
end
Zone.enum = enum



-- CONSTRUCTORS
function Zone.new(container)
	local self = {}
	setmetatable(self, Zone)
	
	-- Validate container
	local INVALID_TYPE_WARNING = "The zone container must be a model, folder, basepart or table!"
	local containerType = typeof(container)
	if not(containerType == "table" or containerType == "Instance") then
		error(INVALID_TYPE_WARNING)
	end

	-- Configurable
	self.accuracy = enum.Accuracy.High
	self.autoUpdate = true
	self.respectUpdateQueue = true
	--self.maxPartsAddition = 20
	--self.ignoreRecommendedMaxParts = false

	-- Variable
	local janitor = Janitor.new()
	self.janitor = janitor
	self._updateConnections = janitor:add(Janitor.new(), "destroy")
	self.container = container
	self.zoneParts = {}
	self.overlapParams = {}
	self.region = nil
	self.volume = nil
	self.boundMin = nil
	self.boundMax = nil
	self.recommendedMaxParts = nil
	self.zoneId = httpService:GenerateGUID()
	self.activeTriggers = {}
	self.occupants = {}
	self.trackingTouchedTriggers = {}
	self.enterDetection = enum.Detection.Centre
	self.exitDetection = enum.Detection.Centre
	self._currentEnterDetection = nil -- This will update automatically internally
	self._currentExitDetection = nil -- This will also update automatically internally
	self.totalPartVolume = 0
	self.allZonePartsAreBlocks = true
	self.trackedItems = {}
	self.settingsGroupName = nil
	self.worldModel = workspace
	self.onItemDetails = {}
	self.itemsToUntrack = {}

	-- This updates _currentEnterDetection and _currentExitDetection right away to prevent nil comparisons
	ZoneController.updateDetection(self)

	-- Signals
	self.updated = janitor:add(Signal.new(), "destroy")
	local triggerTypes = {
		"player",
		"part",
		"localPlayer",
		"item"
	}
	local triggerEvents = {
		"entered",
		"exited",
	}
	for _, triggerType in pairs(triggerTypes) do
		local activeConnections = 0
		local previousActiveConnections = 0
		for i, triggerEvent in pairs(triggerEvents) do
			-- this enables us to determine when a developer connects to an event
			-- so that we can act accoridngly (i.e. begin or end a checker loop)
			local signal = janitor:add(Signal.new(true), "destroy")
			local triggerEventUpper = triggerEvent:sub(1,1):upper()..triggerEvent:sub(2)
			local signalName = triggerType..triggerEventUpper
			self[signalName] = signal
			signal.connectionsChanged:Connect(function(increment)
				if triggerType == "localPlayer" and not localPlayer and increment == 1 then
					error(("Can only connect to 'localPlayer%s' on the client!"):format(triggerEventUpper))
				end
				previousActiveConnections = activeConnections
				activeConnections += increment
				if previousActiveConnections == 0 and activeConnections > 0 then
					-- At least 1 connection active, begin loop
					ZoneController._registerConnection(self, triggerType, triggerEventUpper)
				elseif previousActiveConnections > 0 and activeConnections == 0 then
					-- All connections have disconnected, end loop
					ZoneController._deregisterConnection(self, triggerType)
				end
			end)
		end
	end

	-- Setup touched receiver functions where applicable
	Zone.touchedConnectionActions = {}
	for _, triggerType in pairs(triggerTypes) do
		local methodName = ("_%sTouchedZone"):format(triggerType)
		local correspondingMethod = self[methodName]
		if correspondingMethod then
			self.trackingTouchedTriggers[triggerType] = {}
			Zone.touchedConnectionActions[triggerType] = function(touchedItem)
				correspondingMethod(self, touchedItem)
			end
		end
	end

	-- This constructs the zones boundaries, region, etc
	self:_update()

	-- Register/deregister zone
	ZoneController._registerZone(self)
	janitor:add(function()
		ZoneController._deregisterZone(self)
	end, true)
	
	return self
end

function Zone.fromRegion(cframe, size)
	local MAX_PART_SIZE = 2024
	local container = Instance.new("Model")
	local function createCube(cubeCFrame, cubeSize)
		if cubeSize.X > MAX_PART_SIZE or cubeSize.Y > MAX_PART_SIZE or cubeSize.Z > MAX_PART_SIZE then
			local quarterSize = cubeSize * 0.25
			local halfSize = cubeSize * 0.5
			createCube(cubeCFrame * CFrame.new(-quarterSize.X, -quarterSize.Y, -quarterSize.Z), halfSize)
			createCube(cubeCFrame * CFrame.new(-quarterSize.X, -quarterSize.Y, quarterSize.Z), halfSize)
			createCube(cubeCFrame * CFrame.new(-quarterSize.X, quarterSize.Y, -quarterSize.Z), halfSize)
			createCube(cubeCFrame * CFrame.new(-quarterSize.X, quarterSize.Y, quarterSize.Z), halfSize)
			createCube(cubeCFrame * CFrame.new(quarterSize.X, -quarterSize.Y, -quarterSize.Z), halfSize)
			createCube(cubeCFrame * CFrame.new(quarterSize.X, -quarterSize.Y, quarterSize.Z), halfSize)
			createCube(cubeCFrame * CFrame.new(quarterSize.X, quarterSize.Y, -quarterSize.Z), halfSize)
			createCube(cubeCFrame * CFrame.new(quarterSize.X, quarterSize.Y, quarterSize.Z), halfSize)
		else
			local part = Instance.new("Part")
			part.CFrame = cubeCFrame
			part.Size = cubeSize
			part.Anchored = true
			part.Parent = container
		end
	end
	createCube(cframe, size)
	local zone = Zone.new(container)
	zone:relocate()
	return zone
end



-- PRIVATE METHODS
function Zone:_calculateRegion(tableOfParts, dontRound)
	local bounds = {["Min"] = {}, ["Max"] = {}}
	for boundType, details in pairs(bounds) do
		details.Values = {}
		function details.parseCheck(v, currentValue)
			if boundType == "Min" then
				return (v <= currentValue)
			elseif boundType == "Max" then
				return (v >= currentValue)
			end
		end
		function details:parse(valuesToParse)
			for i,v in pairs(valuesToParse) do
				local currentValue = self.Values[i] or v
				if self.parseCheck(v, currentValue) then
					self.Values[i] = v
				end
			end
		end
	end
	for _, part in pairs(tableOfParts) do
		local sizeHalf = part.Size * 0.5
		local corners = {
			part.CFrame * CFrame.new(-sizeHalf.X, -sizeHalf.Y, -sizeHalf.Z),
			part.CFrame * CFrame.new(-sizeHalf.X, -sizeHalf.Y, sizeHalf.Z),
			part.CFrame * CFrame.new(-sizeHalf.X, sizeHalf.Y, -sizeHalf.Z),
			part.CFrame * CFrame.new(-sizeHalf.X, sizeHalf.Y, sizeHalf.Z),
			part.CFrame * CFrame.new(sizeHalf.X, -sizeHalf.Y, -sizeHalf.Z),
			part.CFrame * CFrame.new(sizeHalf.X, -sizeHalf.Y, sizeHalf.Z),
			part.CFrame * CFrame.new(sizeHalf.X, sizeHalf.Y, -sizeHalf.Z),
			part.CFrame * CFrame.new(sizeHalf.X, sizeHalf.Y, sizeHalf.Z),
		}
		for _, cornerCFrame in pairs(corners) do
			local x, y, z = cornerCFrame:GetComponents()
			local values = {x, y, z}
			bounds.Min:parse(values)
			bounds.Max:parse(values)
		end
	end
	local minBound = {}
	local maxBound = {}
	-- Rounding a regions coordinates to multiples of 4 ensures the region optimises the region
	-- by ensuring it aligns on the voxel grid
	local function roundToFour(to_round)
		local ROUND_TO = 4
		local divided = (to_round+ROUND_TO/2) / ROUND_TO
		local rounded = ROUND_TO * math.floor(divided)
		return rounded
	end
	for boundName, boundDetail in pairs(bounds) do
		for _, v in pairs(boundDetail.Values) do
			local newTable = (boundName == "Min" and minBound) or maxBound
			local newV = v
			if not dontRound then
				local roundOffset = (boundName == "Min" and -2) or 2
				newV = roundToFour(v+roundOffset) -- +-2 to ensures the zones region is not rounded down/up
			end
			table.insert(newTable, newV)
		end
	end
	local boundMin = Vector3.new(unpack(minBound))
	local boundMax = Vector3.new(unpack(maxBound))
	local region = Region3.new(boundMin, boundMax)
	return region, boundMin, boundMax
end

function Zone:_displayBounds()
	if not self.displayBoundParts then
		self.displayBoundParts = true
		local boundParts = {BoundMin = self.boundMin, BoundMax = self.boundMax}
		for boundName, boundCFrame in pairs(boundParts) do
			local part = Instance.new("Part")
			part.Anchored = true
			part.CanCollide = false
			part.Transparency = 0.5
			part.Size = Vector3.new(1,1,1)
			part.Color = Color3.fromRGB(255,0,0)
			part.CFrame = CFrame.new(boundCFrame)
			part.Name = boundName
			part.Parent = workspace
			self.janitor:add(part, "Destroy")
		end
	end
end

function Zone:_update()
	local container = self.container
	local zoneParts = {}
	local updateQueue = 0
	self._updateConnections:clean()

	local containerType = typeof(container)
	local holders = {}
	local INVALID_TYPE_WARNING = "The zone container must be a model, folder, basepart or table!"
	if containerType == "table" then
		for _, part in pairs(container) do
			if part:IsA("BasePart") then
				table.insert(zoneParts, part)
			end
		end
	elseif containerType == "Instance" then
		if container:IsA("BasePart") then
			table.insert(zoneParts, container)
		else
			table.insert(holders, container)
			for _, part in pairs(container:GetDescendants()) do
				if part:IsA("BasePart") then
					table.insert(zoneParts, part)
				else
					table.insert(holders, part)
				end
			end
		end
	end
	self.zoneParts = zoneParts
	self.overlapParams = {}
	
	local allZonePartsAreBlocksNew = true
	for _, zonePart in pairs(zoneParts) do
		local success, shapeName = pcall(function() return zonePart.Shape.Name end)
		if shapeName ~= "Block" then
			allZonePartsAreBlocksNew = false
		end
	end
	self.allZonePartsAreBlocks = allZonePartsAreBlocksNew
	
	local zonePartsWhitelist = OverlapParams.new()
	zonePartsWhitelist.FilterType = Enum.RaycastFilterType.Include
	zonePartsWhitelist.MaxParts = #zoneParts
	zonePartsWhitelist.FilterDescendantsInstances = zoneParts
	self.overlapParams.zonePartsWhitelist = zonePartsWhitelist

	local zonePartsIgnorelist = OverlapParams.new()
	zonePartsIgnorelist.FilterType = Enum.RaycastFilterType.Include
	zonePartsIgnorelist.FilterDescendantsInstances = zoneParts
	self.overlapParams.zonePartsIgnorelist = zonePartsIgnorelist

	local function update()
		if self.autoUpdate then
			local executeTime = os.clock()
			if self.respectUpdateQueue then
				updateQueue += 1
				executeTime += 0.1
			end
			local updateConnection
			updateConnection = runService.Heartbeat:Connect(function()
				if os.clock() >= executeTime then
					updateConnection:Disconnect()
					if self.respectUpdateQueue then
						updateQueue -= 1
					end
					if updateQueue == 0 and self.zoneId then
						self:_update()
					end
				end
			end)
		end
	end
	local partProperties = {"Size", "Position"}
	local function verifyDefaultCollision(instance)
		if instance.CollisionGroupId ~= 0 then
			error("Zone parts must belong to the 'Default' (0) CollisionGroup! Consider using zone:relocate() if you wish to move zones outside of workspace to prevent them interacting with other parts.")
		end
	end
	for _, part in pairs(zoneParts) do
		for _, prop in pairs(partProperties) do
			self._updateConnections:add(part:GetPropertyChangedSignal(prop):Connect(update), "Disconnect")
		end
		verifyDefaultCollision(part)
		self._updateConnections:add(part:GetPropertyChangedSignal("CollisionGroupId"):Connect(function()
			verifyDefaultCollision(part)
		end), "Disconnect")
	end
	local containerEvents = {"ChildAdded", "ChildRemoved"}
	for _, holder in pairs(holders) do
		for _, event in pairs(containerEvents) do
			self._updateConnections:add(self.container[event]:Connect(function(child)
				if child:IsA("BasePart") then
					update()
				end
			end), "Disconnect")
		end
	end
	
	local region, boundMin, boundMax = self:_calculateRegion(zoneParts)
	local exactRegion, _, _ = self:_calculateRegion(zoneParts, true)
	self.region = region
	self.exactRegion = exactRegion
	self.boundMin = boundMin
	self.boundMax = boundMax
	local rSize = region.Size
	self.volume = rSize.X*rSize.Y*rSize.Z
	
	self:_updateTouchedConnections()
	
	self.updated:Fire()
end

function Zone:_updateOccupants(trackerName, newOccupants)
	local previousOccupants = self.occupants[trackerName]
	if not previousOccupants then
		previousOccupants = {}
		self.occupants[trackerName] = previousOccupants
	end
	local signalsToFire = {}
	for occupant, prevItem in pairs(previousOccupants) do
		local newItem = newOccupants[occupant]
		if newItem == nil or newItem ~= prevItem then
			previousOccupants[occupant] = nil
			if not signalsToFire.exited then
				signalsToFire.exited = {}
			end
			table.insert(signalsToFire.exited, occupant)
		end
	end
	for occupant, _ in pairs(newOccupants) do
		if previousOccupants[occupant] == nil then
			local isAPlayer = occupant:IsA("Player")
			previousOccupants[occupant] = (isAPlayer and occupant.Character) or true
			if not signalsToFire.entered then
				signalsToFire.entered = {}
			end
			table.insert(signalsToFire.entered, occupant)
		end
	end 
	return signalsToFire
end

function Zone:_formTouchedConnection(triggerType)
	local touchedJanitorName = "_touchedJanitor"..triggerType
	local touchedJanitor = self[touchedJanitorName]
	if touchedJanitor then
		touchedJanitor:clean()
	else
		touchedJanitor = self.janitor:add(Janitor.new(), "destroy")
		self[touchedJanitorName] = touchedJanitor
	end
	self:_updateTouchedConnection(triggerType)
end

function Zone:_updateTouchedConnection(triggerType)
	local touchedJanitorName = "_touchedJanitor"..triggerType
	local touchedJanitor = self[touchedJanitorName]
	if not touchedJanitor then return end
	for _, basePart in pairs(self.zoneParts) do
		touchedJanitor:add(basePart.Touched:Connect(self.touchedConnectionActions[triggerType], self), "Disconnect")
	end
end

function Zone:_updateTouchedConnections()
	for triggerType, _ in pairs(self.touchedConnectionActions) do
		local touchedJanitorName = "_touchedJanitor"..triggerType
		local touchedJanitor = self[touchedJanitorName]
		if touchedJanitor then
			touchedJanitor:cleanup()
			self:_updateTouchedConnection(triggerType)
		end
	end
end

function Zone:_disconnectTouchedConnection(triggerType)
	local touchedJanitorName = "_touchedJanitor"..triggerType
	local touchedJanitor = self[touchedJanitorName]
	if touchedJanitor then
		touchedJanitor:cleanup()
		self[touchedJanitorName] = nil
	end
end

local function round(number, decimalPlaces)
	return math.round(number * 10^decimalPlaces) * 10^-decimalPlaces
end
function Zone:_partTouchedZone(part)
	local trackingDict = self.trackingTouchedTriggers["part"]
	if trackingDict[part] then return end
	local nextCheck = 0
	local verifiedEntrance = false
	local enterPosition = part.Position
	local enterTime = os.clock()
	local partJanitor = self.janitor:add(Janitor.new(), "destroy")
	trackingDict[part] = partJanitor
	local instanceClassesToIgnore = {Seat = true, VehicleSeat = true}
	local instanceNamesToIgnore = {HumanoidRootPart = true}
	if not (instanceClassesToIgnore[part.ClassName] or not instanceNamesToIgnore[part.Name])  then
		part.CanTouch = false
	end

	local partVolume = round((part.Size.X * part.Size.Y * part.Size.Z), 5)
	self.totalPartVolume += partVolume

	partJanitor:add(heartbeat:Connect(function()
		local clockTime = os.clock()
		if clockTime >= nextCheck then

			local cooldown = enum.Accuracy.getProperty(self.accuracy)
			nextCheck = clockTime + cooldown
			
			local withinZone = self:findPoint(part.CFrame)
			if not withinZone then
				withinZone = self:findPart(part)
			end
			if not verifiedEntrance then
				if withinZone then
					verifiedEntrance = true
					self.partEntered:Fire(part)
				elseif (part.Position - enterPosition).Magnitude > 1.5 and clockTime - enterTime >= cooldown then
					partJanitor:cleanup()
				end
			elseif not withinZone then
				verifiedEntrance = false
				enterPosition = part.Position
				enterTime = os.clock()
				self.partExited:Fire(part)
			end
		end
	end), "Disconnect")
	partJanitor:add(function()
		trackingDict[part] = nil
		part.CanTouch = true
		self.totalPartVolume = round((self.totalPartVolume - partVolume), 5)
	end, true)
end

local partShapeActions = {
	["Ball"] = function(part)
		return "GetPartBoundsInRadius", {part.Position, part.Size.X}
	end,
	["Block"] = function(part)
		return "GetPartBoundsInBox", {part.CFrame, part.Size}
	end,
	["Other"] = function(part)
		return "GetPartsInPart", {part}
	end,
}
function Zone:_getRegionConstructor(part, overlapParams)
	local success, shapeName = pcall(function() return part.Shape.Name end)
	local methodName, args
	if success and self.allZonePartsAreBlocks then
		local action = partShapeActions[shapeName]
		if action then
			methodName, args = action(part)
		end
	end
	if not methodName then
		methodName, args = partShapeActions.Other(part)
	end
	if overlapParams then
		table.insert(args, overlapParams)
	end
	return methodName, args
end

-- PUBLIC METHODS
function Zone:findLocalPlayer()
	if not localPlayer then
		error("Can only call 'findLocalPlayer' on the client!")
	end
	return self:findPlayer(localPlayer)
end

function Zone:_find(trackerName, item)
	ZoneController.updateDetection(self)
	local tracker = ZoneController.trackers[trackerName]
	local touchingZones = ZoneController.getTouchingZones(item, false, self._currentEnterDetection, tracker)
	for _, zone in pairs(touchingZones) do
		if zone == self then
			return true
		end
	end
	return false
end

function Zone:findPlayer(player)
	local character = player.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	if not humanoid then
		return false
	end
	return self:_find("player", player.Character)
end

function Zone:findItem(item)
	return self:_find("item", item)
end

function Zone:findPart(part)
	local methodName, args = self:_getRegionConstructor(part, self.overlapParams.zonePartsWhitelist)
	local touchingZoneParts = self.worldModel[methodName](self.worldModel, unpack(args))
	--local touchingZoneParts = self.worldModel:GetPartsInPart(part, self.overlapParams.zonePartsWhitelist)
	if #touchingZoneParts > 0 then
		return true, touchingZoneParts
	end
	return false
end

function Zone:getCheckerPart()
	local checkerPart = self.checkerPart
	if not checkerPart then
		checkerPart = self.janitor:add(Instance.new("Part"), "Destroy")
		checkerPart.Size = Vector3.new(0.1, 0.1, 0.1)
		checkerPart.Name = "ZonePlusCheckerPart"
		checkerPart.Anchored = true
		checkerPart.Transparency = 1
		checkerPart.CanCollide = false
		self.checkerPart = checkerPart
	end
	local checkerParent = self.worldModel
	if checkerParent == workspace then
		checkerParent = ZoneController.getWorkspaceContainer()
	end
	if checkerPart.Parent ~= checkerParent then
		checkerPart.Parent = checkerParent
	end
	return checkerPart
end

function Zone:findPoint(positionOrCFrame)
	local cframe = positionOrCFrame
	if typeof(positionOrCFrame) == "Vector3" then
		cframe = CFrame.new(positionOrCFrame)
	end
	local checkerPart = self:getCheckerPart()
	checkerPart.CFrame = cframe
	--checkerPart.Parent = self.worldModel
	local methodName, args = self:_getRegionConstructor(checkerPart, self.overlapParams.zonePartsWhitelist)
	local touchingZoneParts = self.worldModel[methodName](self.worldModel, unpack(args))
	--local touchingZoneParts = self.worldModel:GetPartsInPart(self.checkerPart, self.overlapParams.zonePartsWhitelist)
	if #touchingZoneParts > 0 then
		return true, touchingZoneParts
	end
	return false
end

function Zone:_getAll(trackerName)
	ZoneController.updateDetection(self)
	local itemsArray = {}
	local zonesAndOccupants = ZoneController._getZonesAndItems(trackerName, {self = true}, self.volume, false, self._currentEnterDetection)
	local occupantsDict = zonesAndOccupants[self]
	if occupantsDict then
		for item, _ in pairs(occupantsDict) do
			table.insert(itemsArray, item)
		end
	end
	return itemsArray
end

function Zone:getPlayers()
	return self:_getAll("player")
end

function Zone:getItems()
	return self:_getAll("item")
end

function Zone:getParts()
	-- This is designed for infrequent 'one off' use
	-- If you plan on checking for parts within a zone frequently, it's recommended you
	-- use the .partEntered and .partExited events instead.
	local partsArray = {}
	if self.activeTriggers["part"] then
		local trackingDict = self.trackingTouchedTriggers["part"]
		for part, _ in pairs(trackingDict) do
			table.insert(partsArray, part)
		end
		return partsArray
	end
	local partsInRegion = self.worldModel:GetPartBoundsInBox(self.region.CFrame, self.region.Size, self.overlapParams.zonePartsIgnorelist)
	for _, part in pairs(partsInRegion) do
		if self:findPart(part) then
			table.insert(partsArray, part)
		end
	end
	return partsArray
end

function Zone:getRandomPoint()
	local region = self.exactRegion
	local size = region.Size
	local cframe = region.CFrame
	local random = Random.new()
	local randomCFrame
	local success, touchingZoneParts
	local pointIsWithinZone
	local totalPartsInZone = #self.overlapParams.zonePartsWhitelist.FilterDescendantsInstances
	if totalPartsInZone <= 0 then
		-- Its important we return if there are no parts within the zone otherwise the checks below will recur infinitely.
		-- This could occur for example if streaming is enabled and the zone's parts disappear on the client
		return nil
	end
	repeat
		randomCFrame = cframe * CFrame.new(random:NextNumber(-size.X/2,size.X/2), random:NextNumber(-size.Y/2,size.Y/2), random:NextNumber(-size.Z/2,size.Z/2))
		success, touchingZoneParts = self:findPoint(randomCFrame)
		if success then
			pointIsWithinZone = true
		end
	until pointIsWithinZone
	local randomVector = randomCFrame.Position
	return randomVector, touchingZoneParts
end

function Zone:setAccuracy(enumIdOrName)
	local enumId = tonumber(enumIdOrName)
	if not enumId then
		enumId = enum.Accuracy[enumIdOrName]
		if not enumId then
			error(("'%s' is an invalid enumName!"):format(enumIdOrName))
		end
	else
		local enumName = enum.Accuracy.getName(enumId)
		if not enumName then
			error(("%s is an invalid enumId!"):format(enumId))
		end
	end
	self.accuracy = enumId
end

function Zone:setDetection(enumIdOrName)
	local enumId = tonumber(enumIdOrName)
	if not enumId then
		enumId = enum.Detection[enumIdOrName]
		if not enumId then
			error(("'%s' is an invalid enumName!"):format(enumIdOrName))
		end
	else
		local enumName = enum.Detection.getName(enumId)
		if not enumName then
			error(("%s is an invalid enumId!"):format(enumId))
		end
	end
	self.enterDetection = enumId
	self.exitDetection = enumId
end

function Zone:trackItem(instance)
	local isBasePart = instance:IsA("BasePart")
	local isCharacter = false
	if not isBasePart then
		isCharacter = instance:FindFirstChildOfClass("Humanoid") and instance:FindFirstChild("HumanoidRootPart")
	end

	assert(isBasePart or isCharacter, "Only BaseParts or Characters/NPCs can be tracked!")

	if self.trackedItems[instance] then
		return
	end
	if self.itemsToUntrack[instance] then
		self.itemsToUntrack[instance] = nil
	end

	local itemJanitor = self.janitor:add(Janitor.new(), "destroy")
	local itemDetail = {
		janitor = itemJanitor,
		item = instance,
		isBasePart = isBasePart,
		isCharacter = isCharacter,
	}
	self.trackedItems[instance] = itemDetail

	itemJanitor:add(instance.AncestryChanged:Connect(function()
		if not instance:IsDescendantOf(game) then
			self:untrackItem(instance)
		end
	end), "Disconnect")

	local Tracker = require(trackerModule)
	Tracker.itemAdded:Fire(itemDetail)
end

function Zone:untrackItem(instance)
	local itemDetail = self.trackedItems[instance]
	if itemDetail then
		itemDetail.janitor:destroy()
	end
	self.trackedItems[instance] = nil

	local Tracker = require(trackerModule)
	Tracker.itemRemoved:Fire(itemDetail)
end

function Zone:bindToGroup(settingsGroupName)
	self:unbindFromGroup()
	local group = ZoneController.getGroup(settingsGroupName) or ZoneController.setGroup(settingsGroupName)
	group._memberZones[self.zoneId] = self
	self.settingsGroupName = settingsGroupName
end

function Zone:unbindFromGroup()
	if self.settingsGroupName then
		local group = ZoneController.getGroup(self.settingsGroupName)
		if group then
			group._memberZones[self.zoneId] = nil
		end
		self.settingsGroupName = nil
	end
end

function Zone:relocate()
	if self.hasRelocated then
		return
	end

	local CollectiveWorldModel = require(collectiveWorldModelModule)
	local worldModel = CollectiveWorldModel.setupWorldModel(self)
	self.worldModel = worldModel
	self.hasRelocated = true
	
	local relocationContainer = self.container
	if typeof(relocationContainer) == "table" then
		relocationContainer = Instance.new("Folder")
		for _, zonePart in pairs(self.zoneParts) do
			zonePart.Parent = relocationContainer
		end
	end
	self.relocationContainer = self.janitor:add(relocationContainer, "Destroy", "RelocationContainer")
	relocationContainer.Parent = worldModel
end

function Zone:_onItemCallback(eventName, desiredValue, instance, callbackFunction)
	local detail = self.onItemDetails[instance]
	if not detail then
		detail = {}
		self.onItemDetails[instance] = detail
	end
	if #detail == 0 then
		self.itemsToUntrack[instance] = true
	end
	table.insert(detail, instance)
	self:trackItem(instance)

	local function triggerCallback()
		callbackFunction()
		if self.itemsToUntrack[instance] then
			self.itemsToUntrack[instance] = nil
			self:untrackItem(instance)
		end
	end

	local inZoneAlready = self:findItem(instance)
	if inZoneAlready == desiredValue then
		triggerCallback()
	else
		local connection
		connection = self[eventName]:Connect(function(item)
			if connection and item == instance then
				connection:Disconnect()
				connection = nil
				triggerCallback()
			end
		end)
		--[[
		if typeof(expireAfterSeconds) == "number" then
			task.delay(expireAfterSeconds, function()
				if connection ~= nil then
					connection:Disconnect()
					connection = nil
					triggerCallback()
				end
			end)
		end
		--]]
	end
end

function Zone:onItemEnter(...)
	self:_onItemCallback("itemEntered", true, ...)
end

function Zone:onItemExit(...)
	self:_onItemCallback("itemExited", false, ...)
end

function Zone:destroy()
	self:unbindFromGroup()
	self.janitor:destroy()
end
Zone.Destroy = Zone.destroy



