local part = script.Parent
local sounds = {}

-- Collect all sound objects in the part
for _, child in part:GetChildren() do
    if child:IsA("Sound") then
        table.insert(sounds, child)
    end
end

-- Function to play random sounds
local function playRandomSounds()
    local lastSoundIndex = nil
    while true do
        local randomIndex
        repeat
            randomIndex = math.random(1, #sounds)
        until randomIndex ~= lastSoundIndex
        
        local randomSound = sounds[randomIndex]
        randomSound:Play()
        lastSoundIndex = randomIndex
        
        local delayTime = math.random(1, 12)
        task.wait(delayTime)
    end
end

-- Start playing sounds
playRandomSounds()

