local clickDetector = parent:FindFirstChild("ClickDetector")
local sfw1 = parent:FindFirstChild("SFW1")  -- Texture 1
local sfw2 = parent:FindFirstChild("SFW2")  -- Texture 2
local sfw3 = parent:FindFirstChild("SFW3")  -- Texture 3
local sfw4 = parent:FindFirstChild("SFW4")  -- Texture 4
local sfw5 = parent:FindFirstChild("SFW5")  -- Texture 5
local sfw6 = parent:FindFirstChild("SFW6")  -- Texture 5
local sfw7 = parent:FindFirstChild("SFW7")  -- Texture 7
local surfaceLight = parent:FindFirstChild("SurfaceLight") -- The SurfaceLight inside the part
local event = game:GetService("ReplicatedStorage"):FindFirstChild("TextureChangeEvent")

-- Ensure all required objects exist
if not (clickDetector and sfw1 and sfw2 and sfw3 and sfw4 and event and surfaceLight) then
	warn("Missing ClickDetector, textures, SurfaceLight, or RemoteEvent!")
	return
end

-- Store textures and their associated colors
local textures = {
	{texture = sfw1, color = Color3.fromRGB(255, 202, 246)},  -- State 1 (SFW1)
	{texture = sfw2, color = Color3.fromRGB(203, 235, 255)},  -- State 2 (SFW2)
	{texture = sfw3, color = Color3.fromRGB(255, 176, 96)},  -- State 3 (SFW3)
	{texture = sfw4, color = Color3.fromRGB(248, 42, 255)},  -- State 4 (SFW4)
	{texture = sfw5, color = Color3.fromRGB(248, 255, 255)},  -- State 5 (SFW5)
	{texture = sfw6, color = Color3.fromRGB(255, 238, 252)},  -- State 6 (SFW6)
	{texture = sfw7, color = Color3.fromRGB(165, 219, 255)},  -- State 7 (SFW7)
	{texture = nil,  color = Color3.fromRGB(0, 0, 0)}  -- State 4 (OFF - all textures hidden)
}

local currentIndex = 1 -- Start at SFW1

local function cycleTextures()
	local currentTextureData = textures[currentIndex]  -- Store current texture data
	local nextIndex = (currentIndex % #textures) + 1  -- Move to next state
	local nextTextureData = textures[nextIndex]  -- Store next texture data

	-- Hide the current texture
	if currentTextureData.texture then
		currentTextureData.texture.Transparency = 1
	end

	-- Show the next texture (unless it's the OFF state)
	if nextTextureData.texture then
		nextTextureData.texture.Transparency = 0
	end

	-- Change the SurfaceLight color or turn it off
	if nextIndex == 8 then
		surfaceLight.Enabled = false  -- Turn OFF light in OFF state
	else
		surfaceLight.Color = nextTextureData.color
		surfaceLight.Enabled = true  -- Keep light ON for other states
	end

	-- Fire event so all clients see the change
	if event then
		event:FireAllClients(currentIndex, nextIndex, nextTextureData.color)
	end

	-- Update index
	currentIndex = nextIndex
end

clickDetector.MouseClick:Connect(cycleTextures)
local parent = script.Parent
