local event = game:GetService("ReplicatedStorage"):FindFirstChild("TextureChangeEvent")

-- Safety check
if not (clickDetector and sfw1 and surfaceLight and event) then
	warn("Missing required components!")
	return
end

-- Initial state (ON)
local isOn = false
sfw1.Transparency = 1
surfaceLight.Enabled = false
surfaceLight.Color = Color3.fromRGB(255, 237, 208) -- Or any color you want

local function toggleTexture()
	isOn = not isOn  -- Flip state

	if isOn then
		sfw1.Transparency = 0
		surfaceLight.Enabled = true
	else
		sfw1.Transparency = 1
		surfaceLight.Enabled = false
	end

	-- Fire event to notify clients
	event:FireAllClients(isOn)
end

clickDetector.MouseClick:Connect(toggleTexture)
