	-- Only change material if necessary
	if part.Material ~= Enum.Material.Metal then
		part.Material = Enum.Material.Metal
	end

	-- Disable light if it exists
	if light and light.Enabled then
		light.Enabled = false
	end

	-- Play sound if it exists
	if sound then
		sound:Play()
	end

	task.wait(0.3) -- Short wait before switching back

	-- Only change material if necessary
	if part.Material ~= Enum.Material.Neon then
		part.Material = Enum.Material.Neon
	end

	-- Enable light and randomize range if it exists
	if light then
		light.Enabled = true
		light.Range = math.random(24, 30)
	end
end
