local function playRandomSounds()
    local lastSoundIndex = nil
    while true do
        local randomIndex
        repeat
            randomIndex = math.random(1, #sounds)
        until randomIndex ~= lastSoundIndex
        
        local randomSound = sounds[randomIndex]
        randomSound:Play()
        lastSoundIndex = randomIndex
        
        local delayTime = math.random(1, 12)
        task.wait(delayTime)
    end
end

