-- May not work if there are multiple models of this in the game
function Weld(x,y)
	local W = Instance.new("Weld")
	W.Part0 = x
	W.Part1 = y
	local CJ = CFrame.new(x.Position)
	local C0 = x.CFrame:inverse()*CJ
	local C1 = y.CFrame:inverse()*CJ
	W.C0 = C0
	W.C1 = C1
	W.Parent = x
	y.Anchored = false
end

function Get(A)
	if (A.className == "UnionOperation") then
		Weld(script.Parent.Base, A)
	else
		local C = A:GetChildren()
		if A:FindFirstChild("HingeA") ~= nil then
		Weld(script.Parent.Base, A.HingeA)
		else
		for i=1, #C do
		Get(C[i])
		end
		end
	end
end

function Finale()
	Get(script.Parent)
end

Finale()
