local hotWater = 1
local coldWater = 1
local waterTemp = nil
local p = script.Parent

-- Water and sounds --
local showerSound = p.ShowerHead.Spout.ShowerSound

-- Important parts --
local faucet = p.Faucet
local steam = p:WaitForChild("Steam")
--local warmSteam = steam:WaitForChild("WarmSteam")
--local hotSteam = steam:WaitForChild("HotSteam")
local showerHead = p.ShowerHead.Spout.ParticleEmitter

----- Handle position handler -----

-- Cold water
faucet.ColdWaterSet.Interactive.ClickDetector.MouseClick:Connect(function()
	faucet.Handle:SetPrimaryPartCFrame(faucet.HandleBase.CFrame * CFrame.Angles(math.rad(-30),0,0))
	if steam.WarmSteam.Enabled == true then
	steam.WarmSteam.Enabled = false
	end
	if steam.HotSteam.Enabled == true then
	steam.HotSteam.Enabled = false
	end
	p.ColdOn.Value = true
	p.HotOn.Value = false
end)

-- Warm water
faucet.WarmWaterSet.Interactive.ClickDetector.MouseClick:Connect(function()
	faucet.Handle:SetPrimaryPartCFrame(faucet.HandleBase.CFrame * CFrame.Angles(math.rad(-90),0,0))
	if steam.HotSteam.Enabled == true then
	steam.HotSteam.Enabled = false
	end
	steam.WarmSteam.Enabled = true
	p.HotOn.Value = true
	p.ColdOn.Value = true
end)

-- Hot water
faucet.HotWaterSet.Interactive.ClickDetector.MouseClick:Connect(function()
	faucet.Handle:SetPrimaryPartCFrame(faucet.HandleBase.CFrame * CFrame.Angles(math.rad(-150),0,0))
	if steam.WarmSteam.Enabled == true then
	steam.WarmSteam.Enabled = false
	end
	steam.HotSteam.Enabled = true
	p.HotOn.Value = true
	p.ColdOn.Value = false
end)

-- Water off
faucet.WaterOffSet.Interactive.ClickDetector.MouseClick:Connect(function()
	faucet.Handle:SetPrimaryPartCFrame(faucet.HandleBase.CFrame)
	if steam.WarmSteam.Enabled == true then
	steam.WarmSteam.Enabled = false
	end
	if steam.HotSteam.Enabled == true then
	steam.HotSteam.Enabled = false
	end
	p.HotOn.Value = false
	p.ColdOn.Value = false
end)

