local function cleanup()
	for _, cls in pairs({"SunRaysEffect","BloomEffect","ColorCorrectionEffect","Atmosphere","Sky"}) do
		for _, obj in pairs(Lighting:GetChildren()) do
			if obj:IsA(cls) then
				obj:Destroy()
			end
		end
	end
end

local function apply(settings)
	cleanup() 

	if settings.ClockTime then TweenService:Create(Lighting, TweenInfo.new(1), {ClockTime = settings.ClockTime}):Play() end
	if settings.Brightness then TweenService:Create(Lighting, TweenInfo.new(1), {Brightness = settings.Brightness}):Play() end
	if settings.Ambient then TweenService:Create(Lighting, TweenInfo.new(1), {Ambient = settings.Ambient}):Play() end
	if settings.FogEnd then TweenService:Create(Lighting, TweenInfo.new(1), {FogEnd = settings.FogEnd}):Play() end
	if settings.FogStart then TweenService:Create(Lighting, TweenInfo.new(1), {FogStart = settings.FogStart}):Play() end

	if settings.OriginalObjects then
		for _, obj in pairs(settings.OriginalObjects) do
			obj:Clone().Parent = Lighting
		end
	end

	if settings.FutureSkyColor then
		local sky = Instance.new("Sky", Lighting)
		sky.SkyboxBk = ""
		sky.SkyboxDn = ""
		sky.SkyboxFt = ""
		sky.SkyboxLf = ""
		sky.SkyboxRt = ""
		sky.SkyboxUp = ""
	end

	if settings.SunRays then
		local sun = Instance.new("SunRaysEffect", Lighting)
		sun.Intensity = settings.SunRays.Intensity or 0
		sun.Spread = settings.SunRays.Spread or 0.2
	end

	if settings.FutureFog then
		local atmos = Instance.new("Atmosphere", Lighting)
		for k,v in pairs(settings.FutureFog) do atmos[k] = v end
	end

	if settings.Bloom then
		local bloom = Instance.new("BloomEffect", Lighting)
		for k,v in pairs(settings.Bloom) do bloom[k] = v end
	end
	
	if settings.ColorCorrection then
		local cc = Instance.new("ColorCorrectionEffect", Lighting)
		for k,v in pairs(settings.ColorCorrection) do cc[k] = v end
	end
end

local function createButton(name, settings)
	local btn = templateButton:Clone()
	btn.Name = name.."Button"
	btn.Text = name
	btn.Parent = scrollFrame
	btn.Visible = true
	btn.MouseButton1Click:Connect(function()
		apply(settings)
	end)
end

