local UserInputService = game:GetService("UserInputService")
local Players = game:GetService("Players")
local player = Players.LocalPlayer
local camera = workspace.CurrentCamera

local camButton = script.Parent
local cameraFrame = camButton:FindFirstChild("Camera") -- the frame that has the overlay
local overlayVisible = false

local cameraParts = {
	workspace:WaitForChild("PrivateCameraPart1"),
	workspace:WaitForChild("PrivateCameraPart2"),
	workspace:WaitForChild("PrivateCameraPart3")
}

local currentView = 0 -- 0 = Player, 1 = Camera1, 2 = Camera2
local originalCameraCFrame
local originalCameraFOV
local uiVisibilityState = {}

local minFOV = 20
local maxFOV = 50
local fovStep = 0.8

local shakeThread = nil
local shakeRunning = false

-- Camera shake function
local function smoothShake(cameraPart)
	local shakeMagnitude = 0.05
	local shakeSpeed = 0.1
	local timeElapsed = 0

	while shakeRunning do
		local offsetX = math.sin(timeElapsed * shakeSpeed) * shakeMagnitude * 0.1
		local offsetY = math.cos(timeElapsed * shakeSpeed * 0.05) * shakeMagnitude
		local offsetZ = math.sin(timeElapsed * shakeSpeed * 0.1) * shakeMagnitude * 0.1

		local offset = Vector3.new(offsetX, offsetY, offsetZ)
		camera.CFrame = cameraPart.CFrame * CFrame.new(offset)

		timeElapsed += task.wait(0.03)
	end

	camera.CFrame = cameraPart.CFrame
end

-- Handle FOV zoom
UserInputService.InputChanged:Connect(function(input)
	if currentView ~= 0 and input.UserInputType == Enum.UserInputType.MouseWheel then
		local newFOV = math.clamp(camera.FieldOfView + (-input.Position.Z * fovStep), minFOV, maxFOV)
		camera.FieldOfView = newFOV
	end
end)

-- Hide overlay frame
local function hideOverlay()
	if cameraFrame then
		cameraFrame.Visible = true
	end
end

-- Show overlay frame
local function showOverlay()
	if cameraFrame then
		cameraFrame.Visible = false
	end
end

-- Return to player view
local function setToPlayerView()
	camera.CameraType = Enum.CameraType.Custom
	camera.CFrame = originalCameraCFrame or camera.CFrame
	camera.FieldOfView = originalCameraFOV or 70

	-- Restore all GUI
	for gui, wasEnabled in pairs(uiVisibilityState) do
		if gui and gui.Parent then
			gui.Enabled = wasEnabled
		end
	end

	-- Hide camera overlay
	hideOverlay()

	-- Stop shake
	shakeRunning = false
	if shakeThread then
		task.cancel(shakeThread)
		shakeThread = nil
	end

	currentView = 0
end

-- Switch to camera view (1 or 2)
local function setToCameraView(index)
	if currentView == 0 then
		-- Save original camera
		originalCameraCFrame = camera.CFrame
		originalCameraFOV = camera.FieldOfView

		-- Hide all other GUIs except the one holding camButton
		uiVisibilityState = {}
		for _, gui in ipairs(player.PlayerGui:GetChildren()) do
			if gui:IsA("ScreenGui") and gui ~= camButton.Parent then
				uiVisibilityState[gui] = gui.Enabled
				gui.Enabled = false
			end
		end
	end

	camera.CameraType = Enum.CameraType.Scriptable
	camera.CFrame = cameraParts[index].CFrame
	camera.FieldOfView = maxFOV

	-- Show overlay
	showOverlay()

	-- Shake
	shakeRunning = false
	if shakeThread then
		task.cancel(shakeThread)
	end
	shakeRunning = true
	shakeThread = task.spawn(function()
		smoothShake(cameraParts[index])
	end)

	currentView = index
end

-- Cycle views: Player → Cam1 → Cam2 → Player
local function toggleCamera()
	if currentView == 0 then
		setToCameraView(1)
	elseif currentView == 1 then
		setToCameraView(2)
	elseif currentView == 2 then
		setToCameraView(3)
	elseif currentView == 3 then
		setToPlayerView()
	end
end

camButton.MouseButton1Click:Connect(toggleCamera)

-- Emergency reset button binding (e.g., press "R" to return to player view if stuck)
UserInputService.InputBegan:Connect(function(input, gameProcessed)
	if not gameProcessed then
		if input.KeyCode == Enum.KeyCode.J then
			setToPlayerView()
		elseif input.KeyCode == Enum.KeyCode.Y then
			toggleCamera()
		end
	end
end)
