	if Mode == "Start" then
		CutsceneGui.Enabled = true

		camera.CameraType = Enum.CameraType.Scriptable
		camera.CFrame = camPart.CFrame

		TS:Create(Frame1, Start, {Position = UDim2.new(-0.755, 0, 0.324, 0)}):Play()
		TS:Create(Frame2, Start, {Position = UDim2.new(0.148, 0, -0.502, 0)}):Play()

	elseif Mode == "End" then
		local tween1 = TS:Create(Frame1, End, {Position = UDim2.new(-1.3, 0, 1, 0)})
		local tween2 = TS:Create(Frame2, End, {Position = UDim2.new(0.7, 0, -1.5, 0)})

		tween1:Play()
		tween2:Play()

		local n = 0
		local function gtfo()
			n += 1
			if n == 2 then
				task.spawn(function()
					if camera.CameraType == Enum.CameraType.Scriptable and camera.CFrame == camPart.CFrame then
						task.wait(0.5)
						if player.Character and player.Character:FindFirstChild("Humanoid") then
							camera.CameraSubject = player.Character.Humanoid
						end
						camera.CameraType = Enum.CameraType.Custom
					end

					CutsceneGui.Enabled = false
				end)
			end
		end

		tween1.Completed:Once(gtfo)
		tween2.Completed:Once(gtfo)
	end

end

