local function getTip(char)
	if not char then return nil end
	local rod = char:FindFirstChild("Rod")
	local p1 = rod and rod:FindFirstChild("Particle1")
	if p1 then
		local c = p1:FindFirstChild("cust") or Instance.new("Part", p1)
		c.Name = "cust"; c.Size = Vector3.new(0.2,0.2,0.2); c.Anchored = true; c.CanCollide = false; c.Transparency = 1
		c.CFrame = p1.CFrame * CFrame.new(0, p1.Size.Y/2 + 0.1, 0)
		c.CFrame = CFrame.new(c.Position, c.Position + p1.CFrame.UpVector)
		return c
	end
	return nil
end

local function spawnParticles()
	local vGui = playerGui:FindFirstChild("Vignette")
	if not vGui then return end
	local sets = {
		Size = vGui:GetAttribute("Size") or 0.05,
		Lifetime = vGui:GetAttribute("Lifetime") or 20,
		Color = vGui:GetAttribute("Color") or Color3.new(1,1,1),
		Material = Enum.Material[vGui:GetAttribute("Material") or "Plastic"]
	}
	local targets = {player.Character}
	for _, n in {"Bot", "Bot2"} do
		local b = workspace:FindFirstChild(player.Name..n)
		if b then table.insert(targets, b) end
	end
	if playerGui:FindFirstChild("Syncs") then
		for _, v in playerGui.Syncs:GetChildren() do
			local p = Players:FindFirstChild(v.Name)
			if p and p.Character then table.insert(targets, p.Character) end
		end
	end
	task.spawn(function()
		local wt = 0.35
		for _ = 1, (vGui:GetAttribute("Amount") or 5) do
			for _, char in targets do
				local tip = getTip(char)
				if tip then
					local cf = tip.CFrame * CFrame.Angles(math.rad(rng:NextInteger(-12,12)), math.rad(rng:NextInteger(-15,15)), 0)
					cumEvent:FireServer(tip.CFrame, cf.LookVector * rng:NextInteger(22,30), char, sets)
				end
			end
			task.wait(wt); wt = wt + 0.3
		end
	end)
end

local function effects()
	local f = Instance.new("Frame", gui)
	f.Size = UDim2.new(1,0,1,0); f.BackgroundColor3 = Color3.new(1,0.77,0.91); f.BackgroundTransparency = 0.4
	local oFOV = camera.FieldOfView
	TweenService:Create(camera, TweenInfo.new(1), {FieldOfView = 40}):Play()
	local t = TweenService:Create(f, TweenInfo.new(4), {BackgroundTransparency = 1})
	t:Play(); t.Completed:Connect(function() f:Destroy(); TweenService:Create(camera, TweenInfo.new(1), {FieldOfView = oFOV}):Play() end)
end

RunService.Heartbeat:Connect(function(dt)
	if not isEnabled then 
		return 
	end

	local fol = workspace:FindFirstChild("GoatAnimFol")
	local anim = fol and fol:FindFirstChild(player.Name)
	local speedObj = anim and anim:FindFirstChild("Speed")

	if speedObj then
		timeSinceLastAnim = 0 -- Reset grace period timer since animation is found
		main.Visible = true

		local speed = speedObj.Value
		current = speed > 1 and math.min(MAX_VAL, current + (FILL_RATE * (speed - 1) * dt)) or math.max(0, current - (DRAIN_RATE * dt))

		if current >= MAX_VAL then
			current = 0; blowHard:FireServer("Hard"); spawnParticles(); effects()
			label.Text = "BREEDING!"; task.delay(3, function() label.Text = "AROUSAL" end)
		end
	else
		-- Add delta time to our timer. If it's been missing for more than 0.5 seconds, we assume they truly stopped
		timeSinceLastAnim = timeSinceLastAnim + dt

		if timeSinceLastAnim > 0.5 then
			main.Visible = false
			current = 0
		end
	end

	fill.Size = fill.Size:Lerp(UDim2.new(current/MAX_VAL, 0, 1, 0), 0.1)
end)local button = script.Parent.Parent.Parent.Parent.Parent.Player.MainCenter
